(function (root) {
  'use strict';
  // Общая раскладка боковых выносок. Карточки всех модулей (выноски материалов,
  // заметки) раскладываются СОВМЕСТНО по двум краям viewport и не перекрываются:
  // по отдельности каждый модуль ставил бы свои карточки поверх чужих.
  //
  // Модуль каждый кадр сдаёт свои записи и зовёт layout():
  //   board.set('имя', [{key, x, y, box, line}]);  board.layout(w, h);
  // x, y — экранная точка привязки (px от левого верхнего угла viewport); box —
  // карточка, line — линия-сноска (оба absolute-элементы модуля). Карточки, которым
  // не хватило высоты, прячутся. Прятать записи, не сданные в board, — дело модуля.
  function create() {
    const sources = new Map();
    function layout(w, h) {
      const all = [];
      for (const list of sources.values()) all.push(...list);
      const width = Math.min(200, Math.max(110, w * 0.37)),
        sides = [[], []];
      for (const entry of all) sides[entry.x < w / 2 ? 0 : 1].push(entry);
      for (let side = 0; side < 2; side++) {
        const placed = [];
        let total = 0;
        for (const entry of sides[side].sort(
          (a, b) => a.y - b.y || String(a.key).localeCompare(String(b.key))
        )) {
          const { box, line } = entry;
          box.style.display = 'block';
          box.style.width = width + 'px';
          const height = box.getBoundingClientRect().height;
          if (total + height + 8 > h - 24) {
            box.style.display = 'none';
            line.style.display = 'none';
            continue;
          }
          placed.push({ entry, height });
          total += height + 8;
        }
        let last = 0,
          remaining = total;
        for (const { entry, height } of placed) {
          const { box, line } = entry,
            x = side ? w - width - 8 : 8;
          const y = Math.min(Math.max(entry.y - height / 2, last + 8, 8), h - 8 - remaining);
          last = y + height;
          remaining -= height + 8;
          Object.assign(box.style, { display: 'block', left: x + 'px', top: y + 'px', width: width + 'px' });
          const endX = side ? x : x + width,
            endY = y + height / 2,
            dx = endX - entry.x,
            dy = endY - entry.y;
          line.style.display = 'block';
          line.style.left = entry.x + 'px';
          line.style.top = entry.y + 'px';
          line.style.width = Math.hypot(dx, dy) + 'px';
          line.style.transform = 'rotate(' + Math.atan2(dy, dx) + 'rad)';
        }
      }
    }
    return {
      set(name, entries) {
        sources.set(name, entries || []);
      },
      remove(name) {
        sources.delete(name);
      },
      layout
    };
  }
  const api = {
    board(services) {
      return services.calloutBoard || (services.calloutBoard = create());
    },
    create
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  root.BazisCallouts = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);

