(function (root) {
  'use strict';
  // Independent color dialog: draft changes apply only on confirmation.
  root.BazisColorPicker = {
    open(doc, color, onApply, titleText = 'Цвет материала') {
      const dialog = doc.createElement('dialog');
      dialog.className = 'matColorDialog';
      dialog.setAttribute('aria-label', 'Выбор цвета');
      dialog.style.cssText =
        'width:440px;max-width:calc(100vw - 24px);max-height:85vh;overflow:auto;background:#17232d;color:#e8eef0;border:1px solid #526776;border-radius:10px;padding:16px';
      const title = doc.createElement('h3');
      title.textContent = titleText;
      title.style.margin = '0 0 12px';
      dialog.append(title);
      const palette = doc.createElement('div');
      palette.style.cssText = 'display:grid;grid-template-columns:repeat(8,1fr);gap:5px;margin-bottom:12px';
      dialog.append(palette);
      let h = 0,
        s = 0,
        v = 1;
      const rgb = () => {
        const c = v * s,
          x = c * (1 - Math.abs(((h / 60) % 2) - 1)),
          m = v - c,
          parts =
            h < 60
              ? [c, x, 0]
              : h < 120
                ? [x, c, 0]
                : h < 180
                  ? [0, c, x]
                  : h < 240
                    ? [0, x, c]
                    : h < 300
                      ? [x, 0, c]
                      : [c, 0, x];
        return parts.map(a => Math.round((a + m) * 255));
      };
      const fromHex = value => {
        const a = value.match(/[0-9a-f]{2}/gi).map(x => parseInt(x, 16) / 255),
          max = Math.max(...a),
          min = Math.min(...a),
          d = max - min;
        v = max;
        s = max ? d / max : 0;
        h = !d
          ? 0
          : max === a[0]
            ? 60 * (((a[1] - a[2]) / d) % 6)
            : max === a[1]
              ? 60 * ((a[2] - a[0]) / d + 2)
              : 60 * ((a[0] - a[1]) / d + 4);
        if (h < 0) h += 360;
      };
      const field = doc.createElement('div');
      field.style.cssText =
        'position:relative;height:180px;touch-action:none;background:linear-gradient(to top,#000,transparent),linear-gradient(to right,#fff,transparent)';
      field.tabIndex = 0;
      field.setAttribute('role', 'group');
      field.setAttribute('aria-label', 'Насыщенность и яркость; стрелки для изменения');
      const dot = doc.createElement('span');
      dot.style.cssText =
        'position:absolute;width:12px;height:12px;border:2px solid white;box-shadow:0 0 0 1px #000;border-radius:50%;transform:translate(-50%,-50%);pointer-events:none';
      field.append(dot);
      dialog.append(field);
      const hueLabel = doc.createElement('label');
      hueLabel.textContent = 'Оттенок ';
      const hue = doc.createElement('input');
      hue.type = 'range';
      hue.min = 0;
      hue.max = 359;
      hue.step = 1;
      hue.style.width = '100%';
      hueLabel.append(hue);
      dialog.append(hueLabel);
      const values = doc.createElement('div');
      values.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:10px 0';
      const sample = doc.createElement('span');
      sample.style.cssText = 'width:28px;height:28px;border:1px solid #aaa';
      values.append(sample);
      const hex = doc.createElement('input');
      hex.type = 'text';
      hex.setAttribute('aria-label', 'HEX');
      hex.maxLength = 7;
      hex.style.width = '78px';
      values.append(hex);
      const channels = ['R', 'G', 'B'].map(name => {
        const label = doc.createElement('label');
        label.textContent = name + ' ';
        const input = doc.createElement('input');
        input.type = 'number';
        input.min = 0;
        input.max = 255;
        input.style.width = '45px';
        label.append(input);
        values.append(label);
        return input;
      });
      dialog.append(values);
      function update() {
        const a = rgb(),
          value = '#' + a.map(x => x.toString(16).padStart(2, '0')).join('');
        hex.value = value;
        channels.forEach((e, i) => (e.value = a[i]));
        sample.style.background = value;
        hue.value = h;
        field.style.backgroundColor = `hsl(${h},100%,50%)`;
        dot.style.left = s * 100 + '%';
        dot.style.top = (1 - v) * 100 + '%';
      }
      for (const value of [
        '#ffffff',
        '#cccccc',
        '#888888',
        '#444444',
        '#000000',
        '#804020',
        '#c8ad7f',
        '#f0dfb0',
        '#ff0000',
        '#ff8000',
        '#ffff00',
        '#80ff00',
        '#00cc80',
        '#00ffff',
        '#0080ff',
        '#0000ff',
        '#8000ff',
        '#ff00ff',
        '#ff80c0',
        '#804040',
        '#408040',
        '#404080',
        '#c0c8d0',
        '#f5eee4'
      ]) {
        const b = doc.createElement('button');
        b.type = 'button';
        b.style.cssText = 'height:28px;padding:0;background:' + value;
        b.setAttribute('aria-label', value);
        b.onclick = () => {
          fromHex(value);
          update();
        };
        palette.append(b);
      }
      const point = e => {
        const r = field.getBoundingClientRect();
        s = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
        v = 1 - Math.max(0, Math.min(1, (e.clientY - r.top) / r.height));
        update();
      };
      field.onpointerdown = e => {
        field.setPointerCapture(e.pointerId);
        point(e);
      };
      field.onpointermove = e => {
        if (field.hasPointerCapture(e.pointerId)) point(e);
      };
      field.onkeydown = e => {
        if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
        e.preventDefault();
        s = Math.max(0, Math.min(1, s + (e.key === 'ArrowRight' ? 0.01 : e.key === 'ArrowLeft' ? -0.01 : 0)));
        v = Math.max(0, Math.min(1, v + (e.key === 'ArrowUp' ? 0.01 : e.key === 'ArrowDown' ? -0.01 : 0)));
        update();
      };
      hue.oninput = () => {
        h = Number(hue.value);
        update();
      };
      hex.onchange = () => {
        if (/^#[0-9a-f]{6}$/i.test(hex.value)) {
          fromHex(hex.value);
          update();
        } else update();
      };
      channels.forEach(
        e =>
          (e.onchange = () => {
            if (
              channels.every(
                c => c.value !== '' && Number.isFinite(+c.value) && +c.value >= 0 && +c.value <= 255
              )
            ) {
              fromHex('#' + channels.map(c => Math.round(+c.value).toString(16).padStart(2, '0')).join(''));
            }
            update();
          })
      );
      const buttons = doc.createElement('div');
      buttons.style.cssText = 'display:flex;justify-content:flex-end;gap:8px';
      for (const [text, run] of [
        ['Отмена', () => dialog.close()],
        [
          'Применить',
          () => {
            onApply(hex.value);
            dialog.close();
          }
        ]
      ]) {
        const b = doc.createElement('button');
        b.textContent = text;
        b.onclick = run;
        buttons.append(b);
      }
      dialog.append(buttons);
      dialog.addEventListener('close', () => dialog.remove());
      doc.body.append(dialog);
      fromHex(color);
      update();
      dialog.showModal();
      return dialog;
    }
  };
})(typeof globalThis !== 'undefined' ? globalThis : this);

