(function (root) {
  'use strict';
  function install(context, bundle) {
    const { hooks, document: doc, window: win, THREE: T } = context;
    if (bundle?.schema !== 1) throw new Error('Несовместимый модуль сохранения HTML');
    // First registry entry: no generated menus, labels or canvases are copied.
    const snapshot = () => doc.documentElement?.outerHTML || '';
    const original = root.BazisI18n ? root.BazisI18n.untranslated(snapshot) : snapshot();
    const inputs = doc.querySelectorAll
      ? Array.from(doc.querySelectorAll('input[id]'))
          .filter(e => e.type === 'checkbox' || e.type === 'range')
          .map(e => e.id)
      : [];
    // Кнопок у модуля нет (решение владельца 24.09.2026: локальная копия у него есть,
    // правки идут только на GitHub — дискеткой github_save). Остаётся общий API:
    // capture/applyState нужны дискетке и восстановлению вида, download — проверкам.
    // Последнее сообщение (восстановление вида, сохранение) — в свойстве message.
    const status = { textContent: '' };
    let restored = false,
      disposed = false;
    function capture() {
      const v = win.__viewer;
      if (!v) throw new Error('Модель ещё загружается');
      const features = {};
      for (const f of v.features) if (f.serialize) features[f.name] = f.serialize();
      const controls = {};
      for (const id of inputs) {
        const e = doc.getElementById(id);
        controls[id] = e.type === 'checkbox' ? e.checked : e.value;
      }
      const boxes = Array.from(doc.querySelectorAll('#layerControls input'));
      // Слои — по имени: после правки модели порядок и число слоёв могут поменяться.
      // Массив по номеру оставлен для старых читателей.
      const layers = boxes.map(e => e.checked),
        layersByName = {};
      for (const e of boxes) {
        const name = e.getAttribute('aria-label');
        if (name) layersByName[name] = e.checked;
      }
      return {
        schema: 1,
        source: context.data.source_sha256,
        savedAt: new Date().toISOString(),
        features,
        controls,
        layers,
        layersByName,
        camera: {
          position: v.camera.position.toArray(),
          target: v.controls.target.toArray(),
          up: v.camera.up.toArray()
        },
        dimensions: v.dimensions.map(r => ({
          a: r.a.toArray(),
          b: r.b.toArray(),
          ...(/^#[0-9a-f]{6}$/i.test(r.color) ? { color: r.color } : {})
        }))
      };
    }
    function buildHtml() {
      const state = capture();
      if (!original) throw new Error('Исходный HTML недоступен');
      const copy = new win.DOMParser().parseFromString(original, 'text/html');
      copy.getElementById('viewerSavedState')?.remove();
      const script = copy.createElement('script');
      script.id = 'viewerSavedState';
      script.type = 'application/json';
      script.textContent = JSON.stringify(state).replace(/</g, '\\u003c');
      copy.head.append(script);
      return '<!DOCTYPE html>\n' + copy.documentElement.outerHTML;
    }
    function download() {
      try {
        const blob = new win.Blob([buildHtml()], { type: 'text/html;charset=utf-8' }),
          url = win.URL.createObjectURL(blob);
        const rp2 = context.data && context.data.republish;
        const base =
          rp2 && rp2.slug
            ? rp2.slug
            : (context.data.source || 'Модель').replace(/\.[^.]+$/, '') + '_изменено';
        const a = doc.createElement('a');
        a.href = url;
        a.download = base + '.html';
        doc.body.append(a);
        a.click();
        a.remove();
        win.setTimeout(() => win.URL.revokeObjectURL(url), 10000);
        status.textContent = 'Копия HTML подготовлена';
      } catch (error) {
        status.textContent = 'Не удалось сохранить: ' + error.message;
      }
    }
    // Применить снимок настроек. Мягко: снимок мог быть сделан на ПРЕЖНЕЙ версии
    // модели (после перезаливки из БАЗИСа контрольная сумма другая). Тогда применяем
    // всё, что подходит, а что не подошло — пропускаем, не роняя остальное. Повторный
    // вызов не задваивает замеры: сначала убираем прежние ручные.
