            e.dispatchEvent(new win.Event('input'));
          }
        }
      });
      safe('layers', () => {
        const boxes = Array.from(doc.querySelectorAll('#layerControls input'));
        const set = (e, on) => {
          if (typeof on !== 'boolean') return;
          e.checked = on;
          e.dispatchEvent(new win.Event('change'));
        };
        if (s.layersByName)
          for (const e of boxes) {
            const name = e.getAttribute('aria-label');
            if (name && Object.prototype.hasOwnProperty.call(s.layersByName, name))
              set(e, s.layersByName[name]);
          }
        else if (same) boxes.forEach((e, i) => set(e, s.layers?.[i])); // старый формат по номеру — только для той же модели
      });
      for (const f of v.features)
        if (f.restore && Object.prototype.hasOwnProperty.call(s.features || {}, f.name))
          safe(f.name, () => f.restore(s.features[f.name]));
      const vector = a => Array.isArray(a) && a.length === 3 && a.every(Number.isFinite);
      safe('dimensions', () => {
        if (v.dimensions.length) doc.getElementById('clearMeasures')?.onclick?.();
        for (const d of s.dimensions || [])
          if (vector(d.a) && vector(d.b)) {
            const rec = v.addDimension(new T.Vector3(...d.a), new T.Vector3(...d.b));
            if (rec && /^#[0-9a-f]{6}$/i.test(d.color)) rec.color = d.color;
          }
      });
      safe('camera', () => {
        if (s.camera && [s.camera.position, s.camera.target, s.camera.up].every(vector)) {
          v.camera.position.fromArray(s.camera.position);
          v.camera.up.fromArray(s.camera.up);
          v.controls.target.fromArray(s.camera.target);
          v.controls.update();
