      });
      applied = { savedAt: s.savedAt || null, same, skipped };
      return applied;
    }
    const describe = result =>
      (result.same
        ? 'Настройки вида применены'
        : 'Модель изменилась после сохранения — применены подходящие настройки') +
      (result.skipped.length ? ' (пропущено: ' + result.skipped.join(', ') + ')' : '');
    let applied = null;
    function embeddedState() {
      const script = doc.getElementById('viewerSavedState');
      return script ? JSON.parse(script.textContent) : null;
    }
    function restore() {
      if (restored || disposed || !win.__viewer) return;
      restored = true;
      try {
        const s = embeddedState();
        if (!s) return;
        status.textContent = describe(applyState(s));
