(function (root) {
  'use strict';
  // Перевод интерфейса. Код модулей и шаблон пишут по-русски; этот модуль подменяет
  // текст на выбранный язык прямо в странице — в узлах текста и в атрибутах title,
  // aria-label, placeholder, alt, data-label, data-compact-label — и следит за
  // новыми (MutationObserver).
  // Словари — i18n.json модулей: {"русская строка": {"uk","en","pl"}}; реестр
  // вклеивает их в код, и они копятся в BazisI18nData. Строка ищется целиком, а
  // составная («Есть новая версия: … (у страницы — …)») — по известным фрагментам.
  // Данные модели (названия деталей, материалов, текст заметок) не переводятся:
  // их контейнеры помечены стандартным translate="no" (el.translate = false), а
  // элемент с data-i18n-skip — только его атрибуты (title с названием детали).
  // Для текста вне DOM (рисунок на холсте) — BazisI18n.t(строка) и onChange.

  const LANGUAGES = [
    ['ru', 'Русский'], // i18n-ignore — название языка на нём самом
    ['uk', 'Українська'], // i18n-ignore
    ['en', 'English'],
    ['pl', 'Polski']
  ];
  const CODES = LANGUAGES.map(l => l[0]),
    SOURCE = 'ru',
    KEY = 'bazisLang',
    CYR = /[А-Яа-яЁёІіЇїЄєҐґ]/,
    LETTER = 'А-Яа-яЁёІіЇїЄєҐґA-Za-z0-9', // i18n-ignore — класс букв
    // data-label, data-compact-label — подписи, которые CSS выводит через attr()
    ATTRS = ['title', 'aria-label', 'placeholder', 'alt', 'data-label', 'data-compact-label'],
    SKIP = new Set(['SCRIPT', 'STYLE', 'TEXTAREA', 'NOSCRIPT', 'CODE', 'PRE']);

  const dict = new Map(); // русская строка → {uk, en, pl}
  const texts = new WeakMap(); // узел текста → {ru, shown}
  const attrs = new WeakMap(); // элемент → Map(атрибут → {ru, shown})
  const listeners = new Set();
  let lang = SOURCE,
    fragments,
    observer = null,
    started = false;

  function add(entries) {
    for (const [ru, tr] of Object.entries(entries || {})) dict.set(ru, tr);
    fragments = undefined;
    if (started) refresh();
  }
  // Словари модулей, вклеенных раньше этого, уже лежат массивом; дальнейшие — сюда.
  const queued = Array.isArray(root.BazisI18nData) ? root.BazisI18nData : [];
  root.BazisI18nData = { push: add };
  queued.forEach(add);

  const escape = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  function fragmentPattern() {
    if (fragments === undefined) {
      const keys = [...dict.keys()].filter(k => k.length > 1).sort((a, b) => b.length - a.length);
      // граница слова — только со стороны, где фрагмент начинается/кончается буквой:
      // «. Обновление…» после «…5a2» или «…страницу (» перед «models/» тоже фрагменты
      const edge = new RegExp('[' + LETTER + ']');
      const alternative = k =>
        (edge.test(k[0]) ? '(?<![' + LETTER + '])' : '') +
        escape(k) +
        (edge.test(k[k.length - 1]) ? '(?![' + LETTER + '])' : '');
      fragments = keys.length ? new RegExp(keys.map(alternative).join('|'), 'g') : null;
    }
    return fragments;
  }
  // Перевод строки на текущий язык. Края (пробелы) сохраняются. Нет перевода — как есть.
  function translate(ru, to = lang) {
    if (to === SOURCE || !ru || !CYR.test(ru)) return ru;
    const core = ru.trim(),
      entry = dict.get(core);
    if (entry && entry[to]) return ru.replace(core, () => entry[to]);
    const pattern = fragmentPattern();
    return pattern ? ru.replace(pattern, m => dict.get(m)?.[to] || m) : ru;
  }
  // t('Шаблон {0} из {1}', a, b) — для текста, который не лежит в DOM
  function t(ru, ...args) {
    let text = translate(ru);
    args.forEach((value, i) => {
      text = text.split('{' + i + '}').join(String(value));
    });
    return text;
  }

  // Форма слова при числе: модуль даёт три русские формы (1 / 2–4 / 5+), а форма
  // выбирается по правилам ВЫБРАННОГО языка — русская 21 «отверстие», польская 21
  // «otworów»; выбранную форму затем переводит словарь.
  function plural(n, one, few, many) {
    let rule = 'many';
    try {
      rule = new Intl.PluralRules(lang).select(Math.abs(Number(n)));
    } catch (e) {}
    return rule === 'one' ? one : rule === 'few' ? few : many;
  }

  const excluded = el => !el || SKIP.has(el.tagName) || !!el.closest('[translate="no"]');
  function doText(node) {
    if (excluded(node.parentElement)) return;
    const value = node.nodeValue,
      rec = texts.get(node);
    let ru = value;
    if (rec && value === rec.shown)
      ru = rec.ru; // наш же перевод — берём исходник
    else if (!CYR.test(value)) return texts.delete(node);
    const shown = translate(ru);
    texts.set(node, { ru, shown });
    if (shown !== value) node.nodeValue = shown;
  }
  function doAttr(el, name) {
    // у атрибутов исключение одно — translate="no": placeholder поля ввода переводим,
    // хотя сам текст в поле (TEXTAREA) — нет
    if (!el || el.closest('[translate="no"]') || el.hasAttribute('data-i18n-skip')) return;
    const value = el.getAttribute(name);
    if (value == null) return;
    let map = attrs.get(el);
    const rec = map && map.get(name);
    let ru = value;
    if (rec && value === rec.shown) ru = rec.ru;
    else if (!CYR.test(value)) return map && map.delete(name);
    const shown = translate(ru);
    if (!map) attrs.set(el, (map = new Map()));
    map.set(name, { ru, shown });
    if (shown !== value) el.setAttribute(name, shown);
  }
  function walk(node) {
    if (!node) return;
    if (node.nodeType === 3) return doText(node);
    if (node.nodeType !== 1 && node.nodeType !== 9 && node.nodeType !== 11) return;
    const doc = node.ownerDocument || node,
      it = doc.createTreeWalker(node, 4); // NodeFilter.SHOW_TEXT
    for (let text = it.nextNode(); text; text = it.nextNode()) doText(text);
    const selector = ATTRS.map(a => '[' + a + ']').join(',');
    if (node.nodeType === 1 && node.matches(selector)) for (const a of ATTRS) doAttr(node, a);
    for (const el of node.querySelectorAll(selector)) for (const a of ATTRS) doAttr(el, a);
  }
  let title = null;
  function refresh() {
    const doc = root.document;
    if (!doc || !doc.body) return;
    walk(doc.body);
    // заголовок вкладки: «<модель> · просмотр модели»
    if (title === null) title = doc.title;
    doc.title = translate(title);
  }

  function detect() {
    const pick = code => (CODES.includes(code) ? code : null);
    const url = new root.URLSearchParams(root.location?.search || '').get('lang');
    let saved = null;
    try {
      saved = root.localStorage.getItem(KEY);
    } catch (e) {}
    if (pick(url)) return url;
    if (pick(saved)) return saved;
    // Язык браузера — только у живого пользователя: у автоматических проверок
    // (navigator.webdriver) остаётся язык сборки, иначе их ожидания поплыли бы.
    if (!root.navigator?.webdriver)
      for (const tag of root.navigator?.languages || [root.navigator?.language || '']) {
        const code = pick(String(tag).slice(0, 2).toLowerCase());
        if (code) return code;
      }
    return SOURCE;
  }

  function setLanguage(code, remember = true) {
    if (!CODES.includes(code)) return lang;
    lang = code;
    if (remember)
      try {
        root.localStorage.setItem(KEY, code);
      } catch (e) {}
    if (root.document) root.document.documentElement.lang = code;
    refresh();
    for (const fn of listeners) fn(code);
    return lang;
  }
  // Выполнить fn на русском исходнике страницы (снимок html_save, отладка) и вернуть язык.
  function untranslated(fn) {
    if (lang === SOURCE) return fn();
    const current = lang;
    lang = SOURCE;
    refresh();
    try {
      return fn();
    } finally {
      lang = current;
      refresh();
    }
  }
  function start() {
    // без живого DOM (заглушки проверок, старые браузеры) переводчик не включается —
    // страница остаётся на русском, а не падает
    const doc = root.document;
    if (started || !doc?.body || typeof root.MutationObserver !== 'function' || !doc.createTreeWalker) return;
    started = true;
    observer = new root.MutationObserver(records => {
      for (const r of records) {
        if (r.type === 'characterData') doText(r.target);
        else if (r.type === 'attributes') doAttr(r.target, r.attributeName);
        else for (const node of r.addedNodes) walk(node);
      }
    });
    observer.observe(root.document.body, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: ATTRS
    });
    setLanguage(detect(), false);
  }

  root.BazisI18n = {
    languages: LANGUAGES,
    t,
    translate,
    plural,
    setLanguage,
    untranslated,
    onChange(fn) {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
    get language() {
      return lang;
    },
    get size() {
      return dict.size;
    }
  };
  // Все скрипты модулей лежат в одном <script>: к микрозадаче словари всех модулей
  // уже на месте — переводим страницу до установки модулей, без мигания русским.
  if (root.document && typeof root.queueMicrotask === 'function') root.queueMicrotask(start);

  function install(context, data) {
    const { document: doc, hooks } = context;
    if (data?.schema !== 1) throw new Error('Несовместимый модуль перевода');
    start();
    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const control = doc.getElementById('langControl'),
      menu = doc.getElementById('langMenu'),
      code = doc.getElementById('langCode'),
      choices = [...(doc.getElementById('langControl').querySelectorAll?.('[data-lang]') || [])];
    for (const button of choices)
      button.onclick = () => {
        setLanguage(button.dataset.lang);
        menu.open = false;
      };
    const sync = current => {
      code.textContent = current.toUpperCase();
      for (const button of choices)
        button.setAttribute('aria-pressed', String(button.dataset.lang === current));
    };
    sync(lang);
    listeners.add(sync);
    // Кнопка языка — на виду, справа в верхней строке перед дискетой GitHub (а не в
    // меню, куда не заглядывают); список — в общем слое, его даёт toolbar.
    let disposeMenu = null;
    const place = () => {
      const bar = context.toolbarMount || context.toolMount,
        floppy = doc.querySelector?.('#githubSaveTools'); // дискеты может не быть
      if (floppy && floppy.parentElement === bar && bar.insertBefore) bar.insertBefore(control, floppy);
      else bar.append(control);
      disposeMenu = context.services?.portalToolMenu?.(menu) || null;
    };
    hooks.ready.push(place);
    return {
      name: 'i18n',
      setLanguage,
      t,
      get language() {
        return lang;
      },
      dispose() {
        listeners.delete(sync);
        disposeMenu?.();
        const i = hooks.ready.indexOf(place);
        if (i >= 0) hooks.ready.splice(i, 1);
        control.remove();
        doc.querySelector?.('style[data-feature="i18n"]')?.remove();
      }
    };
  }
  const api = { install, translate: (ru, to) => translate(ru, to) };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'i18n', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

