  display: block;
  width: 100%;
  margin: 0 0 4px;
  text-align: left;
}
.langList button:last-child {
  margin-bottom: 0;
}

scripts:
(function (root) {
  'use strict';
  function install(context, data) {
    const { document: doc, window: win, hooks } = context;
    if (data?.schema !== 1) throw new Error('Несовместимый модуль сохранения в GitHub');
    const KEY = 'bazisGhToken';
    // Настройки вида живут ОТДЕЛЬНЫМ файлом рядом с моделью: models/<слаг>/view.json.
    // Перезаливка модели из БАЗИСа пишет только index.html, поэтому настройки,
    // выставленные на странице, переживают правку модели.
    const settingsPath = data.path.replace(/[^/]+$/, 'view.json'),
      CACHE = 'bazisViewState:' + settingsPath;
    let disposed = false,
      dialog = null;

    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const button = doc.getElementById('saveGithub');
    button.title = 'Сохранить настройки вида в опубликованную страницу (' + settingsPath + ')';
    const status = doc.getElementById('githubSaveStatus');
    const wrap = doc.getElementById('githubSaveTools');
    (context.toolbarMount || context.toolMount).append(wrap);
    dialog = doc.getElementById('githubTokenDialog');
    doc.getElementById('githubTokenRepo').textContent = data.repo;
    doc.body.append(dialog);

    // Токен живёт ТОЛЬКО в браузере владельца. В сохраняемый HTML он попасть не может:
    // у модуля намеренно нет serialize(), который обходит html_save.
    const readToken = () => {
      try {
        return win.localStorage.getItem(KEY) || '';
      } catch (e) {
        return '';
      }
    };
    const writeToken = v => {
      try {
        v ? win.localStorage.setItem(KEY, v) : win.localStorage.removeItem(KEY);
      } catch (e) {}
    };

    // base64 от UTF-8 порциями: apply() на мегабайтном массиве переполняет стек.
    function toBase64(text) {
      const bytes = new win.TextEncoder().encode(text);
      let binary = '';
      for (let i = 0; i < bytes.length; i += 0x8000)
        binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
      return win.btoa(binary);
    }

    // cache:'no-store' обязательно: GitHub API отдаёт ответы с max-age=60, и без
    // этого браузер вернул бы вершину ветки минутной давности. Коммит на старой
    // вершине GitHub отклоняет с 422 «Update is not a fast forward».
    function request(token, path, options) {
      return win
        .fetch(
          'https://api.github.com/repos/' + data.owner + '/' + data.repo + path,
          Object.assign({ cache: 'no-store' }, options || {}, {
            headers: Object.assign(
              {
                Accept: 'application/vnd.github+json',
                'Content-Type': 'application/json',
                Authorization: 'Bearer ' + token
              },
              (options || {}).headers || {}
            )
          })
        )
        .then(response => {
          if (response.ok) return response.json();
          return response.text().then(text => {
            const fail = message => {
              const error = new Error(message);
              error.status = response.status;
              throw error;
            };
            if (response.status === 401) fail('Токен не принят (401). Проверь токен и срок его действия.');
            if (response.status === 403)
              fail('Нет прав на запись (403). Нужен токен на ' + data.repo + ' с Contents: Read and write.');
            if (response.status === 404)
              fail('Не найдены репозиторий или ветка (404). Проверь доступ токена.');
            if (response.status === 422)
              fail('Ветка на GitHub меняется прямо сейчас (422). Повтори сохранение через минуту.');
            fail(response.status + ': ' + text.slice(0, 200));
          });
        });
    }

    // Git Data API (blob → tree → commit → ref): Contents API на файлах больше
    // мегабайта капризничает, а собранная страница как раз такая.
    // В gh-pages пишут и страница, и выгрузка из БАЗИСа. Если ветка сдвинулась,
    // пока мы собирали коммит, GitHub отвечает 422 — тогда перечитываем вершину и
    // строим коммит заново поверх неё. Файлы (blob) при этом не заливаем снова.
    // entries: [{path, content (текст) | base64 (двоичный) | remove: true}] — всё одним
    // коммитом: view.json вместе с фото заметок и удалением ненужных.
    const ATTEMPTS = 4;
    async function commit(token, entries, message) {
      const tree = [];
      for (const entry of entries) {
        if (entry.remove) {
          tree.push({ path: entry.path, mode: '100644', type: 'blob', sha: null });
          continue;
        }
        const blob = await request(token, '/git/blobs', {
          method: 'POST',
          body: JSON.stringify({ content: entry.base64 || toBase64(entry.content), encoding: 'base64' })
        });
        tree.push({ path: entry.path, mode: '100644', type: 'blob', sha: blob.sha });
      }
      for (let attempt = 1; ; attempt++) {
        const ref = await request(token, '/git/ref/heads/' + data.branch),
          base = ref.object.sha;
        const head = await request(token, '/git/commits/' + base);
        const madeTree = await request(token, '/git/trees', {
          method: 'POST',
          body: JSON.stringify({ base_tree: head.tree.sha, tree })
        });
        const made = await request(token, '/git/commits', {
          method: 'POST',
          body: JSON.stringify({
            message: message || 'Обнови ' + entries[0].path + ' из просмотрщика',
            tree: madeTree.sha,
            parents: [base]
          })
        });
        try {
          await request(token, '/git/refs/heads/' + data.branch, {
            method: 'PATCH',
            body: JSON.stringify({ sha: made.sha })
          });
          return made.sha;
        } catch (error) {
          if (error.status !== 422 || attempt >= ATTEMPTS) throw error;
          status.textContent = 'Ветка изменилась, пересобираю коммит… (' + attempt + ')';
        }
      }
    }

    function askToken() {
      return new Promise(resolve => {
        const input = doc.getElementById('githubTokenInput'),
          box = doc.getElementById('githubTokenRemember');
        input.value = '';
        box.checked = true;
        const finish = value => {
          try {
            dialog.close();
          } catch (e) {}
          // токен не должен оставаться в DOM страницы после закрытия окна
          input.value = '';
          doc.getElementById('githubTokenOk').onclick = null;
          doc.getElementById('githubTokenCancel').onclick = null;
          dialog.oncancel = null;
          resolve(value);
        };
        doc.getElementById('githubTokenOk').onclick = () => {
          const value = input.value.trim();
          if (box.checked && value) writeToken(value);
          finish(value);
        };
        doc.getElementById('githubTokenCancel').onclick = () => finish('');
        dialog.oncancel = event => {
          event.preventDefault();
          finish('');
        };
        dialog.showModal ? dialog.showModal() : dialog.setAttribute('open', '');
        input.focus();
      });
    }

    async function tokenOrAsk() {
      const token = readToken() || (await askToken());
      if (!token) status.textContent = 'Отменено.';
      return token;
    }

    // Запись любого файла в ветку публикации тем же токеном — для других модулей
    // (обновление просмотрщика пишет так свою страницу). Токен наружу не отдаётся.
    async function commitFile(path, content, message) {
      if (disposed) return null;
      const token = await tokenOrAsk();
      if (!token) return null;
      try {
        return await commit(token, [{ path, content }], message);
      } catch (error) {
        if (/\b401\b|\b403\b/.test(error.message)) writeToken(''); // негодный токен не держим
        throw error;
      }
    }

    // Файлы модулей рядом со страницей (фото заметок): модуль отдаёт attachments() —
    // {dir, files:[{name, base64?}]}: в <папка страницы>/<dir>/ должны лежать ровно
    // эти файлы, base64 — у новых. Лишние из этой папки удаляются тем же коммитом.
    const SAFE_DIR = /^[a-z_]+$/,
      SAFE_FILE = /^[0-9a-z_-]+\.(jpg|png|webp)$/;
    async function listDir(token, dir) {
      try {
        const items = await request(
          token,
          '/contents/' +
            dir.split('/').map(encodeURIComponent).join('/') +
            '?ref=' +
            encodeURIComponent(data.branch)
        );
        return Array.isArray(items) ? items.filter(i => i.type === 'file').map(i => i.name) : [];
      } catch (error) {
        if (error.status === 404) return []; // папки ещё нет
        throw error;
      }
    }
    async function attachmentEntries(token) {
      const entries = [],
        uploaded = [],
        base = settingsPath.replace(/[^/]+$/, '');
      for (const feature of (win.__viewer && win.__viewer.features) || []) {
        const set = feature.attachments?.();
        if (!set || !SAFE_DIR.test(set.dir)) continue;
        const folder = base + set.dir,
          keep = new Set(),
          fresh = [];
        for (const file of set.files || []) {
          if (!SAFE_FILE.test(file.name)) continue;
          keep.add(file.name);
          if (file.base64) {
            entries.push({ path: folder + '/' + file.name, base64: file.base64 });
            fresh.push(file.name);
          }
        }
        for (const name of await listDir(token, folder))
          if (!keep.has(name) && SAFE_FILE.test(name))
            entries.push({ path: folder + '/' + name, remove: true });
        uploaded.push([feature, fresh]);
      }
      return { entries, uploaded };
    }

    async function save() {
      if (disposed) return null;
      const token = await tokenOrAsk();
      if (!token) return null;
      const saver = ((win.__viewer && win.__viewer.features) || []).find(f => f.name === 'html_save');
      if (!saver || !saver.capture) {
        status.textContent = 'Модуль сохранения HTML недоступен.';
        return null;
      }
      button.disabled = true;
      status.textContent = 'Сохраняю на GitHub…';
      try {
        const state = saver.capture();
        const { entries, uploaded } = await attachmentEntries(token);
        const sha = await commit(
          token,
          [{ path: settingsPath, content: JSON.stringify(state, null, 1) }, ...entries],
          'Обнови ' + settingsPath + ' из просмотрщика'
        );
        for (const [feature, names] of uploaded) feature.attachmentsSaved?.(names);
        // Своя копия в браузере: GitHub Pages выкладывает файл ~минуту, а обновить
        // страницу владелец может и раньше — тогда возьмётся эта, более свежая.
        try {
          win.localStorage.setItem(CACHE, JSON.stringify(state));
        } catch (e) {}
        status.textContent =
          'Настройки вида сохранены (коммит ' + sha.slice(0, 7) + '). Перезаливка модели их не сотрёт.';
        return sha;
      } catch (error) {
        status.textContent = error.message;
        if (/\b401\b|\b403\b/.test(error.message)) writeToken(''); // негодный токен не держим
        return null;
      } finally {
        if (!disposed) button.disabled = false;
      }
    }

    // При открытии опубликованной страницы берём самый свежий снимок настроек:
    // файл view.json с сайта, копию в этом браузере (после своего сохранения) или
    // снимок, вшитый в сам HTML (старые сохранения и перетащенные файлы). Вшитый
    // html_save уже применил сам — поверх кладём, только если есть что-то новее.
    let loaded = false;
    async function loadSettings() {
      const saver = ((win.__viewer && win.__viewer.features) || []).find(f => f.name === 'html_save');
      if (!saver || !saver.applyState) return null;
      let remote = null;
      if (/^https?:$/.test((win.location && win.location.protocol) || ''))
        // с диска соседний файл не прочитать
        try {
          const response = await win.fetch('view.json?t=' + Date.now(), { cache: 'no-store' });
          if (response.ok) remote = await response.json();
        } catch (e) {}
      let local = null;
      try {
        local = JSON.parse(win.localStorage.getItem(CACHE) || 'null');
      } catch (e) {}
      let embedded = null;
      try {
        embedded = saver.embeddedState();
      } catch (e) {}
      const stamp = s => String((s && s.savedAt) || '');
      const best = [remote, local]
        .filter(s => s && s.schema === 1)
        .sort((a, b) => stamp(b).localeCompare(stamp(a)))[0];
      if (!best || (embedded && stamp(embedded) >= stamp(best))) return null;
      try {
        const result = saver.applyState(best);
        status.textContent = saver.describe(result) + (best === remote ? ' (из сохранённых на GitHub)' : '');
        return result;
      } catch (error) {
        status.textContent = 'Не удалось применить сохранённые настройки: ' + error.message;
        return null;
      }
    }
    // Ждём, пока html_save применит вшитый снимок, — иначе наш применился бы первым
    // и был бы перетёрт более старым.
    const waitForRestore = () => {
      if (loaded || disposed) return;
      const saver = ((win.__viewer && win.__viewer.features) || []).find(f => f.name === 'html_save');
      // В первом кадре __viewer ещё не назначен — это «ждать», а не «применять».
      if (!saver || !saver.restored) return;
      loaded = true;
      const i = hooks.frame.indexOf(waitForRestore);
      if (i >= 0) hooks.frame.splice(i, 1);
      loadSettings();
    };
    hooks.frame.push(waitForRestore);

    button.onclick = save;
    // Намеренно БЕЗ serialize(): html_save обходит features и вшил бы токен в файл.
    return {
      name: 'github_save',
      save,
      commitFile,
      loadSettings,
      target: settingsPath,
      page: data.path,
      hasToken: () => !!readToken(),
      forgetToken: () => {
        writeToken('');
        status.textContent = 'Токен удалён из браузера.';
      },
      dispose() {
        disposed = true;
        const i = hooks.frame.indexOf(waitForRestore);
        if (i >= 0) hooks.frame.splice(i, 1);
        wrap.remove();
        doc.querySelector?.('style[data-feature="github_save"]')?.remove();
        if (dialog) {
          dialog.remove();
          dialog = null;
        }
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'github_save', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

