scripts:
(function (root) {
  'use strict';
  function install(context) {
    const { document: doc, services, hooks, toolbarMount } = context,
      rows = [],
      win = context.window || root,
      portalDisposers = [];
    // Постоянная разметка — markup.html (сборщик кладёт её в #featureMarkup); строки
    // функций (createToolRow) и подсказки «?» создаются по вызову и остаются в коде.
    const modules = doc.getElementById('functionalModules');
    toolbarMount.append(modules);
    let viewerMenu = null,
      menuOutside = null,
      menuEscape = null,
      mobileStructure = null,
      closeStructure = null,
      structureEscape = null;
    // Строки функций прокручиваются и потому обрезают обычный absolute-попап.
    // На время открытия переносим попап в body и привязываем к его summary.
    // options.anchor — элемент, от которого окно отмеряет верх/низ (по умолчанию сама
    // кнопка). Меню внутри строки инструментов передают строку: окно открывается под
    // строкой целиком и не закрывает её остальные элементы (на узком экране строка
    // переносится, и под кнопкой оказываются её же галочки).
    services.portalToolMenu = (menu, options = {}) => {
      const popup = menu?.querySelector?.(':scope > .toolPopup');
      if (!popup) return () => {};
      const originalStyle = popup.style.cssText,
        marker = doc.createComment('tool popup'),
        summary = menu.querySelector('summary');
      let portaled = false;
      const place = () => {
        if (!portaled || !menu.open) return;
        const s = summary.getBoundingClientRect(),
          v = (options.anchor || summary).getBoundingClientRect(),
          a = {
            left: s.left,
            right: s.right,
            top: Math.min(s.top, v.top),
            bottom: Math.max(s.bottom, v.bottom)
          },
          margin = 10,
          gap = 6,
          mobile = win.innerWidth <= 760;
        popup.style.visibility = 'hidden';
        popup.style.display = 'block';
        popup.style.maxWidth = win.innerWidth - margin * 2 + 'px';
        popup.style.width = mobile ? win.innerWidth - margin * 2 + 'px' : '282px';
        const box = popup.getBoundingClientRect(),
          below = win.innerHeight - a.bottom - gap,
          above = a.top - gap,
          useBelow = below >= Math.min(box.height, 220) || below >= above,
          available = Math.max(80, useBelow ? below : above);
        const top = useBelow
          ? a.bottom + gap
          : Math.max(margin, a.top - gap - Math.min(box.height, available));
        let left = mobile
          ? margin
          : popup.classList.contains('toolPopupRight')
            ? a.right - box.width
            : a.left;
        left = Math.max(margin, Math.min(left, win.innerWidth - box.width - margin));
        Object.assign(popup.style, {
          left: left + 'px',
          top: top + 'px',
          maxHeight: available + 'px',
          visibility: 'visible'
        });
      };
      const restore = () => {
        if (!portaled) return;
        marker.replaceWith(popup);
        popup.classList.remove('toolPopupPortal');
        popup.style.cssText = originalStyle;
        delete popup._toolMenuOwner;
        portaled = false;
      };
      const toggle = () => {
        if (menu.open && !portaled) {
          popup.replaceWith(marker);
          popup._toolMenuOwner = menu;
          popup.classList.add('toolPopupPortal');
          doc.body.append(popup);
          portaled = true;
          place();
        } else if (!menu.open) restore();
      };
      menu.addEventListener('toggle', toggle);
      win.addEventListener('resize', place);
      win.addEventListener('scroll', place, true);
      const dispose = () => {
        menu.removeEventListener('toggle', toggle);
        win.removeEventListener('resize', place);
        win.removeEventListener('scroll', place, true);
        restore();
      };
      portalDisposers.push(dispose);
      return dispose;
    };
    services.createToolRow = (id, title, onToggle) => {
      const button = doc.createElement('button');
      button.type = 'button';
      button.id = id;
      button.textContent = title;
      button.setAttribute('aria-expanded', 'false');
      const row = doc.createElement('div');
      row.id = id + 'Tools';
      row.className = 'toolGroup featureRow';
      row.hidden = true;
      button.setAttribute('aria-controls', row.id);
      const setOpen = value => {
        row.hidden = !value;
        if (!value) for (const menu of row.querySelectorAll('.toolMenu[open]')) menu.open = false;
        button.setAttribute('aria-expanded', String(!!value));
        button.setAttribute('aria-pressed', String(!!value));
      };
      button.onclick = () => {
        const value = row.hidden;
        setOpen(value);
        if (onToggle) onToggle(value);
      };
      modules.append(button);
      toolbarMount.append(row);
      const result = { button, row, setOpen, onToggle };
      rows.push(result);
      return result;
    };
    function helpFor(nodes) {
      const help = doc.createElement('details'),
        summary = doc.createElement('summary'),
        body = doc.createElement('div');
      help.className = 'compactHelp';
      summary.textContent = '?';
      summary.setAttribute('aria-label', 'Подсказка');
      body.append(...nodes);
      help.append(summary, body);
      return help;
    }
    const ready = () => {
      const side = doc.querySelector?.('#toggleSide');
      if (side) {
        const menu = doc.getElementById('viewerMenu'),
          toggle = doc.getElementById('viewerMenuToggle'),
          body = doc.getElementById('viewerMenuPopup'),
          display = doc.getElementById('displayPanel'),
          displayItems = doc.getElementById('viewerMenuDisplay'),
          selection = doc.getElementById('selectionPanel'),
          selectionTools = doc.getElementById('selectionTools'),
          fit = doc.getElementById('fit'),
          views = fit?.parentElement,
          opacity = display.querySelector('.opacityTool'),
          label = display.querySelector('.blockLabel');
        viewerMenu = menu;
        const setOpen = value => {
          body.hidden = !value;
          if (!value) for (const child of body.querySelectorAll('.toolMenu[open]')) child.open = false;
          toggle.setAttribute('aria-expanded', String(!!value));
        };
        toggle.onclick = () => setOpen(body.hidden);
        if (fit) displayItems.append(fit);
        for (const child of [...display.children])
          if (child !== opacity && child !== label) displayItems.append(child);
        label?.remove();
        body.append(side, displayItems);
        toolbarMount.append(menu);
        if (selectionTools) display.append(selectionTools);
        selection?.remove();
        if (views && !views.children.length) views.remove();
        side.addEventListener('click', () => setOpen(false));
        menuOutside = event => {
          if (
            !menu.contains(event.target) &&
            !menu.contains(event.target.closest?.('.toolPopupPortal')?._toolMenuOwner || null)
          )
            setOpen(false);
        };
        menuEscape = event => {
          if (event.key === 'Escape') setOpen(false);
        };
        doc.addEventListener('pointerdown', menuOutside, true);
        doc.addEventListener('keydown', menuEscape);
      }
      const extras = doc.querySelector?.('#featureExtras')?.parentElement;
      if (extras) {
        extras.classList.add('compactExtras');
        const note = extras.querySelector(':scope > .subtle');
        if (note) extras.append(helpFor([note]));
      }

      const materials = services.createToolRow('materialsOpen', 'Материалы');
      materials.row.append(doc.getElementById('layerTools'));
      const measure = doc.getElementById('measureMenu'),
        measureTools = services.createToolRow('measureOpen', 'Замеры', open => {
          const b = doc.getElementById('measure');
          if (!open && b.getAttribute('aria-pressed') === 'true') b.click();
        });
      if (side) {
        const panel = doc.getElementById('side');
        mobileStructure = doc.getElementById('mobileStructure');
        modules.append(mobileStructure);
        const close = () => {
          panel.classList.remove('open');
          side.setAttribute('aria-expanded', 'false');
          mobileStructure.setAttribute('aria-expanded', 'false');
          mobileStructure.focus();
        };
        mobileStructure.onclick = () => {
          side.click();
          const on = panel.classList.contains('open');
          mobileStructure.setAttribute('aria-expanded', String(on));
          if (on) closeStructure.focus();
        };
        closeStructure = doc.getElementById('closeStructure');
        closeStructure.onclick = close;
        panel.append(closeStructure);
        structureEscape = event => {
          if (event.key === 'Escape' && win.innerWidth <= 760 && panel.classList.contains('open')) close();
        };
        doc.addEventListener('keydown', structureEscape);
      }
      const content = measure.querySelector('.toolPopup');
      if (content) {
        content.className = 'measureTools';
        const notes = [content.querySelector('.notice'), content.querySelector('.measureStatus')].filter(
          Boolean
        );
        if (notes.length) content.append(helpFor(notes));
        measureTools.row.append(content);
        measure.remove();
      }
      doc.getElementById('layersPanel').remove();
    };
    hooks.ready.push(ready);
    return {
      name: 'toolbar',
      dispose() {
        delete services.createToolRow;
        delete services.portalToolMenu;
        for (const dispose of portalDisposers.splice(0)) dispose();
        for (const r of rows) {
          r.button.remove();
          r.row.remove();
        }
        if (menuOutside) doc.removeEventListener('pointerdown', menuOutside, true);
        if (menuEscape) doc.removeEventListener('keydown', menuEscape);
        if (structureEscape) doc.removeEventListener('keydown', structureEscape);
        mobileStructure?.remove();
        closeStructure?.remove();
        viewerMenu?.remove();
        modules.remove();
        doc.querySelector?.('style[data-feature="toolbar"]')?.remove();
        const i = hooks.ready.indexOf(ready);
        if (i >= 0) hooks.ready.splice(i, 1);
      }
    };
  }
  (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'toolbar', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

styles:
#viewerMenu {
  order: -1;
  position: relative;
}
#viewerMenu .toolPopup {
  width: max-content;
  max-width: calc(100vw - 24px);
}
#viewerMenu #toggleSide {
  display: block;
}
.viewerMenuToggle {
  padding: 5px 7px;
  min-width: 30px;
}
.viewerMenuDisplay {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 10px;
}
.viewerMenuDisplay > .toolMenu {
  flex: none;
}
#displayPanel,
#selectionTools {
  flex-wrap: nowrap !important;
}
#displayPanel {
  overflow: visible;
}
#displayPanel > .opacityTool,
#displayPanel .visibilityTools,
#selectionTools,
#selectionTools > * {
  flex: none;
}
#displayPanel .visibilityTools > button {
  flex: none;
}
#displayPanel > .opacityTool {
  margin: 0;
}
#displayPanel button {
  white-space: nowrap;
}
.compactHelp {
  position: relative;
}
.compactHelp > summary {
  list-style: none;
  border: 1px solid var(--popup-border);
  border-radius: 50%;
  width: 24px;
  height: 24px;
  text-align: center;
  cursor: pointer;
}
.compactHelp > div {
  position: fixed;
  z-index: 50;
  left: 12px;
  right: 12px;
  top: 120px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  padding: 10px;
  border-radius: 8px;
  max-height: 35vh;
  overflow: auto;
}
.compactExtras {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  width: min(700px, calc(100vw - 24px)) !important;
}
.compactExtras #featureExtras {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.compactExtras hr,
.compactExtras #featureExtras .subtle {
  display: none;
}
.compactExtras #featureExtras button {
  width: auto !important;
  margin: 0 !important;
}
.compactExtras .check {
  padding: 2px 0;
}
.top > .functionalModules {
  order: 50;
  flex: 0 0 100%;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.top > .featureRow {
  order: 100;
  flex-basis: 100%;
  width: 100%;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
}
.top > .featureRow {
  padding: 6px 8px;
  gap: 6px;
  font-size: 12px;
  max-height: 30vh;
  overflow: auto;
}
.featureRow .tools {
  align-items: center;
}
.featureRow button {
  padding: 6px 9px;
  min-height: 32px;
}
.featureRow .check {
  padding: 2px 0;
}
.measureTools {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 12px;
  width: 100%;
}
.measureTools > h2 {
  display: none;
}
.measureTools > .measureStatus {
  flex: 1 1 200px;
  min-height: 0;
  margin: 0;
  font-size: 12px;
}
.measureTools > .check {
  order: 0;
  white-space: nowrap;
}
.measureTools > h2 {
  display: none;
}
.measureHelp {
  order: 2;
  font-size: 12px;
}
.measureHelp .notice {
  margin: 4px 0;
  max-width: 480px;
}
.featureRow[hidden] {
  display: none !important;
}
.assemblyUnits {
  position: absolute;
  right: 8px;
  top: 110px;
  z-index: 4;
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-width: 170px;
  max-height: 60%;
  overflow: auto;
}
