}
#viewerMenu .viewerMenuDisplay > .toolMenu > .toolPopup {
  position: fixed;
  left: 302px;
  right: 12px;
  top: 104px;
  width: auto;
  max-width: none;
  z-index: 60;
}
.toolPopupPortal {
