  right: auto !important;
  bottom: auto !important;
  transform: none !important;
  z-index: 80 !important;
  box-sizing: border-box;
}
@media (max-width: 760px) {
  #viewerMenu .viewerMenuDisplay > .toolMenu > .toolPopup {
    left: 10px;
    right: 10px;
    top: 120px;
  }
}

/* Главная строка занимает всю ширину; на узком экране подписи сокращаются,
   но ползунок и все действия доступны без горизонтальной прокрутки. */
#mobileStructure,
#closeStructure {
  display: none;
}
@media (max-width: 760px) {
  #mobileStructure,
  #closeStructure {
    display: block;
  }
  #viewerMenu #toggleSide {
    display: none;
  }
  #closeStructure {
    position: absolute;
    right: 10px;
    top: 10px;
    z-index: 2;
    width: 40px;
    height: 40px;
    padding: 0;
    font-size: 24px;
  }
  .top > .functionalModules > button {
    padding: 5px;
    font-size: 11px;
    min-height: 32px;
  }
}
#toolbar {
  right: 14px;
  width: auto;
  max-width: none;
  container-type: inline-size;
}
#toolbar #displayPanel {
  flex: 1 1 0;
  min-width: 0;
  align-self: stretch;
}
#viewerMenu {
  flex: none;
  align-self: center;
}
#toolbar > .githubSaveTools {
  flex: none;
  align-self: stretch;
  padding: 3px;
  border: 0;
  background: none;
}
#saveGithub {
  width: 32px;
  min-height: 32px;
  padding: 4px;
  display: grid;
  place-items: center;
}
/* Кнопки всегда идут стеком слева направо сразу за прозрачностью — и на ПК, и в
      узкой строке. Растягивать блок прозрачности незачем: для умещения строки это
      не нужно, а кнопки уезжали в конец (в узкой вёрстке — даже на ПК с крупным
      масштабом экрана, где окно меньше 760 CSS-пикселей). */
#displayPanel > .opacityTool {
  flex: 0 1 auto;
  min-width: 0;
}
#displayPanel .opacityTool .range {
  flex: 1 1 var(--compact-slider);
  min-width: 40px;
  max-width: 110px;
  width: var(--compact-slider);
}
#displayPanel .opacityTool span {
  flex: none;
  width: 32px;
}
@media (max-width: 760px) {
  #toolbar {
    right: 8px;
    max-width: none;
  }
}
@container (max-width:700px) {
  #toolbar #displayPanel {
    gap: 4px;
    padding: 3px;
  }
  #displayPanel .opacityTool,
  #selectionTools,
  #displayPanel .visibilityTools {
    gap: 4px;
  }
  #displayPanel button[data-compact-label] {
    font-size: 0;
    padding: 4px;
    min-height: 32px;
    min-width: 28px;
  }
  #displayPanel button[data-compact-label]::after {
    content: attr(data-compact-label);
    font-size: 12px;
  }
  #displayPanel .opacityTool label {
    font-size: 0;
  }
  #displayPanel .opacityTool label::after {
    content: attr(data-label);
    font-size: 11px;
  }
}
@container (max-width:330px) {
  #displayPanel .opacityTool label {
    display: none;
  }
}

scripts:
(function (root) {
  'use strict';
  function install(context, data) {
    const { THREE: T, document: doc, hooks, services } = context;
    if (data?.schema !== 1) throw new Error('Несовместимый модуль обводки');
    const shells = [];
    let strong = false,
      button = null,
      disposed = false;
    function makeShell(edge) {
      const mesh = edge.parent;
      if (!mesh?.isMesh) return;
      const geometry = mesh.geometry;
      geometry.computeBoundingBox();
      const box = geometry.boundingBox;
      if (!box || box.isEmpty()) return;
      const size = box.getSize(new T.Vector3()),
        center = box.getCenter(new T.Vector3()),
        pad = Math.min(2, Math.max(0.7, size.length() * 0.001));
      const scale = new T.Vector3(
        ...['x', 'y', 'z'].map(axis => (size[axis] > 1e-5 ? 1 + (pad * 2) / size[axis] : 1))
      );
      const color = edge.material.color.clone().multiplyScalar(0.45),
        material = new T.MeshBasicMaterial({ color, side: T.BackSide, depthTest: true, depthWrite: false });
      const shell = new T.Mesh(geometry, material);
      shell.name = 'Усиленная обводка';
      shell.scale.copy(scale);
      shell.position.set(center.x * (1 - scale.x), center.y * (1 - scale.y), center.z * (1 - scale.z));
      shell.visible = false;
      shell.renderOrder = -1;
      shell.userData = { decorative: true, outlineShell: true, sourceEdge: edge };
      mesh.add(shell);
      shells.push(shell);
    }
    const sync = () => {
      for (const shell of shells) shell.visible = strong && shell.userData.sourceEdge.visible;
    };
    function apply(value) {
      strong = !!value;
      for (const edge of services.edgeLineObjects || []) {
        edge.material.opacity = strong ? 1 : edge.userData.outlineBaseOpacity || 0.8;
        edge.material.needsUpdate = true;
      }
      sync();
      if (button) button.setAttribute('aria-pressed', String(strong));
      context.render?.();
    }
    function ready() {
      for (const edge of services.edgeLineObjects || []) makeShell(edge);
      /* Кнопка временно отключена по запросу; режим и сохранённые настройки оставляем.
   button=doc.createElement('button');button.type='button';button.id='strongOutline';button.textContent='Обводка';button.title='Усилить контуры деталей';button.onclick=()=>apply(!strong);doc.getElementById('opacity')?.closest('.opacityTool')?.after(button);
   */
      apply(strong);
    }
    hooks.ready.push(ready);
    hooks.frame.push(sync);
    function dispose() {
      if (disposed) return;
      disposed = true;
      apply(false);
      for (const [list, fn] of [
        [hooks.ready, ready],
        [hooks.frame, sync]
      ]) {
        const i = list.indexOf(fn);
        if (i >= 0) list.splice(i, 1);
      }
      for (const shell of shells) {
        shell.removeFromParent();
        shell.material.dispose();
      }
      shells.length = 0;
      button?.remove();
    }
    return {
      name: 'outline',
      serialize: () => strong,
      restore: apply,
      setStrong: apply,
      dispose,
      get strong() {
        return strong;
      },
      get shells() {
        return shells;
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'outline', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

(function (root) {
  'use strict';
  function create(T, scene, services) {
    const group = new T.Group();
    group.name = 'sectionCaps';
    group.renderOrder = 4;
    group.visible = false;
    scene.add(group);
    const entries = [];
    function clear() {
      while (group.children.length) {
        const mesh = group.children.pop();
        mesh.geometry.dispose();
      }
      entries.length = 0;
    }
    const key = (p, t) => Math.round(p.x / t) + ',' + Math.round(p.y / t);
    function crossSection(mesh, plane, u, v, tolerance) {
      const position = mesh.geometry?.attributes?.position;
      if (!position) return [];
      const index = mesh.geometry.index,
        count = index ? index.count : position.count,
        segments = [],
        a = new T.Vector3(),
        b = new T.Vector3(),
        c = new T.Vector3();
      const vertex = (target, i) =>
        target.fromBufferAttribute(position, index ? index.getX(i) : i).applyMatrix4(mesh.matrixWorld);
      for (let i = 0; i + 2 < count; i += 3) {
        vertex(a, i);
        vertex(b, i + 1);
        vertex(c, i + 2);
        const points = [a.clone(), b.clone(), c.clone()],
          d = points.map(p => plane.distanceToPoint(p));
        if (
          d.every(x => x > tolerance) ||
          d.every(x => x < -tolerance) ||
          d.every(x => Math.abs(x) <= tolerance)
        )
          continue;
        const hits = [];
        for (const [x, y] of [
          [0, 1],
          [1, 2],
          [2, 0]
        ]) {
          if (Math.abs(d[x]) <= tolerance && Math.abs(d[y]) > tolerance) hits.push(points[x].clone());
          if (d[x] * d[y] < -tolerance * tolerance)
            hits.push(points[x].clone().lerp(points[y], d[x] / (d[x] - d[y])));
        }
        const unique = [];
        for (const p of hits)
          if (!unique.some(q => q.distanceToSquared(p) <= tolerance * tolerance)) unique.push(p);
        if (unique.length < 2) continue;
        let pair = [unique[0], unique[1]],
          far = pair[0].distanceToSquared(pair[1]);
        for (let x = 0; x < unique.length; x++)
          for (let y = x + 1; y < unique.length; y++) {
            const distance = unique[x].distanceToSquared(unique[y]);
            if (distance > far) {
              far = distance;
              pair = [unique[x], unique[y]];
            }
          }
        if (far > tolerance * tolerance) segments.push(pair.map(p => new T.Vector2(p.dot(u), p.dot(v))));
      }
      return segments;
    }
    function loopsFrom(segments, tolerance) {
      const nodes = new Map(),
        edges = new Map();
      const node = p => {
        const k = key(p, tolerance);
        if (!nodes.has(k)) nodes.set(k, { key: k, p: p.clone(), edges: [] });
        return nodes.get(k);
      };
      for (const segment of segments) {
        const a = node(segment[0]),
          b = node(segment[1]);
        if (a === b) continue;
        const ek = a.key < b.key ? a.key + '|' + b.key : b.key + '|' + a.key;
        if (edges.has(ek)) continue;
        const edge = { key: ek, a, b, used: false };
        edges.set(ek, edge);
        a.edges.push(edge);
        b.edges.push(edge);
      }
      const loops = [];
      for (const first of edges.values()) {
        if (first.used) continue;
        first.used = true;
        const start = first.a;
        let previous = start,
          current = first.b;
        const loop = [start.p.clone()];
        for (let guard = 0; guard <= edges.size; guard++) {
          loop.push(current.p.clone());
          if (current === start) break;
          const next = current.edges.find(e => !e.used);
          if (!next) {
            loop.length = 0;
            break;
          }
          next.used = true;
          const following = next.a === current ? next.b : next.a;
          previous = current;
          current = following;
        }
        if (loop.length >= 4 && loop[0].distanceToSquared(loop.at(-1)) <= tolerance * tolerance) {
          loop.pop();
          const clean = loop.filter((p, i) => {
            const before = loop[(i + loop.length - 1) % loop.length],
              after = loop[(i + 1) % loop.length];
            return Math.abs(after.clone().sub(p).cross(p.clone().sub(before))) > tolerance * tolerance;
          });
          if (clean.length >= 3) loops.push(clean);
        }
      }
      return loops;
    }
    const area = loop =>
      loop.reduce(
        (sum, p, i) => sum + p.x * loop[(i + 1) % loop.length].y - loop[(i + 1) % loop.length].x * p.y,
        0
      ) / 2;
    function inside(point, loop) {
      let yes = false;
      for (let i = 0, j = loop.length - 1; i < loop.length; j = i++) {
        const a = loop[i],
          b = loop[j];
        if (a.y > point.y !== b.y > point.y && point.x < ((b.x - a.x) * (point.y - a.y)) / (b.y - a.y) + a.x)
          yes = !yes;
      }
      return yes;
    }
    function capGeometry(mesh, plane, normal) {
      if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
      const size = mesh.geometry.boundingBox?.getSize(new T.Vector3()).length() || 1,
        tolerance = Math.max(1e-4, size * 1e-7);
      const u = new T.Vector3()
          .crossVectors(normal, Math.abs(normal.y) < 0.9 ? new T.Vector3(0, 1, 0) : new T.Vector3(1, 0, 0))
          .normalize(),
        v = new T.Vector3().crossVectors(normal, u).normalize();
      const loops = loopsFrom(crossSection(mesh, plane, u, v, tolerance), tolerance);
      if (!loops.length) return null;
      const records = loops
        .map(loop => ({ loop, area: Math.abs(area(loop)), depth: 0 }))
        .sort((a, b) => b.area - a.area);
      for (let i = 0; i < records.length; i++)
        for (let j = 0; j < i; j++) if (inside(records[i].loop[0], records[j].loop)) records[i].depth++;
      const positions = [],
        normals = [],
        uvs = [],
        indices = [],
        origin = normal
          .clone()
          .multiplyScalar(-plane.constant)
          .addScaledVector(normal, tolerance * 2),
        capNormal = normal.clone().negate();
      for (const outer of records.filter(r => r.depth % 2 === 0)) {
        const holes = records
            .filter(r => r.depth === outer.depth + 1 && inside(r.loop[0], outer.loop))
            .map(r => r.loop),
          all = [outer.loop, ...holes].flat(),
          base = positions.length / 3;
        for (const p of all) {
          const world = origin.clone().addScaledVector(u, p.x).addScaledVector(v, p.y);
          positions.push(world.x, world.y, world.z);
          normals.push(capNormal.x, capNormal.y, capNormal.z);
          uvs.push(p.x, p.y);
        }
        for (const tri of T.ShapeUtils.triangulateShape(outer.loop, holes))
          indices.push(base + tri[0], base + tri[1], base + tri[2]);
      }
      if (!indices.length) return null;
      const geometry = new T.BufferGeometry();
      geometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
      geometry.setAttribute('normal', new T.Float32BufferAttribute(normals, 3));
      geometry.setAttribute('uv', new T.Float32BufferAttribute(uvs, 2));
      geometry.setIndex(indices);
      geometry.computeBoundingBox();
      geometry.computeBoundingSphere();
      return geometry;
    }
    function sources() {
      const found = [];
      for (const name of ['panels', 'profiles', 'imports'])
        services.groups?.[name]?.traverse(mesh => {
          if (mesh.isMesh && !mesh.userData?.decorative) found.push(mesh);
        });
      return found;
    }
    function rebuild(plane, normal, active) {
      clear();
      group.visible = !!active;
      if (!active) return 0;
      scene.updateMatrixWorld(true);
      for (const source of sources()) {
        const geometry = capGeometry(source, plane, normal);
        if (!geometry) continue;
        const cap = new T.Mesh(geometry, source.material);
        cap.userData = { decorative: true, sectionCap: true };
        cap.renderOrder = source.renderOrder + 0.1;
        cap.frustumCulled = false;
        group.add(cap);
        entries.push({ cap, source });
      }
      return entries.length;
    }
    function sync() {
      for (const entry of entries) {
        entry.cap.material = entry.source.material;
        entry.cap.visible = services.visible?.(entry.source) !== false;
      }
    }
    function dispose() {
      clear();
      group.removeFromParent();
    }
    return {
      group,
      rebuild,
      sync,
      clear,
      dispose,
      get count() {
        return entries.length;
      }
    };
  }
  const api = { create };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.BazisSectionCaps = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);
(function (root) {
  'use strict';
  function install(context, bundle) {
    const { THREE: T, renderer, scene, camera, controls, hooks, services, document: doc } = context;
    if (bundle?.schema !== 1 || !hooks?.pointVisible) throw new Error('Несовместимый модуль сечения');
    const baseNormal = new T.Vector3(0, 1, 0),
      plane = new T.Plane(),
      normal = new T.Vector3(),
      box = new T.Box3(),
      center = new T.Vector3();
    let axis = 'y',
      position = 0,
      reversed = false,
      active = false,
      showPlane = true,
      disposed = false,
      chosen = false,
      pending = false,
      min = 0,
      max = 0;
    const corners = [];
    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const $ = id => doc.getElementById(id);
    const pickHint = $('sectionPickHint');
    context.hintMount?.append(pickHint);
    const block = $('sectionPanel');
    const frame = new T.LineLoop(new T.BufferGeometry(), new T.LineBasicMaterial({ color: 0xffb74d }));
    frame.name = 'Плоскость сечения';
    frame.visible = false;
    scene.add(frame);
    const caps = root.BazisSectionCaps?.create(T, scene, services);
    if (!caps) throw new Error('Не загружен модуль заполнения сечения');
    const menu = $('sectionTools');
    const popup = $('sectionMenuPopup');
    const sectionRow = $('sectionRow');
    const rowTools = services.createToolRow?.('sectionOpen', 'Сечение');
    let disposeMore = null;
    if (rowTools) {
      rowTools.row.append(sectionRow);
      block.hidden = true;
      // «⋯» — в общий верхний слой, под строкой сечения целиком: прибитое к экрану
      // окно (top:140px) на телефоне ложилось на «Обратную сторону» во второй строке.
      disposeMore = services.portalToolMenu?.($('sectionMore'), { anchor: rowTools.row }) || null;
    } else popup.append(sectionRow); // без тулбара — строка в выпадающем меню
    function placePopup() {
      if (!menu.open) return;
      const top = Math.min(
        (context.toolbarMount?.getBoundingClientRect().bottom || 70) + 6,
        context.window.innerHeight - 180
      );
      popup.style.top = top + 'px';
      popup.style.maxHeight = Math.max(120, context.window.innerHeight - top - 12) + 'px';
    }
    menu.addEventListener('toggle', placePopup);
    context.window.addEventListener('resize', placePopup);

    const enabled = $('sectionEnabled');
    const direction = $('sectionAxis');
    const slider = $('sectionPosition');
    const number = $('sectionCoordinate');
    const flip = $('sectionReverse');
    const shown = $('sectionShowPlane');
    const summary = $('sectionSummary');
    const hint = $('sectionHint');
    const button = (id, run) => {
      const b = $(id);
      b.onclick = run;
      return b;
    };
    const choose = button('sectionChooseFace', () => beginPick());
    const middle = button('sectionMiddle', () => setPosition(center.dot(baseNormal)));
    const align = button('sectionAlign', () => alignView());
    const clearButton = button('sectionClear', () => clear());

    (context.toolbarMount || context.toolMount).append(block);
    block.append(menu);
    function pointVisible(point) {
      return !active || pending || !chosen || plane.distanceToPoint(point) >= -1e-6;
    }
    function update() {
      if (disposed) return;
      normal.copy(baseNormal).multiplyScalar(reversed ? -1 : 1);
      plane.set(normal, (reversed ? 1 : -1) * position);
      const cutting = active && chosen && !pending;
      const projections = corners.map(p => p.dot(baseNormal));
      min = Math.min(...projections);
      max = Math.max(...projections);
      const others = (renderer.clippingPlanes || []).filter(p => p !== plane);
      renderer.clippingPlanes = cutting ? [...others, plane] : others;
      caps.rebuild(plane, normal, cutting);
      frame.visible = cutting && showPlane;
      const u = new T.Vector3()
        .crossVectors(
          baseNormal,
          Math.abs(baseNormal.y) < 0.9 ? new T.Vector3(0, 1, 0) : new T.Vector3(1, 0, 0)
        )
        .normalize();
      const v = new T.Vector3().crossVectors(baseNormal, u),
        points = [];
      const pad = box.getSize(new T.Vector3()).length() * 0.025;
      const us = corners.map(p => p.dot(u)),
        vs = corners.map(p => p.dot(v));
      for (const [a, b] of [
        [0, 0],
        [1, 0],
        [1, 1],
        [0, 1]
