        points.push(
          baseNormal
            .clone()
            .multiplyScalar(position)
            .addScaledVector(normal, 0.01)
            .addScaledVector(u, a ? Math.max(...us) + pad : Math.min(...us) - pad)
            .addScaledVector(v, b ? Math.max(...vs) + pad : Math.min(...vs) - pad)
        );
      frame.geometry.dispose();
      frame.geometry = new T.BufferGeometry().setFromPoints(points);
      enabled.checked = active;
      direction.value = pending || !chosen ? '' : axis;
      flip.checked = reversed;
      shown.checked = showPlane;
      slider.min = number.min = String(min);
      slider.max = number.max = String(max);
      slider.value = number.value = String(Math.round(position * 10) / 10);
      pickHint.textContent = pending ? 'Сечение: нажмите на грань модели' : '';
      summary.textContent = active ? 'Сечение ●' : 'Сечение';
      for (const control of [slider, number, flip, shown, middle, align]) control.disabled = !cutting;
      direction.disabled = choose.disabled = !active;
      clearButton.disabled = !active && !chosen;
      hint.textContent = pending
        ? 'Нажмите на плоскую грань модели. Затем перемещайте сечение ползунком.'
        : chosen
          ? 'Сечение параллельно выбранной плоскости. Геометрия не удаляется.'
          : 'Включите сечение, затем выберите грань модели или направление из списка.';
    }
