      baseNormal[axis] = 1;
      chosen = true;
      pending = false;
      position = center.dot(baseNormal);
      update();
    }
    function reverse() {
      reversed = !reversed;
      update();
    }
    function setShowPlane(value) {
      showPlane = !!value;
      update();
    }
    function alignView() {
      const target = center.clone().addScaledVector(baseNormal, position - center.dot(baseNormal));
      const distance = Math.max(
        camera.position.distanceTo(controls.target),
        box.getSize(new T.Vector3()).length()
