(function (root) {
  'use strict';
  // McGuire/Bavoil weighted blended OIT. Linear light; separate accumulation
  // and revealage passes work with the bundled Three r160 without MRT blending.
  function install(context, bundle) {
    const { THREE: T, renderer, scene, camera, controls, hooks, services, document: doc } = context;
    if (bundle?.schema !== 1 || !hooks?.surfaceMaterial || !hooks?.render)
      throw new Error('Несовместимый модуль прозрачности');
    const supported =
      !context.graphics?.safe &&
      !!(renderer.capabilities?.isWebGL2 && renderer.extensions.has('EXT_color_buffer_float'));
    const materials = new Set(),
      variants = new Map(),
      fallbackHooks = new Map();
    const alpha = { value: 1 },
      size = { value: new T.Vector2(1, 1) },
      distance = { value: 1 },
      depth = { value: null };
    let disposed = false,
      targets = null,
      composite = null,
      quad = null,
      passScene = null;
    const fallbackUniform = { value: 0 };
    function applyFallback(m) {
      m.onBeforeCompile = shader => {
        shader.uniforms.uDither = fallbackUniform;
        // Своя varying с видовой глубиной фрагмента (мм): экранный шаблон СМЕЩАЕТСЯ по
        // срезам глубины, иначе у фасада и полки за ним «оставленные» пиксели совпадают
        // пиксель-в-пиксель и заднюю панель не видно совсем. Со смещением дырки
        // переднего слоя открывают задний.
        shader.vertexShader =
          'varying float vDitherDepth;\n' +
          shader.vertexShader.replace(
            '#include <project_vertex>',
            '#include <project_vertex>\nvDitherDepth=-(modelViewMatrix*vec4(transformed,1.0)).z;'
          );
        shader.fragmentShader =
          'uniform float uDither;\nvarying float vDitherDepth;\n' +
          shader.fragmentShader.replace(
            '#include <clipping_planes_fragment>',
            '#include <clipping_planes_fragment>\n' +
              'if(uDither>0.001){' +
              'vec2 dof=vec2(mod(floor(vDitherDepth*0.2),4.0),mod(floor(vDitherDepth*0.05),4.0));' +
              'vec2 dp=floor(gl_FragCoord.xy)+dof;vec2 dh=floor((gl_FragCoord.xy+dof)*0.5);' +
              'float b1=fract(dp.x*0.5+dp.y*dp.y*0.75);' + // Bayer 2×2 в полном разрешении
              'float b2=fract(dh.x*0.5+dh.y*dh.y*0.75);' + // Bayer 2×2 в половинном
              'float bayer=b2*0.25+b1;' + // → равномерный Bayer 4×4, 16 уровней
              'if(bayer<uDither)discard;}'
          );
      };
      m.customProgramCacheKey = () => 'dither';
      return m;
    }

    function register(material) {
      materials.add(material);
      if (!supported) {
        fallbackHooks.set(material, [material.onBeforeCompile, material.customProgramCacheKey]);
        applyFallback(material);
      }
    }
    function setOpacity(value) {
      if (!Number.isFinite(value)) throw new Error('Некорректная непрозрачность');
      alpha.value = Math.min(1, Math.max(0.25, value));
      fallbackUniform.value = 1 - alpha.value;
      const boost = Math.pow((1 - alpha.value) / 0.75, 0.7);
      for (const entry of services.fadeables || []) {
        const floor = Number.isFinite(entry.min) ? entry.min : 0.18;
        entry.mat.opacity = entry.base * (floor + (1 - floor) * boost);
      }
      for (const material of services.holeMaterials || []) {
        material.depthTest = alpha.value === 1 && !doc.getElementById('holeOverlay').checked;
        material.needsUpdate = true;
      }
    }
    const declarations = `uniform sampler2D oitDepth;
uniform vec2 oitSize;
uniform float oitAlpha;
uniform float oitDistance;
varying float oitViewDepth;
`;
    const depthTest = `float fragmentDepth=gl_FragCoord.z;
#if defined(USE_LOGDEPTHBUF) && defined(USE_LOGDEPTHBUF_EXT)
fragmentDepth=vIsPerspective==0.0?gl_FragCoord.z:log2(vFragDepth)*logDepthBufFC*0.5;
#endif
if(fragmentDepth>texture2D(oitDepth,gl_FragCoord.xy/oitSize).r+0.0000001)discard;
`;
    function variant(original, pass) {
      let pair = variants.get(original);
      if (!pair) {
        pair = {};
        variants.set(original, pair);
      }
      let material = pair[pass];
      if (!material) {
        material = original.clone();
        pair[pass] = material;
        material.transparent = true;
        material.depthWrite = false;
        material.depthTest = false;
        // Closed solids contribute the face facing the viewer once, not both skins.
        material.side = T.FrontSide;
        material.blending = T.CustomBlending;
        material.blendEquation = T.AddEquation;
        material.blendSrc = pass === 'accum' ? T.OneFactor : T.ZeroFactor;
        material.blendDst = pass === 'accum' ? T.OneFactor : T.OneMinusSrcAlphaFactor;
        material.onBeforeCompile = shader => {
          Object.assign(shader.uniforms, {
            oitDepth: depth,
            oitSize: size,
            oitAlpha: alpha,
            oitDistance: distance
          });
          shader.vertexShader =
            'varying float oitViewDepth;\n' +
            shader.vertexShader.replace(
              '#include <project_vertex>',
              '#include <project_vertex>\noitViewDepth=-mvPosition.z;'
            );
          shader.fragmentShader =
            declarations +
            shader.fragmentShader
              .replace(
                '#include <opaque_fragment>',
                depthTest +
                  (pass === 'accum'
