      const reveal = new T.WebGLRenderTarget(1, 1, { ...options, depthBuffer: false });
      targets = { base, accum, reveal };
      depth.value = base.depthTexture;
      composite = new T.ShaderMaterial({
        depthTest: false,
        depthWrite: false,
        uniforms: {
          base: { value: base.texture },
          accum: { value: accum.texture },
          reveal: { value: reveal.texture }
        },
        vertexShader: 'varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.0,1.0);}',
        fragmentShader: `uniform sampler2D base,accum,reveal;varying vec2 vUv;
void main(){vec4 sum=texture2D(accum,vUv);float transmittance=texture2D(reveal,vUv).r;
vec3 color=sum.rgb/max(sum.a,0.00001);
gl_FragColor=vec4(color*(1.0-transmittance)+texture2D(base,vUv).rgb*transmittance,1.0);
#include <tonemapping_fragment>
#include <colorspace_fragment>
}`
      });
      quad = new T.Mesh(new T.PlaneGeometry(2, 2), composite);
      quad.frustumCulled = false;
      passScene = new T.Scene();
      passScene.add(quad);
    }
    function render() {
      if (disposed || !supported || alpha.value === 1) return false;
      allocate();
      const drawSize = renderer.getDrawingBufferSize(new T.Vector2());
      if (!drawSize.equals(size.value)) {
        size.value.copy(drawSize);
        for (const target of Object.values(targets)) target.setSize(drawSize.x, drawSize.y);
      }
      distance.value = Math.max(camera.position.distanceTo(controls.target), 1);
      const objects = [];
      scene.traverse(object => {
        if (!object.material) return;
        const panel = materials.has(object.material);
        const overlay =
          !panel &&
          (Array.isArray(object.material)
            ? object.material.every(m => !m.depthTest)
            : !object.material.depthTest);
        objects.push({ object, mask: object.layers.mask, material: object.material, panel, overlay });
      });
      const previous = {
        target: renderer.getRenderTarget(),
        clear: renderer.getClearColor(new T.Color()),
        alpha: renderer.getClearAlpha(),
        auto: renderer.autoClear,
        autoReset: renderer.info.autoReset,
        background: scene.background
      };
      function selectPass(pass) {
        for (const entry of objects) {
          const show =
            pass === 'base'
              ? !entry.panel && !entry.overlay
              : pass === 'overlay'
                ? entry.overlay
                : entry.panel;
          entry.object.layers.mask = show ? entry.mask : 0;
          entry.object.material =
            entry.panel && (pass === 'accum' || pass === 'reveal')
              ? variant(entry.material, pass)
              : entry.material;
        }
      }
      try {
        renderer.autoClear = false;
        if (previous.autoReset) renderer.info.reset();
        renderer.info.autoReset = false;
        selectPass('base');
        renderer.setRenderTarget(targets.base);
        renderer.setClearColor(previous.clear, previous.alpha);
        renderer.clear();
        renderer.render(scene, camera);
        scene.background = null;
        selectPass('accum');
        renderer.setRenderTarget(targets.accum);
        renderer.setClearColor(0, 0);
        renderer.clear();
        renderer.render(scene, camera);
        selectPass('reveal');
        renderer.setRenderTarget(targets.reveal);
        renderer.setClearColor(0xffffff, 1);
        renderer.clear();
        renderer.render(scene, camera);
        renderer.setRenderTarget(previous.target);
        renderer.setClearColor(previous.clear, previous.alpha);
        renderer.clear();
        renderer.render(passScene, camera);
        selectPass('overlay');
        renderer.render(scene, camera);
      } finally {
