(function (root) {
  'use strict';
  // Видовой куб справа-сверху: мини-сцена в своём канвасе повторяет ориентацию
  // главной камеры; клик по грани разворачивает вид на эту сторону. Отдельный
  // рендерер/канвас — полностью изолирован от основного прохода (и от OIT).
  const FACES = [
    // порядок материалов BoxGeometry: +X,-X,+Y,-Y,+Z,-Z
    { view: 'right', label: 'Справа' },
    { view: 'left', label: 'Слева' },
    { view: 'top', label: 'Сверху' },
    { view: 'bottom', label: 'Снизу' },
    { view: 'front', label: 'Спереди' },
    { view: 'back', label: 'Сзади' }
  ];
  const faceToView = i => (FACES[i] || {}).view || null;

  function labelTexture(T, text) {
    const c = typeof document !== 'undefined' ? document.createElement('canvas') : null;
    if (!c || !c.getContext) return null;
    c.width = c.height = 128;
    const g = c.getContext('2d');
    g.fillStyle = '#dfe7ec';
    g.fillRect(0, 0, 128, 128);
    g.strokeStyle = '#5b6b77';
    g.lineWidth = 6;
    g.strokeRect(3, 3, 122, 122);
    g.fillStyle = '#12222c';
    g.font = 'bold 27px system-ui,Arial';
    g.textAlign = 'center';
    g.textBaseline = 'middle';
