  }

  function install(context, data) {
    const { THREE: T, camera, hooks, document: doc, window: win } = context;
    if (data?.schema !== 1 || !hooks?.frame) throw new Error('Несовместимый модуль видового куба');

    // Мини-рендерер в своём канвасе. В node/без WebGL — деградируем в no-op,
    // но faceToView и контракт остаются проверяемыми.
    let renderer = null,
      host = null,
      onClick = null,
      offLanguage = null,
      frame = null;
    try {
      // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
      host = doc.getElementById('viewCube');
      const canvas = doc.getElementById('viewCubeCanvas');
      const mount = doc.getElementById && doc.getElementById('viewport');
