      name: 'viewcube',
      faceToView,
      active: !!renderer,
      dispose() {
        if (frame) {
          const i = hooks.frame.indexOf(frame);
          if (i >= 0) hooks.frame.splice(i, 1);
        }
        if (onClick && host) host.removeEventListener('click', onClick);
        host && host.remove();
