scripts:
(function (root) {
  'use strict';
  function install(context, bundle) {
    const { services, hooks, document: doc, window: win } = context;
    if (bundle?.schema !== 1) throw new Error('Неизвестный формат меню замеров');
    const visuals = () => services.dimensionVisuals || [],
      manual = rec => (services.measurements || []).includes(rec);
    const validColor = value => typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value);
    const key = rec => JSON.stringify([rec.a?.toArray(), rec.b?.toArray(), rec.text]);
    const seen = new WeakMap();
    let restored = new Map(),
      current = null,
      mount = null,
      press = null,
      timer = null,
      suppress = null,
      picker = null;
    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const menu = doc.getElementById('dimensionActions');
    doc.body.append(menu);
    function button(id, run) {
      const b = doc.getElementById(id);
      b.onclick = run;
      return b;
    }
    const remove = button('dimensionActionRemove', () => {
      const rec = current;
      close();
      if (rec && services.removeDimension?.(rec))
        doc.getElementById('measureStatus').textContent = 'Замер удалён.';
    });
    const color = button('dimensionActionColor', () => {
      const rec = current;
      close();
      if (!rec) return;
      picker = root.BazisColorPicker.open(
        doc,
        rec.color || '#ff4040',
        value => setColor(rec, value),
        'Цвет размера'
      );
    });
    function apply(rec) {
      if (services.applyDimensionStyle) {
        services.applyDimensionStyle();
        return;
      }
      if (validColor(rec.color)) {
        rec.label.style.color = rec.color;
        for (const m of rec.materials || []) m.color.set(rec.color);
      }
    }
    function setColor(rec, value) {
      if (!visuals().includes(rec) || !validColor(value)) return false;
      rec.color = value.toLowerCase();
      if (!manual(rec)) restored.set(key(rec), rec.color);
      apply(rec);
      return true;
    }
    function close(focus = false) {
      menu.hidden = true;
      if (focus) current?.label.focus();
      current = null;
    }
    function open(rec, x, y) {
      if (services.isMeasuring?.() || !visuals().includes(rec)) return;
      current = rec;
      services.focusDimension?.(rec);
      remove.disabled = !manual(rec);
      remove.title = remove.disabled ? 'Удаление доступно для замеров, созданных в HTML' : '';
      menu.hidden = false;
      const box = menu.getBoundingClientRect();
      menu.style.left = Math.max(6, Math.min(x, win.innerWidth - box.width - 6)) + 'px';
      menu.style.top = Math.max(6, Math.min(y, win.innerHeight - box.height - 6)) + 'px';
      (remove.disabled ? color : remove).focus();
    }
    const record = event => {
      const el = event.target.closest?.('.dimLabel');
      return visuals().find(r => r.label === el);
    };
    const contextMenu = event => {
      const rec = record(event);
      if (!rec || services.isMeasuring?.()) return;
      event.preventDefault();
      event.stopPropagation();
      cancel();
      open(rec, event.clientX, event.clientY);
    };
    function cancel() {
      if (timer != null) win.clearTimeout(timer);
      timer = null;
      press = null;
    }
    const down = event => {
      cancel();
      const rec = record(event);
      if (event.pointerType !== 'touch' || !rec || services.isMeasuring?.()) return;
      press = { rec, x: event.clientX, y: event.clientY, id: event.pointerId };
      timer = win.setTimeout(() => {
        const p = press;
        if (p) {
          suppress = { label: p.rec.label, until: Date.now() + 1200 };
          open(p.rec, p.x, p.y);
        }
        cancel();
      }, 550);
    };
    const move = event => {
      if (press?.id === event.pointerId && Math.hypot(event.clientX - press.x, event.clientY - press.y) > 10)
        cancel();
    };
    const click = event => {
      if (suppress && Date.now() < suppress.until && event.target.closest?.('.dimLabel') === suppress.label) {
        event.preventDefault();
        event.stopImmediatePropagation();
        suppress = null;
      }
    };
    const labelKey = event => {
      const rec = record(event);
      if (!rec) return;
      if (event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10')) {
        event.preventDefault();
        const r = rec.label.getBoundingClientRect();
        open(rec, r.left, r.bottom);
      } else if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        rec.label.click();
      }
    };
    const outside = event => {
      if (!menu.contains(event.target)) close();
    };
    const keyDown = event => {
      if (menu.hidden) return;
      if (event.key === 'Escape') {
        event.preventDefault();
        close(true);
      } else if (['ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) {
        event.preventDefault();
        const buttons = [remove, color].filter(b => !b.disabled),
          at = buttons.indexOf(doc.activeElement),
          index =
            event.key === 'Home'
              ? 0
              : event.key === 'End'
                ? buttons.length - 1
                : (at + (event.key === 'ArrowDown' ? 1 : -1) + buttons.length) % buttons.length;
        buttons[index].focus();
      }
    };
    const resize = () => {
      cancel();
      close();
    };
    const events = [
      ['contextmenu', contextMenu],
      ['pointerdown', down],
      ['pointermove', move],
      ['pointerup', cancel],
      ['pointercancel', cancel],
      ['click', click],
      ['keydown', labelKey]
    ];
    function ready() {
      mount = doc.getElementById('labels');
      for (const [type, fn] of events) mount.addEventListener(type, fn, true);
    }
    function frame() {
      const list = visuals();
      if (current && !list.includes(current)) close();
      for (const rec of list) {
        if (!seen.has(rec)) {
          seen.set(rec, { color: null, materials: (rec.materials || []).map(m => m.color.clone()) });
          rec.label.tabIndex = 0;
          rec.label.setAttribute('role', 'button');
          rec.label.setAttribute('aria-haspopup', 'menu');
          rec.label.title = 'Нажатие — точки размера. Правая кнопка или удержание — удалить / изменить цвет.';
        }
        if (!manual(rec) && !rec.color && restored.has(key(rec))) rec.color = restored.get(key(rec));
        const state = seen.get(rec);
        if (state.color !== rec.color) {
          state.color = rec.color;
          if (validColor(rec.color)) apply(rec);
        }
      }
    }
    doc.addEventListener('pointerdown', outside);
    doc.addEventListener('keydown', keyDown);
    win.addEventListener('resize', resize);
    hooks.ready.push(ready);
    hooks.frame.push(frame);
    return {
      name: 'dimension_actions',
      setColor,
      serialize: () => ({
        colors: visuals()
          .filter(r => !manual(r) && validColor(r.color))
          .map(r => ({ key: key(r), color: r.color }))
      }),
      restore(state) {
        restored = new Map(
          (Array.isArray(state?.colors) ? state.colors : [])
            .filter(c => c && typeof c.key === 'string' && c.key.length < 500 && validColor(c.color))
            .map(c => [c.key, c.color])
        );
        for (const rec of visuals())
          if (!manual(rec)) {
            delete rec.color;
            const saved = seen.get(rec);
            if (saved) {
              (rec.materials || []).forEach((m, i) => {
                if (saved.materials[i]) m.color.copy(saved.materials[i]);
              });
              saved.color = null;
            }
            if (restored.has(key(rec))) rec.color = restored.get(key(rec));
            if (!services.applyDimensionStyle) rec.label.style.color = '';
          }
        services.applyDimensionStyle?.();
        frame();
      },
      dispose() {
        cancel();
        close();
        picker?.close();
        menu.remove();
        doc.querySelector?.('style[data-feature="dimension_actions"]')?.remove();
        for (const [type, fn] of events) mount?.removeEventListener(type, fn, true);
        doc.removeEventListener('pointerdown', outside);
        doc.removeEventListener('keydown', keyDown);
        win.removeEventListener('resize', resize);
        for (const [list, fn] of [
          [hooks.ready, ready],
          [hooks.frame, frame]
        ]) {
          const i = list.indexOf(fn);
          if (i >= 0) list.splice(i, 1);
        }
      }
    };
  }
  (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'dimension_actions', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

