scripts:
(function (root) {
  'use strict';
  // Сохранённые в модели размеры (объекты типа 9000) рисуются в стиле SketchUp:
  // выносные линии, размерная линия со стрелками-барбами и подпись значения.
  // Данные модуль получает своим разделом data.dims (integration.py достаёт их из
  // scene.native_dimensions): p/q — мировая поза начала, локальная +X — вдоль
  // размера на size, локальная +Y — сторона выносных длиной length; value — подпись.
  // Геометрия уходит в отдельную группу groups.nativeDimensions. Размеры из БАЗИСа
  // можно скрыть независимо от замеров, созданных пользователем в HTML.
  function install(context, data) {
    const { THREE: T, hooks, scene, camera, canvas, services, document: doc } = context;
    if (data?.schema !== 1 || !Array.isArray(hooks?.frame)) throw new Error('Несовместимый модуль размеров');
    const dims = data.dims || [];
    const group = new T.Group();
    group.name = 'nativeDimensions';
    group.renderOrder = 11;
    const labelsMount = doc.getElementById ? doc.getElementById('labels') : null;
    const labels = [];
    let host = null,
      occ = [];
    const attach = () => {
      host = services?.groups?.nativeDimensions || services?.groups?.dimensions || scene;
      host.add(group);
      const g = services?.groups;
      if (g) occ = ['panels', 'profiles', 'imports'].map(k => g[k]).filter(Boolean);
      for (const d of dims) {
        if (!d.p || !d.q || !Number.isFinite(d.size) || d.size <= 0) continue;
        const quat = new T.Quaternion(...d.q),
          A = new T.Vector3(...d.p),
          B = new T.Vector3(1, 0, 0).applyQuaternion(quat).multiplyScalar(d.size).add(A);
        // Вынос: размерная линия стоит не на измеренных точках, а сдвинута на length
        // по локальной +Y (знак — сторона), к ней идут выносные линии с небольшим
        // заходом за неё, как на чертеже БАЗИСа. Без length — линия по точкам.
        const offset = Number.isFinite(d.length)
          ? new T.Vector3(0, 1, 0).applyQuaternion(quat).multiplyScalar(d.length)
          : new T.Vector3();
        const LA = A.clone().add(offset),
          LB = B.clone().add(offset);
        const visual = services.createDimensionVisual(LA, LB);
        group.add(visual.group);
        if (offset.length() > 1e-6) {
          const over = offset.clone().setLength(Math.min(10, offset.length() * 0.1));
          const material = new T.LineBasicMaterial({
            color: visual.materials?.[0]?.color?.getHex?.() ?? 0xb7f3d9,
            depthTest: visual.materials?.[0]?.depthTest ?? true
          });
          const ext = new T.LineSegments(
            new T.BufferGeometry().setFromPoints([A, LA.clone().add(over), B, LB.clone().add(over)]),
            material
          );
          ext.renderOrder = 12;
          ext.userData.extensionLines = true;
          visual.group.add(ext);
          visual.materials?.push(material);
        }
        const raw = d.value != null && d.value !== '' ? d.value : d.size,
          num = Number(raw);
        const text = Number.isFinite(num) ? context.fmt(num) : String(raw);
        visual.text = text; // подпись без единиц — единицы навешивает общий стиль
        labels.push({
          id: d.id,
          el: visual.label,
          mid: LA.clone().add(LB).multiplyScalar(0.5),
          text,
          group: visual.group
        });
      }
      const count = doc.getElementById?.('nativeMeasureCount');
      if (count) count.textContent = String(labels.length);
      applyStyle();
    };
    hooks.ready.push(attach);

    const project = v => {
      const s = v.clone().project(camera);
      return { x: ((s.x + 1) * canvas.clientWidth) / 2, y: ((1 - s.y) * canvas.clientHeight) / 2, z: s.z };
    };
    // Подпись — HTML поверх канваса, буфер глубины её не прячет; проверяем вручную
    // лучом камера→подпись: если раньше упрёмся в видимую поверхность — перекрыта.
    const ray = new T.Raycaster(),
      dir = new T.Vector3();
    const renderable = o => {
      for (let n = o; n; n = n.parent) if (!n.visible) return false;
      return true;
    };
    const blocked = mid => {
      if (services.dimensionBlocked) return services.dimensionBlocked(mid);
      if (!occ.length) return false;
      const dist = camera.position.distanceTo(mid);
      dir.copy(mid).sub(camera.position).normalize();
      ray.set(camera.position, dir);
      const hit = ray
        .intersectObjects(occ, true)
        .find(
          h => h.object.isMesh && renderable(h.object) && context.services.pointVisible?.(h.point) !== false
        );
      return !!hit && hit.distance < dist - dist * 0.003;
    };
    // Позиционирование и видимость подписей — общий цикл шаблона (он одинаково
    // обслуживает ручные замеры и размеры из БАЗИСа). Здесь остаётся только то, что
    // специфично для родных: видимость по объекту-источнику и подхват новых замеров
    // в общий стиль.
    let styledCount = -1;
    const frame = () => {
      for (const l of labels) l.group.visible = services.objectVisible?.(l.id) !== false;
      const list = services.dimensionVisuals;
      if (list && list.length !== styledCount) {
        styledCount = list.length;
        applyStyle();
      }
    };
    hooks.frame.push(frame);

    // Настройки вида размеров: размер шрифта, цвет (по умолчанию голубой) и единицы.
    // Хранятся в localStorage, поэтому переносятся между моделями и сессиями. Цвет
    // применяется и к подписям, и к линиям — размеры остаются единым по стилю слоем.
    const win = context.window || root,
      STORE = 'bazisDimStyleV3',
      DEFAULTS = { size: 10, color: '#102820', unit: false, box: true };
    let cfg = Object.assign({}, DEFAULTS);
    try {
      const s = JSON.parse(win.localStorage.getItem(STORE));
      if (s && typeof s === 'object') cfg = Object.assign(cfg, s);
    } catch (e) {}
    // Стиль — ОДИН на все размеры: и на ручные замеры, и на пришедшие из БАЗИСа.
    // Берём общий список визуалов у шаблона; своего списка хватает лишь на случай
    // старого шаблона без этой службы.
    const allVisuals = () =>
      services.dimensionVisuals || labels.map(l => ({ label: l.el, text: l.text, group: l.group }));
    // Без подложки цифра лежит прямо на тёмной сцене: тёмный цвет шрифта там не
    // читается, поэтому берём светлый и даём тёмный контур (на светлых панелях).
    const isDark = hex => {
      const m = /^#?([0-9a-f]{6})$/i.exec(hex || '');
      if (!m) return true;
      const n = parseInt(m[1], 16);
      return (0.2126 * ((n >> 16) & 255) + 0.7152 * ((n >> 8) & 255) + 0.0722 * (n & 255)) / 255 < 0.55;
    };
    const applyStyle = () => {
      const bare = !cfg.box;
      for (const rec of allVisuals()) {
        const el = rec.label;
        if (!el) continue;
        const color = rec.color || cfg.color,
          textColor =
            bare && isDark(color)
              ? rec.color
                ? '#' + new T.Color(color).lerp(new T.Color('#ffffff'), 0.5).getHexString()
                : '#eaf8f2'
              : color;
        el.style.fontSize = cfg.size + 'px';
        el.style.color = textColor;
        el.style.textShadow = bare ? '0 0 2px #000,0 0 4px #000,0 1px 2px #000' : '';
        const base = rec.text != null ? rec.text : el.textContent;
        el.textContent = cfg.unit ? base + ' мм' : base;
        // «Подложка» — та самая плашка из .dimLabel; выключаем инлайном, не трогая класс.
        const off = !cfg.box;
        el.style.background = off ? 'transparent' : '';
        el.style.border = off ? '0' : '';
        el.style.padding = off ? '0' : '';
        el.style.boxShadow = off ? 'none' : '';
        if (rec.group && (rec.color || color !== DEFAULTS.color)) {
          const materials = rec.materials || [];
          if (materials.length) materials.forEach(m => m.color.set(color));
          else
            rec.group.traverse(o => {
              if (o.material) o.material.color.set(color);
            });
        }
      }
    };
    const save = () => {
      try {
        win.localStorage.setItem(STORE, JSON.stringify(cfg));
      } catch (e) {}
    };
    services.applyDimensionStyle = applyStyle;
    applyStyle();

    const styleControls = {};
    const toolMount = context.displayMount || context.toolMount; // блок «Отображение»
    if (toolMount && doc.getElementById) {
      // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
      const $ = id => doc.getElementById(id);
      const size = $('dimensionFontSize'),
        col = $('dimensionColor'),
        unit = $('dimensionUnit'),
        box = $('dimensionBox');
      size.value = String(cfg.size);
      size.oninput = () => {
        cfg.size = Number(size.value);
        applyStyle();
        save();
      };
      col.value = cfg.color;
      col.oninput = () => {
        cfg.color = col.value;
        applyStyle();
        save();
      };
      unit.checked = cfg.unit;
      unit.onchange = () => {
        cfg.unit = unit.checked;
        applyStyle();
        save();
      };
      box.checked = cfg.box;
      box.onchange = () => {
        cfg.box = box.checked;
        applyStyle();
        save();
      };
      Object.assign(styleControls, { size, col, unit, box });
      toolMount.append($('dimensionStyle'));
    }

    return {
      name: 'dimensions',
      serialize: () => ({ ...cfg }),
      restore: s => {
        Object.assign(cfg, s);
        applyStyle();
        if (styleControls.size) {
          styleControls.size.value = String(cfg.size);
          styleControls.col.value = cfg.color;
          styleControls.unit.checked = cfg.unit;
          styleControls.box.checked = cfg.box;
        }
      },
      count: dims.length,
      get drawn() {
        return labels.length;
      },
      group,
      style: cfg,
      dispose() {
        delete services.applyDimensionStyle;
        const i = hooks.frame.indexOf(frame);
        if (i >= 0) hooks.frame.splice(i, 1);
        const j = hooks.ready.indexOf(attach);
        if (j >= 0) hooks.ready.splice(j, 1);
        group.removeFromParent();
        group.traverse(o => {
          o.geometry?.dispose();
          o.material?.dispose();
        });
        for (const l of labels) l.el.remove();
        doc.getElementById('dimensionStyle')?.remove();
        doc.querySelector?.('style[data-feature="dimensions"]')?.remove();
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'dimensions', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

