scripts:
(function (root) {
  'use strict';
  // Менеджер материалов: окно со списком выгруженных текстур и цветов. По каждому
  // материалу можно повернуть текстуру (частая проблема — «неправильное
  // направление»), залить сплошным цветом, заменить текстуру на другую вшитую в
  // модель ИЛИ на свою картинку с диска. Правки привязываются к артикулу материала
  // и хранятся в localStorage, поэтому переносятся между перезагрузками и повторными
  // выгрузками той же модели. Материалы у просмотрщика общие (кэшируются по
  // цвету|текстуре), поэтому правка одного материала меняет все детали с ним.
  const TILE_DEFAULT = 600,
    STORE = 'bazisMatEdits';
  function install(context, data) {
    const { THREE: T, data: DATA, hooks, services, document: doc, window: win } = context;
    if (data?.schema !== 1 || !Array.isArray(hooks?.ready))
      throw new Error('Несовместимый модуль материалов');
    const mount = context.layersMount || context.toolMount;
    const W = win || root,
      bank = DATA.textures || {},
      tile = (services && services.textureTileMm) || TILE_DEFAULT;
    let saved = {};
    try {
      saved = JSON.parse(W.localStorage.getItem(STORE)) || {};
    } catch (e) {
      saved = {};
    }
    const persist = () => {
      try {
        W.localStorage.setItem(STORE, JSON.stringify(saved));
        return true;
      } catch (e) {
        return false;
      }
    };

    // имя материала по артикулу — из строк «Имя\rАртикул» в записях сцены
    const nameByArt = {};
    for (const r of [...(DATA.panels || []), ...(DATA.profiles || []), ...(DATA.meshes || [])]) {
      const m = r && r.material;
      if (m && m.indexOf('\r') >= 0) {
        const p = m.split('\r'),
          art = (p[1] || '').trim();
        if (art && !nameByArt[art]) nameByArt[art] = (p[0] || '').trim() || art;
      }
    }
    const artName = a => nameByArt[a] || a;

    // текстура строится теми же параметрами, что и в просмотрщике (тайлинг, sRGB)
    const buildTex = uri => {
      const t = new T.TextureLoader().load(uri);
      t.wrapS = t.wrapT = T.RepeatWrapping;
      t.repeat.set(1 / tile, 1 / tile);
      if ('colorSpace' in t) t.colorSpace = T.SRGBColorSpace;
      return t;
    };

    const groups = new Map(); // id → {mats:Set, state, ...}
    const uploaded = new Map(); // id → THREE.Texture своей картинки
    const materialRowTools = [];
    const registerMaterialRowTool = fn => {
      materialRowTools.push(fn);
      return () => {
        const i = materialRowTools.indexOf(fn);
        if (i >= 0) materialRowTools.splice(i, 1);
      };
    };
    services.registerMaterialRowTool = registerMaterialRowTool;

    const currentMap = g => {
      if (g.state.mode !== 'tex') return null;
      if (g.state.texData) {
        let t = uploaded.get(g.id);
        if (!t) {
          t = buildTex(g.state.texData);
          uploaded.set(g.id, t);
        }
        return t;
      }
      const key = g.state.texKey;
      if (!key || !bank[key]) return null;
      return services && services.texture ? services.texture(key) : buildTex(bank[key]);
    };
    const apply = g => {
      const map = currentMap(g);
      for (const m of g.mats) {
        if (g.state.mode === 'col') {
          m.map = null;
          m.color.set(g.state.color);
        } else if (map) {
          m.map = map;
          m.color.set(0xffffff);
        }
        m.needsUpdate = true;
      }
      if (map) {
        map.center.set(0.5, 0.5);
        map.rotation = ((g.state.rot || 0) * Math.PI) / 2;
        map.needsUpdate = true;
      }
      if (services && services.render) services.render();
    };

    const collect = () => {
      const src = [
        services && services.groups && services.groups.panels,
        services && services.groups && services.groups.profiles
      ].filter(Boolean);
      for (const grp of src)
        grp.traverse(o => {
          if (!o.isMesh || !o.userData || !o.userData.record || !o.material) return;
          const rec = o.userData.record,
            art = rec.tex || null;
          const id = art ? 'art:' + art : 'col:' + (rec.color || '#cccccc');
          let g = groups.get(id);
          if (!g) {
            g = {
              id,
              type: art ? 'tex' : 'col',
              name: art ? artName(art) : (rec.material || 'Цвет').split('\r')[0] || 'Цвет',
              names: new Set(),
              mats: new Set(),
              orig: { mode: art ? 'tex' : 'col', texKey: art, color: rec.color || '#cccccc' },
              state: {
                rot: 0,
                mode: art ? 'tex' : 'col',
                texKey: art,
                texData: null,
                color: rec.color || '#cccccc'
              }
            };
            groups.set(id, g);
          }
          g.names.add(rec.material || '—');
          g.mats.add(o.material);
        });
      for (const g of groups.values()) {
        const s = saved[g.id];
        if (s) {
          Object.assign(g.state, s);
          apply(g);
        }
      }
    };

    // ── публичный интерфейс (его же дёргают обработчики UI и проверка) ──
    const setState = (id, patch, { save = true } = {}) => {
      const g = groups.get(id);
      if (!g) return null;
      Object.assign(g.state, patch);
      uploaded.delete(id);
      apply(g);
      if (save) {
        saved[id] = Object.assign({}, g.state);
        persist();
      }
      if (g.row) refresh(g);
      return g;
    };
    const reset = id => {
      const g = groups.get(id);
      if (!g) return;
      g.state = { rot: 0, mode: g.orig.mode, texKey: g.orig.texKey, texData: null, color: g.orig.color };
      uploaded.delete(id);
      delete saved[id];
      persist();
      apply(g);
      if (g.row) refresh(g);
    };
    const list = () =>
      [...groups.values()].map(g => ({
        id: g.id,
        type: g.type,
        name: g.name,
        state: Object.assign({}, g.state)
      }));

    // ── UI ──
    // Строка материала — двухэтажная карточка: сверху превью + ПОЛНОЕ имя (длинные
    // артикулы теперь читаются целиком), снизу — только иконки функций: поворот,
    // цвет, замена, сброс. Замена спрятана под иконку с всплывающим списком (вшитые
    // текстуры + «Файл с диска…»), чтобы не тратить строку на широкий select.
    let wrap = null,
      picker = null,
      editor = null;
    const safeColor = c => (/^#([0-9a-f]{6})$/i.test(c || '') ? c : '#cccccc');
    const iconBtn = (txt, title, onclick) => {
      const b = doc.createElement('button');
      b.type = 'button';
      b.textContent = txt;
      b.title = title;
      b.setAttribute('aria-label', title);
      b.onclick = onclick;
      return b;
    };
    const buildUI = () => {
      if (!mount || !doc.getElementById) return;
      // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
      const $ = id => doc.getElementById(id);
      wrap = $('matEditorOpen');
      wrap.onclick = () => editor.showModal();
      editor = $('matEditor');
      $('matEditorClose').onclick = () => editor.close();
      doc.body.append(editor);
      editor.addEventListener('close', () => closePicker());
      services.materialToolsMount = $('matToolsMount');
      const listBox = $('matList');
      const sorted = [...groups.values()].sort(
        (a, b) => (a.type === b.type ? 0 : a.type === 'tex' ? -1 : 1) || a.name.localeCompare(b.name, 'ru')
      );
      for (const g of sorted) listBox.append(row(g));
      mount.append(wrap);
    };
    const thumbCss = g => {
      if (g.state.mode === 'tex') {
        const uri = g.state.texData || bank[g.state.texKey];
        return uri ? { img: 'url(' + uri + ')', bg: '' } : { img: '', bg: g.state.color };
      }
      return { img: '', bg: g.state.color };
    };
    const row = g => {
      const el = doc.createElement('div');
      el.className = 'matRow';
      g.row = el;
      const head = doc.createElement('div');
      head.className = 'matHead';
      const thumb = doc.createElement('span');
      thumb.className = 'matThumb';
      g.thumb = thumb;
      const name = doc.createElement('span');
      name.className = 'matName';
      name.translate = false;
      name.textContent = g.name;
      name.title = g.name;
      head.append(thumb, name);
      const tools = doc.createElement('div');
      tools.className = 'matTools';
      const rot = iconBtn('⟳', 'Повернуть текстуру на 90°', () =>
        setState(g.id, { rot: ((g.state.rot || 0) + 1) % 4 })
      );
      g.rotBtn = rot;
      const col = iconBtn('■', 'Залить сплошным цветом', () =>
        root.BazisColorPicker.open(doc, safeColor(g.state.color), color =>
          setState(g.id, { mode: 'col', color })
        )
      );
      g.colBtn = col;
      const file = doc.createElement('input');
      file.type = 'file';
      file.accept = 'image/*';
      g.file = file;
      file.setAttribute('aria-label', 'Загрузить текстуру');
      file.className = 'matFile';
      const status = doc.createElement('div');
      status.className = 'subtle';
      status.setAttribute('role', 'status');
      g.uploadStatus = status;
      file.onchange = () => {
        const f = file.files && file.files[0];
        if (!f) return;
        file.value = '';
        status.textContent = 'Загрузка текстуры…';
        fileToUri(f, uri => {
          if (uri) {
            setState(g.id, { mode: 'tex', texKey: null, texData: uri });
            status.textContent = 'Текстура заменена. Сохраните вид дискеткой, чтобы передать изменения.';
            closePicker();
          } else status.textContent = 'Не удалось прочитать изображение. Выберите JPEG, PNG или WebP.';
        });
      };
      const rep = iconBtn('🖼', 'Заменить текстуру', () => openPicker(g, rep));
      const rst = iconBtn('⤺', 'Сбросить к исходному материалу', () => reset(g.id));
      tools.append(rot, col, rep, rst);
      for (const renderTool of materialRowTools)
        renderTool({ id: g.id, type: g.type, name: g.name, materials: g.mats }, tools);
      el.append(head, tools, status);
      const legend = doc.createElement('div');
      legend.className = 'matMono';
      const caption = doc.createElement('span');
      caption.textContent = 'Монотон';
      legend.append(caption);
      for (const name of g.names) {
        const color = services.monoColor?.(name);
        if (!color) continue;
        const chip = doc.createElement('span');
        chip.className = 'matMonoChip';
        chip.translate = false;
        chip.title = name.split('\r').join(' · ') + ' — ' + color;
        chip.setAttribute('aria-label', chip.title);
        chip.style.background = color;
        legend.append(chip);
      }
      if (services.monoColor) el.append(legend);
      refresh(g);
      return el;
    };
    const refresh = g => {
      if (!g.row) return;
      const c = thumbCss(g);
      g.thumb.style.backgroundImage = c.img;
      g.thumb.style.backgroundColor = c.bg;
      if (g.colBtn) g.colBtn.style.color = safeColor(g.state.color);
      if (g.rotBtn) g.rotBtn.hidden = g.state.mode !== 'tex';
    };

    // всплывающий список замены: «Файл с диска…» + вшитые в модель текстуры
    const closePicker = () => {
      if (picker) {
        picker.remove();
        picker = null;
        W.removeEventListener && W.removeEventListener('pointerdown', onOutside, true);
      }
    };
    const onOutside = e => {
      if (picker && !(picker.contains && picker.contains(e.target))) closePicker();
    };
    const openPicker = (g, anchor) => {
      closePicker();
      if (!doc.body) return;
      const menu = doc.createElement('dialog');
      menu.className = 'matPicker';
      menu.setAttribute('aria-label', 'Замена текстуры');
      picker = menu;
      const item = (label, uri, run) => {
        const b = doc.createElement('button');
        b.type = 'button';
        const t = doc.createElement('span');
        t.className = 'pk';
        if (uri) t.style.backgroundImage = 'url(' + uri + ')';
        const s = doc.createElement('span');
        s.textContent = label;
        b.append(t, s);
        b.onclick = () => {
          closePicker();
          run();
        };
        menu.append(b);
      };
      const label = doc.createElement('label');
      label.textContent = 'Изображение с устройства';
      label.append(g.file);
      menu.append(label);
      menu.append(iconBtn('Закрыть', 'Закрыть замену текстуры', () => closePicker()));
      for (const k of Object.keys(bank))
        item(artName(k), bank[k], () => setState(g.id, { mode: 'tex', texKey: k, texData: null }));
      doc.body.append(menu);
      menu.showModal();
    };

    const fileToUri = (f, cb) => {
      try {
        const fr = new W.FileReader();
        fr.onload = () => {
          const img = new W.Image();
          img.onload = () => {
            try {
              const max = 1024,
                sc = Math.min(1, max / Math.max(img.width, img.height));
              const cv = doc.createElement('canvas');
              cv.width = Math.round(img.width * sc) || 1;
              cv.height = Math.round(img.height * sc) || 1;
              cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
              cb(cv.toDataURL('image/jpeg', 0.85));
            } catch (e) {
              cb(null);
            }
          };
          img.onerror = () => cb(null);
          img.src = fr.result;
        };
        fr.onerror = () => cb(null);
        fr.readAsDataURL(f);
      } catch (e) {
        cb(null);
      }
    };

    hooks.ready.push(() => {
      collect();
      buildUI();
    });

    return {
      name: 'materials',
      serialize: () => list(),
      restore: rows => {
        for (const r of rows || []) if (groups.has(r.id)) setState(r.id, r.state, { save: false });
      },
      schema: 1,
      list,
      set: setState,
      reset,
      groupCount: () => groups.size,
      dispose() {
        delete services.materialToolsMount;
        if (services.registerMaterialRowTool === registerMaterialRowTool)
          delete services.registerMaterialRowTool;
        closePicker();
        if (wrap) wrap.remove();
        if (editor) editor.remove();
        doc.querySelector?.('style[data-feature="materials"]')?.remove();
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'materials', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

styles:
.matList {
  max-height: 62vh;
  overflow: auto;
  min-width: 230px;
}
.matRow {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 3px;
  border-top: 1px solid var(--divider);
}
.matRow:first-child {
  border-top: 0;
}
.matHead {
  display: flex;
  align-items: center;
  gap: 9px;
}
.matThumb {
  width: 30px;
  height: 30px;
  border-radius: 6px;
  border: 1px solid var(--control-border);
  background-size: cover;
  background-position: center;
  flex: none;
}
.matName {
  font-size: 12.5px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}
.matTools {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-left: 39px;
}
.matTools > * {
  flex: none;
}
.matTools button {
  width: 31px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  padding: 0;
  border: 1px solid var(--control-border);
  background: #1d2b34;
  border-radius: 6px;
  cursor: pointer;
  color: var(--text);
}
.matTools input[type='color'] {
  width: 31px;
  height: 28px;
  padding: 0;
  border: 1px solid var(--control-border);
  border-radius: 6px;
  background: none;
  cursor: pointer;
}
.matPicker {
  position: fixed;
  z-index: 90;
  max-height: 52vh;
  overflow: auto;
  min-width: 210px;
  padding: 4px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
.matPicker button {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: var(--text);
  padding: 6px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
}
.matPicker button:hover,
.matPicker button:focus-visible {
  background: var(--hover);
}
.matPicker .pk {
  width: 22px;
  height: 22px;
  border-radius: 4px;
  border: 1px solid var(--control-border);
  background: #0003;
  background-size: cover;
  background-position: center;
  flex: none;
}

/* Раньше — встроенные стили в коде модуля. Селекторы сильнее прежних правил
   (.matPicker), потому что встроенный стиль их перебивал — так и осталось. */
#matEditor {
  width: 520px;
  max-width: calc(100vw - 24px);
  max-height: 85vh;
  overflow: auto;
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--popup-border);
  border-radius: 10px;
  padding: 14px;
}
#matEditor .matEditorHead {
  justify-content: space-between;
}
input.matFile {
  display: block;
  max-width: 100%;
  margin: 8px 0;
}
.matMono {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  padding-left: 39px;
  font-size: 11px;
}
.matMono .matMonoChip {
  display: inline-block;
  width: 20px;
  height: 20px;
  border: 1px solid #8ca1aa;
  border-radius: 4px;
}
dialog.matPicker {
  width: 360px;
  max-width: calc(100vw - 24px);
  max-height: 75vh;
  color: var(--text);
}

scripts:
(function (root) {
  'use strict';
  function install(context, bundle) {
    const { THREE: T, hooks, services, document: doc } = context;
    if (bundle?.schema !== 1) throw new Error('Несовместимый модуль масштаба текстур');
    const entries = [],
      byId = new Map(),
      modes = new Map(),
      controls = new Map();
    let disposed = false,
      unregister = null;
    const materialId = rec => (rec.tex ? 'art:' + rec.tex : 'col:' + (rec.color || '#cccccc'));
    // Стартовый режим материала: «Растянуть» в настройке текстур БАЗИСа → «На деталь».
    const initial = id => (bundle.defaults?.[id] === 'fit' ? 'fit' : 'tile');
    function addEntry(mesh) {
      const uv = mesh.geometry.attributes.uv;
      if (!uv) return;
      const source = Float32Array.from(uv.array);
      let minU = Infinity,
        minV = Infinity,
        maxU = -Infinity,
        maxV = -Infinity;
      for (let i = 0; i < uv.count; i++) {
        minU = Math.min(minU, uv.getX(i));
        maxU = Math.max(maxU, uv.getX(i));
        minV = Math.min(minV, uv.getY(i));
        maxV = Math.max(maxV, uv.getY(i));
      }
      if (maxU <= minU || maxV <= minV) return;
      const id = materialId(mesh.userData.record),
        entry = {
          id,
          mesh,
          uv,
          source,
          minU,
          minV,
          w: maxU - minU,
          h: maxV - minV,
          key: null,
          fitted: false
        };
      entries.push(entry);
      const list = byId.get(id) || [];
      list.push(entry);
      byId.set(id, list);
      if (!modes.has(id)) modes.set(id, initial(id));
    }
    function restoreEntry(entry) {
      if (!entry.fitted) return;
      entry.uv.array.set(entry.source);
      entry.uv.needsUpdate = true;
      entry.fitted = false;
      entry.key = null;
    }
    function updateEntry(entry) {
      if ((modes.get(entry.id) || 'tile') !== 'fit') {
        restoreEntry(entry);
        return;
      }
      const map = entry.mesh.material.map;
      if (!map) return;
      if (map.matrixAutoUpdate) map.updateMatrix();
      const key = map.matrix.elements.join(',');
      if (entry.fitted && key === entry.key) return;
      entry.key = key;
      const inverse = map.matrix.clone().invert(),
        point = new T.Vector2(),
        c = Math.cos(map.rotation),
        s = Math.sin(map.rotation);
      for (let i = 0; i < entry.uv.count; i++) {
        const u = (entry.source[i * 2] - entry.minU) / entry.w - 0.5,
          v = (entry.source[i * 2 + 1] - entry.minV) / entry.h - 0.5;
        point.set(c * u + s * v + 0.5, -s * u + c * v + 0.5).applyMatrix3(inverse);
        entry.uv.setXY(i, point.x, point.y);
      }
      entry.uv.needsUpdate = true;
      entry.fitted = true;
    }
    function update() {
      if (disposed) return;
      for (const entry of entries) updateEntry(entry);
    }
    function setMode(id, value) {
      const mode = value === 'fit' ? 'fit' : 'tile';
      modes.set(id, mode);
      const control = controls.get(id);
      if (control) control.value = mode;
      for (const entry of byId.get(id) || []) {
        entry.key = null;
        updateEntry(entry);
      }
      context.render?.();
      return mode;
    }
    function setEnabled(value) {
      const mode = value ? 'fit' : 'tile';
      for (const id of byId.keys()) setMode(id, mode);
    }
    function rowTool(material, mount) {
      if (material.type !== 'tex') return;
      const select = doc.createElement('select');
      select.setAttribute('data-material-texture-fit', material.id);
      select.setAttribute('aria-label', 'Масштаб текстуры: ' + material.name);
      select.title = 'Масштаб текстуры';
      for (const [value, text] of [
        ['tile', 'Тайл'],
        ['fit', 'На деталь']
      ]) {
        const option = doc.createElement('option');
        option.value = value;
        option.textContent = text;
        select.append(option);
      }
      select.value = modes.get(material.id) || initial(material.id);
      select.onchange = () => setMode(material.id, select.value);
      controls.set(material.id, select);
      mount.append(select);
    }
    if (services.registerMaterialRowTool) unregister = services.registerMaterialRowTool(rowTool);
    function ready() {
      for (const group of [services.groups.panels, services.groups.profiles])
        group?.traverse(mesh => {
          if (mesh.isMesh && ['panel', 'profile'].includes(mesh.userData?.kind) && mesh.userData.record?.tex)
            addEntry(mesh);
        });
      update();
    }
    // В снимок — только отличия от стартового режима (в т.ч. «Тайл» у растянутого в
    // БАЗИСе). Старые снимки хранили лишь «На деталь»: для них стартовый режим остаётся.
    function serialize() {
      return {
        schema: 2,
        modes: Object.fromEntries([...modes].filter(([id, mode]) => mode !== initial(id)))
      };
    }
    function restore(state) {
      if (typeof state === 'boolean') {
        setEnabled(state);
        return;
      }
      for (const id of byId.keys()) setMode(id, initial(id));
      for (const [id, mode] of Object.entries(state?.modes || {})) if (byId.has(id)) setMode(id, mode);
    }
    hooks.ready.push(ready);
    hooks.frame.push(update);
    return {
      name: 'texture_fit',
      setEnabled,
      setMode,
      update,
      serialize,
      restore,
      get enabled() {
        return [...modes.values()].some(mode => mode === 'fit');
      },
      get modes() {
        return new Map(modes);
      },
      dispose() {
        for (const entry of entries) restoreEntry(entry);
        disposed = true;
        for (const [list, fn] of [
          [hooks.ready, ready],
          [hooks.frame, update]
        ]) {
          const i = list.indexOf(fn);
          if (i >= 0) list.splice(i, 1);
        }
        unregister?.();
        for (const control of controls.values()) control.remove();
        controls.clear();
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'texture_fit', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

(function (root) {
  'use strict';
  function install(context, bundle) {
    const { THREE: T, hooks, services, scene, camera, canvas, document: doc } = context;
    if (bundle?.schema !== 1) throw new Error('Несовместимый модуль выносок материалов');
    let enabled = false,
      elapsed = 1,
      button = null,
      overlay = null,
      disposed = false,
      disposeMenu = null;
    let chips = null,
      chipLeader = null,
      tap = null,
      openName = null,
      chipKey = null,
      viewportEl = null;
    // Узкий экран — лента чипов вместо боковых выносок (см. стили .materialChips).
    const mobile = () => {
      try {
        return !!(win.matchMedia && win.matchMedia('(max-width:760px)').matches);
      } catch (e) {
        return false;
      }
    };
    const labels = new Map(),
      anchors = new Map(),
      ray = new T.Raycaster(),
      pointer = new T.Vector2();
    const board = root.BazisCallouts.board(services);
    // Какие материалы показывать в сносках. Дефолт приходит из сборки (bundle.materials,
    // фурнитурная мелочь скрыта), правки пользователя храним по КЛЮЧУ (артикул, иначе
    // имя) в localStorage — держатся между выгрузками и моделями. Материалы, которых
    // нет в списке (например синтетические из проверки), показываем по умолчанию.
    const win = context.window || root,
      STORE = 'bazisMaterialCallouts';
    const defaults = new Map((bundle.materials || []).map(m => [m.key, !!m.callout]));
    let overrides = {};
    try {
      overrides = JSON.parse(win.localStorage.getItem(STORE)) || {};
    } catch (e) {
      overrides = {};
    }
    const saveOverrides = () => {
      try {
        win.localStorage.setItem(STORE, JSON.stringify(overrides));
      } catch (e) {}
    };
    const keyOf = name => {
      const p = (name || '').split('\r'),
        art = (p[1] || '').trim();
      return art || (name || '').trim();
    };
    const calloutOn = name => {
      const k = keyOf(name);
      return k in overrides ? !!overrides[k] : defaults.has(k) ? defaults.get(k) : true;
    };
    // changedAt — когда выноски переключили в последний раз (руками или из снимка).
    // Выгрузка с «Активировать выноски» (bundle.enabled) главнее снимков, сделанных
    // ДО неё (bundle.built_at): иначе старый view.json с выключенными выносками
    // перебивал бы галочку. Выключили после выгрузки и сохранили — уважаем.
    let changedAt = null,
      still = 0,
      fresh = true;
    function restore(value) {
      const on = value && typeof value === 'object' ? !!value.enabled : !!value,
        at = value && typeof value === 'object' ? value.changedAt || null : null;
      if (bundle.enabled && !on && !(at && bundle.built_at && at > bundle.built_at)) return;
      changedAt = at;
      setEnabled(on, false);
    }
    function setEnabled(value, mark = true) {
      enabled = !!value;
      elapsed = 1;
      fresh = true;
      if (button) button.checked = enabled;
      if (mark) changedAt = new Date().toISOString();
      if (!enabled) {
        for (const item of labels.values()) {
          item.box.style.display = 'none';
          item.line.style.display = 'none';
        }
        anchors.clear();
        board.set('material_labels', []);
        if (chips) {
          chips.classList.remove('on');
          chips.textContent = '';
        }
        chipKey = null;
        closeChip();
      }
    }
    function ready() {
      const viewport = doc.getElementById('viewport');
      viewportEl = viewport;
      // разметка — markup.html (сборщик кладёт её в #featureMarkup)
      overlay = doc.getElementById('materialCalloutsLayer');
      chips = doc.getElementById('materialChips');
      chipLeader = doc.getElementById('materialChipLeader');
      viewport.append(overlay, chips);
      // Тап по детали раскрывает карточку её материала: на телефоне в чипе только артикул.
      tap = event => {
        if (!enabled || !mobile()) return;
        const object = services.pick?.(event),
          name = object ? nameOf(object) : null;
        if (name && calloutOn(name)) openChip(name);
        else closeChip();
      };
      canvas.addEventListener('pointerup', tap);
      button = doc.getElementById('materialCallouts');
      button.onchange = () => setEnabled(button.checked);
      const label = doc.getElementById('materialCalloutsControl');
      const mount = context.layersMount || context.toolMount;
      mount.append(label);
      buildList(mount);
      if (bundle.enabled) setEnabled(true, false);
    }
    // Выпадающий чек-лист «что показывать в сносках»: все материалы панелей/профилей,
    // галочка = текущее состояние. Мастер-чекбокс #materialCallouts оставляем как есть.
    function buildList(mount) {
      const list = bundle.materials || [];
      const menu = doc.getElementById('materialCalloutsList');
      if (!list.length) {
        menu.remove();
        return;
      }
      const box = doc.getElementById('materialCalloutsBox');
      const bulk = (id, on) => {
        doc.getElementById(id).onclick = () => {
          for (const m of list) {
            overrides[m.key] = on;
            const cb = boxes.get(m.key);
            if (cb) cb.checked = on;
          }
          saveOverrides();
          update();
        };
      };
      bulk('materialCalloutsAll', true);
      bulk('materialCalloutsNone', false);
      const boxes = new Map();
      for (const m of list) {
        const lab = doc.createElement('label');
        lab.className = 'check';
        const cb = doc.createElement('input');
        cb.type = 'checkbox';
        cb.checked = calloutOn(m.name);
        boxes.set(m.key, cb);
        cb.onchange = () => {
          overrides[m.key] = cb.checked;
          saveOverrides();
          update();
        };
        const sp = doc.createElement('span');
        sp.textContent = (m.name.split('\r')[0] || m.name).trim();
        sp.translate = false; // название материала — данные
        sp.title = m.name.split('\r').join(' · ');
        lab.append(cb, sp);
        box.append(lab);
      }
      mount.append(menu);
      disposeMenu = services.portalToolMenu?.(menu) || null;
    }
    const nameOf = o =>
      ['panel', 'profile'].includes(o.userData?.kind) ? o.userData.record?.material || '—' : null;
    function projected(point) {
      return point.clone().project(camera);
    }
    function inView(p) {
      return p.z >= -1 && p.z <= 1 && Math.abs(p.x) < 0.98 && Math.abs(p.y) < 0.98;
    }
    function update() {
      if (!enabled || !overlay || disposed) return;
      scene.updateMatrixWorld(true);
      camera.updateMatrixWorld(true);
      // Заслоны — всё, кроме фурнитуры: её сотни мелких мешей с сотнями тысяч
      // треугольников (W-110.26) делали проверку ~0.7 с, а ручка или петля перед
      // точкой выноски погоды не делают. Крупный импорт (ящики, мойка) остаётся.
      const meshes = [];
      for (const [key, group] of Object.entries(services.groups))
        if (key !== 'hardware')
          group.traverse(o => {
            if (o.isMesh && services.visible(o) && !o.userData.decorative && o.layers.test(camera.layers))
              meshes.push(o);
          });
      const found = new Map();
      function probe(point, expected = null) {
        const p = projected(point);
        if (!inView(p)) return false;
        pointer.set(p.x, p.y);
        ray.setFromCamera(pointer, camera);
        const hit = ray.intersectObjects(meshes, false).find(h => services.pointVisible?.(h.point) !== false);
        if (!hit) return false;
        const name = nameOf(hit.object);
        if (name && calloutOn(name) && !found.has(name))
          found.set(name, { point: hit.point.clone(), object: hit.object });
        return name === expected;
      }
      // Keep the previous attachment while it remains visible: labels do not jump
      // between shelves on every camera movement.
      for (const [name, anchor] of anchors)
        if (services.visible(anchor.object) && services.pointVisible?.(anchor.point) !== false)
          probe(anchor.point, name);
      for (const mesh of meshes) {
        const name = nameOf(mesh);
        if (!name || found.has(name)) continue;
        if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
        const box = mesh.geometry.boundingBox;
        if (!box || box.isEmpty()) continue;
        const center = box.getCenter(new T.Vector3()),
          points = [center.clone()];
        for (const axis of ['x', 'y', 'z'])
          for (const end of ['min', 'max']) {
            const p = center.clone();
            p[axis] = box[end][axis];
            points.push(p);
          }
        // AABB centres alone can miss narrow or milled details. Sample actual faces.
        const position = mesh.geometry.attributes.position,
          index = mesh.geometry.index,
          count = index ? index.count : position.count;
        for (let i = 0; i < Math.min(6, Math.floor(count / 3)); i++) {
          const offset = Math.floor((i * Math.floor(count / 3)) / 6) * 3,
            p = new T.Vector3();
          for (let j = 0; j < 3; j++)
            p.add(new T.Vector3().fromBufferAttribute(position, index ? index.getX(offset + j) : offset + j));
          points.push(p.multiplyScalar(1 / 3));
        }
        for (const p of points) if (probe(p.applyMatrix4(mesh.matrixWorld), name)) break;
      }
      anchors.clear();
      for (const [name, anchor] of found) anchors.set(name, anchor);
      layout();
    }
    function label(name) {
      if (labels.has(name)) return labels.get(name);
      const box = doc.createElement('div');
      box.className = 'materialCallout';
      box.title = name.split('\r').join(' · ');
      box.setAttribute('data-i18n-skip', ''); // в title — название материала
      const title = doc.createElement('strong'),
        article = doc.createElement('small'),
        parts = name.split('\r');
      title.textContent = parts[0] || 'Материал без названия';
      article.textContent = parts[1]?.trim() || 'Артикул не указан';
      title.translate = !parts[0]; // название и артикул — данные, заглушки — переводим
      article.translate = !parts[1]?.trim();
      box.append(title, article);
      const color = services.monoColor?.(name);
      if (color) box.style.borderLeft = '4px solid ' + color;
      const line = doc.createElement('div');
      line.className = 'materialLeader';
      overlay.append(line, box);
      const item = { box, line };
      labels.set(name, item);
      return item;
    }
    // Видимые сейчас материалы — общий источник и для боковых выносок, и для чипов.
    function shownNames() {
      const out = [];
      for (const [name, anchor] of anchors) {
        const p = projected(anchor.point);
        if (inView(p) && services.pointVisible?.(anchor.point) !== false) out.push(name);
      }
      return out.sort();
    }
    function layoutChips() {
      if (!chips) return;
      const names = shownNames(),
        key = names.join('|');
      if (key !== chipKey) {
        chipKey = key;
        chips.textContent = '';
        for (const name of names) {
          const parts = name.split('\r'),
            article = (parts[1] || '').trim(),
            title = (parts[0] || '').trim();
          const chip = doc.createElement('button');
          chip.type = 'button';
          chip.className = 'materialChip';
          chip.translate = false;
          chip.dataset.material = name;
          const swatch = doc.createElement('span');
          swatch.className = 'sw';
          const color = services.monoColor?.(name);
          if (color) swatch.style.background = color;
          // Свёрнуто — только артикул; раскрыто — «артикул · название» одной строкой
          // с горизонтальной прокруткой (на телефоне переносить некуда).
          const short = doc.createElement('span');
          short.className = 'short';
          short.textContent = article || title;
          const full = doc.createElement('span');
          full.className = 'full';
          full.textContent = article ? article + ' · ' + title : title;
          chip.title = parts.join(' · ');
          chip.append(swatch, short, full);
          chip.onclick = () => {
            openName === name ? closeChip() : openChip(name);
          };
          chips.append(chip);
        }
      }
      chips.classList.add('on');
      if (openName && names.indexOf(openName) < 0) closeChip();
      for (const chip of chips.children) chip.classList.toggle('open', chip.dataset.material === openName);
      drawChipLeader();
    }
    // Сноска: линия от раскрытой выноски к самой детали — как на широком экране.
    function drawChipLeader() {
      if (!chipLeader) return;
      const anchor = openName ? anchors.get(openName) : null;
      const chip = openName && chips ? [...chips.children].find(c => c.dataset.material === openName) : null;
      if (!anchor || !chip || !viewportEl || services.pointVisible?.(anchor.point) === false) {
        chipLeader.style.display = 'none';
        return;
      }
      const p = projected(anchor.point);
      if (!inView(p)) {
        chipLeader.style.display = 'none';
        return;
      }
      const view = viewportEl.getBoundingClientRect(),
        box = chip.getBoundingClientRect();
      const x1 = box.right - view.left,
        y1 = box.top - view.top + box.height / 2;
      const x2 = ((p.x + 1) * view.width) / 2,
        y2 = ((1 - p.y) * view.height) / 2;
      chipLeader.style.cssText =
        'display:block;left:' +
        x1 +
        'px;top:' +
        y1 +
        'px;width:' +
        Math.hypot(x2 - x1, y2 - y1) +
        'px;transform:rotate(' +
        Math.atan2(y2 - y1, x2 - x1) +
        'rad)';
    }
    function openChip(name) {
      openName = name;
      if (chips)
        for (const chip of chips.children) {
          const on = chip.dataset.material === name;
          chip.classList.toggle('open', on);
          if (on && chip.scrollIntoView)
            try {
              chip.scrollIntoView({ block: 'nearest' });
            } catch (e) {}
        }
      drawChipLeader();
    }
    function closeChip() {
      openName = null;
      if (chips) for (const chip of chips.children) chip.classList.remove('open');
      if (chipLeader) chipLeader.style.display = 'none';
    }
    function layout() {
      if (!overlay) return;
      const rect = canvas.getBoundingClientRect(),
        w = rect.width,
        h = rect.height;
      for (const item of labels.values()) {
        item.box.style.display = 'none';
        item.line.style.display = 'none';
      }
      if (mobile()) {
        board?.set('material_labels', []);
        board?.layout(w, h);
        layoutChips();
        return;
      }
      if (chips && chips.classList.contains('on')) {
        chips.classList.remove('on');
        chipKey = null;
        closeChip();
      }
      // Раскладку по краям делает общий board (callout_board.js) — совместно с
      // карточками других модулей (заметки), чтобы они не перекрывались.
      const entries = [];
      for (const [name, anchor] of anchors) {
        const p = projected(anchor.point);
        if (!inView(p) || services.pointVisible?.(anchor.point) === false) continue;
        const item = label(name);
        entries.push({
          key: name,
          x: ((p.x + 1) * w) / 2,
          y: ((1 - p.y) * h) / 2,
          box: item.box,
          line: item.line
        });
      }
      board.set('material_labels', entries);
      board.layout(w, h);
    }
    // Пока камера движется, видимость не пересчитываем: выноски едут за прежними
    // точками (layout дешёвый), а лучевая проверка — когда камера замерла на 0.2 с.
    // Иначе при вращении тяжёлой модели кадр каждые 250 мс проседал на всю проверку.
    const lastCamera = new T.Matrix4();
    function frame(delta) {
      if (!enabled) return;
      camera.updateMatrixWorld();
      if (!camera.matrixWorld.equals(lastCamera)) {
        lastCamera.copy(camera.matrixWorld);
        still = 0;
      } else still += delta;
      elapsed += delta;
      if (elapsed >= 0.25 && (still >= 0.2 || fresh)) {
        elapsed = 0;
        fresh = false;
        update();
      } else layout();
    }
    hooks.ready.push(ready);
    hooks.frame.push(frame);
    function dispose() {
      if (disposed) return;
      setEnabled(false);
      disposed = true;
      for (const [list, fn] of [
        [hooks.ready, ready],
        [hooks.frame, frame]
      ]) {
        const i = list.indexOf(fn);
        if (i >= 0) list.splice(i, 1);
      }
      disposeMenu?.();
      overlay?.remove();
      if (tap) canvas.removeEventListener('pointerup', tap);
      chips?.remove();
      chipLeader?.remove();
      chips = chipLeader = null;
      doc.getElementById('materialCalloutsControl')?.remove();
      doc.getElementById('materialCalloutsList')?.remove();
      doc.querySelector?.('style[data-feature="material_labels"]')?.remove();
      labels.clear();
      board.remove('material_labels');
    }
    return {
      name: 'material_labels',
      serialize: () => ({ enabled, changedAt }),
      restore,
      setEnabled,
      update,
      dispose,
      get enabled() {
        return enabled;
      },
      get visibleMaterials() {
        return [...anchors.keys()];
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else
    (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'material_labels', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

styles:
.materialCallouts {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 4;
}
.materialCallout {
  position: absolute;
  width: 166px;
  box-sizing: border-box;
  padding: 5px 7px;
  background: #15232de8;
  border: 1px solid #7e9aa5;
  border-radius: 5px;
  color: #eff7fa;
  font: 12px/16px system-ui;
  pointer-events: none;
}
.materialCallout strong,
.materialCallout small {
  display: block;
  white-space: normal;
  overflow-wrap: anywhere;
}
/* артикул — тем же размером, что название, и голубым: читается с первого взгляда */
.materialCallout small {
  font-size: inherit;
  font-weight: 600;
  color: #7ddcff;
}
.materialLeader {
  position: absolute;
  height: 1px;
  background: #aec6d0;
  transform-origin: 0 0;
  pointer-events: none;
}
/* Телефон: боковые выноски занимали пол-экрана, поэтому показываем ленту чипов
   снизу — только кружок цвета и артикул. Полное название открывается карточкой. */
.materialChips {
  position: absolute;
  left: 0;
  bottom: var(--hardwareBarH, 8px);
  display: none;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  max-height: 52vh;
  overflow-y: auto;
  overflow-x: hidden;
  z-index: 5;
  pointer-events: auto;
  scrollbar-width: none;
}
.materialChips::-webkit-scrollbar {
  display: none;
}
.materialChips.on {
  display: flex;
}
.materialChip {
  display: flex;
  align-items: center;
  gap: 6px;
  max-width: 93vw;
  padding: 4px 10px 4px 7px;
  border: 1px solid #7e9aa5;
  border-left: 0;
  border-radius: 0 999px 999px 0;
  background: #15232dee;
  color: #eff7fa;
  font: 12px/16px system-ui;
  white-space: nowrap;
  cursor: pointer;
  box-shadow: 0 2px 8px #0006;
}
.materialChip .sw {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  flex: none;
  background: #8fa6b1;
}
/* артикул на чипе телефона — как в карточке: голубой и полужирный */
.materialChip .short {
  font-weight: 600;
  color: #7ddcff;
}
.materialChip .full {
  display: none;
  overflow-x: auto;
  scrollbar-width: none;
}
.materialChip .full::-webkit-scrollbar {
  display: none;
}
.materialChip.open {
  border-color: #74d9cf;
  background: #22384a;
}
.materialChip.open .short {
  display: none;
}
.materialChip.open .full {
  display: block;
  max-width: 86vw;
}
.materialChipLeader {
  position: absolute;
  height: 1px;
  background: #aec6d0;
  transform-origin: 0 0;
  pointer-events: none;
  display: none;
}

/* Меню «В сносках…»: кнопки «Все/Никого» и прокручиваемый список материалов */
.materialCalloutsBulk {
  display: flex;
  gap: 8px;
  margin-bottom: 6px;
}
.materialCalloutsBulk button {
  padding: 3px 8px;
  font-size: 11px;
}
.materialCalloutsBox {
  max-height: 58vh;
  overflow: auto;
  min-width: 230px;
}

scripts:
(function (root) {
  'use strict';
  // Заметки: точка на детали + текст (и фото), выноской сбоку, как у материалов.
  // Ставятся, правятся и удаляются прямо на странице; хранятся в сохраняемых
  // настройках вида (serialize/restore). Фото — файлы notes/<хэш>.jpg рядом со
  // страницей: в заметке только имя, сами файлы отдаёт attachments() — их кладёт на
  // GitHub дискетка github_save вместе с view.json.
  function install(context, bundle) {
    const { THREE: T, hooks, services, camera, canvas, document: doc } = context,
      win = context.window || root;
    if (bundle?.schema !== 1) throw new Error('Несовместимый модуль заметок');
    const board = root.BazisCallouts.board(services),
      ray = new T.Raycaster(),
      pointer = new T.Vector2(),
      views = new Map();
    let notes = [],
      enabled = true,
      adding = false,
      disposed = false,
      installed = false,
      elapsed = 1;
    let overlay = null,
      tools = null,
      toolItems = null,
      showBox = null,
      addButton = null,
      status = null,
      listMenu = null,
      listSummary = null,
      listBox = null,
      disposeMenu = null;
    let dialog = null,
      dialogTitle = null,
      dialogMeta = null,
      area = null,
      saveButton = null,
      deleteButton = null,
      editing = null,
      focusTimer = null;
    // Статическая разметка — в markup.html (сборщик кладёт её в #featureMarkup).
    const $ = id => doc.getElementById(id);
    const HINT = 'Заметки сохраняются вместе с видом — дискеткой «Сохранить на GitHub».';

    // ---- фото ----
    const IMAGE_DIR = 'notes',
      MAX_SIDE = 1600,
      MAX_IMAGES = 12,
      imageName = /^[0-9a-f]{16}\.jpg$/;
    // ещё не отправленные на GitHub: имя → {base64 | null (уже отправлено), url}
    const pending = new Map();
    let draftImages = [],
      imagesBox = null,
      photoInput = null,
      photoHint = null,
      imageView = null;
    const imageUrl = name => pending.get(name)?.url || IMAGE_DIR + '/' + name;
    const toBase64 = bytes => {
      let binary = '';
      for (let i = 0; i < bytes.length; i += 0x8000)
        binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
      return win.btoa(binary);
    };
    // Имя — хэш содержимого: одинаковые фото не дублируются, кэш браузера не врёт.
    async function hashName(bytes) {
      let hex;
      if (win.crypto?.subtle) {
        const digest = new Uint8Array(await win.crypto.subtle.digest('SHA-256', bytes));
        hex = [...digest.slice(0, 8)].map(b => b.toString(16).padStart(2, '0')).join('');
      } else {
        // без crypto.subtle (редкие старые браузеры) — FNV-1a двумя 32-битными половинами
        let a = 0x811c9dc5,
          b = 0x01000193;
        for (const byte of bytes) {
          a = Math.imul(a ^ byte, 0x01000193) >>> 0;
          b = Math.imul(b ^ byte, 0x811c9dc5) >>> 0;
        }
        hex = a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0');
      }
      return hex + '.jpg';
    }
    async function decode(file) {
      if (win.createImageBitmap) return win.createImageBitmap(file); // с поворотом по EXIF
      const url = win.URL.createObjectURL(file);
      try {
        const img = new win.Image();
        img.src = url;
        await img.decode();
        return img;
      } finally {
        win.URL.revokeObjectURL(url);
      }
    }
    // Фото с телефона — 3–8 МБ; уменьшаем до MAX_SIDE по длинной стороне, JPEG ~0.85.
    async function prepareImage(file) {
      const source = await decode(file),
        w = source.width,
        h = source.height,
        scale = Math.min(1, MAX_SIDE / Math.max(w, h));
      const canvasEl = doc.createElement('canvas');
      canvasEl.width = Math.max(1, Math.round(w * scale));
      canvasEl.height = Math.max(1, Math.round(h * scale));
      canvasEl.getContext('2d').drawImage(source, 0, 0, canvasEl.width, canvasEl.height);
      source.close?.();
      const blob = await new Promise(resolve => canvasEl.toBlob(resolve, 'image/jpeg', 0.85));
      if (!blob) throw new Error('не удалось сжать фото');
      const bytes = new Uint8Array(await blob.arrayBuffer()),
        name = await hashName(bytes);
      if (!pending.has(name))
        pending.set(name, { base64: toBase64(bytes), url: win.URL.createObjectURL(blob) });
      return name;
    }
    // Просмотр фото заметки: листание стрелками (кнопки, ← →), счётчик «1 / 3».
    let viewList = [],
      viewIndex = 0;
    function showImage(index) {
      viewIndex = (index + viewList.length) % viewList.length;
      $('noteImageViewImg').src = imageUrl(viewList[viewIndex]);
      const many = viewList.length > 1;
      $('noteImageViewPrev').hidden = $('noteImageViewNext').hidden = !many;
      $('noteImageViewCount').hidden = !many;
      $('noteImageViewCount').textContent = viewIndex + 1 + ' / ' + viewList.length;
    }
    function openImage(name, list) {
      viewList = list && list.length ? [...list] : [name];
      showImage(Math.max(0, viewList.indexOf(name)));
      if (imageView.open) imageView.close();
      imageView.showModal();
    }
    function renderDraft() {
      imagesBox.textContent = '';
      for (const name of draftImages) {
        const thumb = doc.createElement('div');
        thumb.className = 'noteThumb';
        const img = doc.createElement('img');
        img.src = imageUrl(name);
        img.alt = 'Фото заметки';
        img.onclick = () => openImage(name, draftImages);
        const drop = doc.createElement('button');
        drop.type = 'button';
        drop.textContent = '×';
        drop.title = 'Убрать фото из заметки';
        drop.setAttribute('aria-label', drop.title);
        drop.onclick = () => {
          draftImages = draftImages.filter(n => n !== name);
          renderDraft();
        };
        thumb.append(img, drop);
        imagesBox.append(thumb);
      }
      saveButton.disabled = !area.value.trim() && !draftImages.length;
    }
    async function addPhotos(files) {
      const list = [...(files || [])].filter(f => /^image\//.test(f.type));
      for (const file of list) {
        if (draftImages.length >= MAX_IMAGES) {
          photoHint.textContent = 'Не больше ' + MAX_IMAGES + ' фото в одной заметке.';
          break;
        }
        try {
          const name = await prepareImage(file);
          if (!draftImages.includes(name)) draftImages.push(name);
        } catch (error) {
          photoHint.textContent = 'Не удалось добавить фото: ' + error.message;
        }
        renderDraft();
      }
    }

    const EYE =
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M1 12s4-7 11-7 11 7 11 7-4 7-11 7S1 12 1 12z"/><circle cx="12" cy="12" r="3"/></svg>';
    const EYE_OFF =
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M1 12s4-7 11-7 11 7 11 7-4 7-11 7S1 12 1 12z"/><circle cx="12" cy="12" r="3"/><path d="M3 3l18 18"/></svg>';
    const CAMERA =
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h3l2-3h6l2 3h3v12H4z"/><circle cx="12" cy="13" r="3.5"/></svg>';
    // «📷 N» — пометка заметки с фото (карточка, список)
    function photoMark(count) {
      const mark = doc.createElement('span');
      mark.className = 'notePhotoMark';
      mark.innerHTML = CAMERA;
      mark.append(String(count));
      mark.title = 'Фото: ' + count;
      return mark;
    }
    let noteMenu = null,
      menuNote = null;
    const round = v => Math.round(v * 1000) / 1000;
    const newId = () => 'n' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    const finite3 = a => Array.isArray(a) && a.length === 3 && a.every(v => Number.isFinite(Number(v)));
    function describe(rec) {
      if (!rec) return '';
      const parts = [String(rec.name || 'Деталь').trim()];
      if (rec.artpos) parts.push('поз. ' + rec.artpos);
      return parts.join(' · ');
    }
    // Точку храним двумя способами: в координатах детали (заметка едет вместе с ней —
    // разнос сборки, правка модели) и в мировых (запас, если детали больше нет).
    function anchorOf(note) {
      if (note.objectId != null && note.local) {
        const object = (services.renderedById?.get(note.objectId) || []).find(o => o.isMesh);
        if (object) {
          object.updateMatrixWorld(true);
          return { object, point: object.localToWorld(new T.Vector3(...note.local)) };
        }
      }
      return { object: null, point: new T.Vector3(...note.point) };
    }
    function targets() {
      const out = [];
      for (const group of Object.values(services.groups || {}))
        group.traverse(o => {
          if (o.isMesh && services.visible(o) && !o.userData.decorative && o.layers.test(camera.layers))
            out.push(o);
        });
      return out;
    }
    const pointOk = p => services.pointVisible?.(p) !== false;
    function hitAt(event) {
      const r = canvas.getBoundingClientRect();
      pointer.set(
        ((event.clientX - r.left) / r.width) * 2 - 1,
        (-(event.clientY - r.top) / r.height) * 2 + 1
      );
      ray.setFromCamera(pointer, camera);
      return ray.intersectObjects(targets(), false).find(h => pointOk(h.point)) || null;
    }
    function fromHit(hit) {
      const object = hit.object,
        rec = object.userData?.record,
        p = hit.point;
      const note = {
        id: newId(),
        text: '',
        point: [p.x, p.y, p.z].map(round),
        objectId: null,
        local: null,
        element: describe(rec)
      };
      if (rec?.id != null && !object.isInstancedMesh) {
        object.updateMatrixWorld(true);
        const l = object.worldToLocal(p.clone());
        note.objectId = rec.id;
        note.local = [l.x, l.y, l.z].map(round);
      }
      return note;
    }
    function occluded(point) {
      const distance = camera.position.distanceTo(point);
      if (distance < 1e-6) return false;
      ray.set(camera.position, point.clone().sub(camera.position).normalize());
      ray.far = distance;
      const hit = ray.intersectObjects(targets(), false).find(h => pointOk(h.point));
      ray.far = Infinity;
      return !!hit && hit.distance < distance - Math.max(0.5, distance * 0.0005);
    }

    // ---- карточки ----
    function view(note) {
      let item = views.get(note.id);
      if (!item) {
        const box = doc.createElement('div');
        box.className = 'noteCallout';
        box.dataset.note = note.id;
        const text = doc.createElement('span');
        text.className = 'noteText';
        const meta = doc.createElement('small');
        meta.translate = false; // подпись детали — данные модели
        // превью первого фото + «📷 N»; нажатие — просмотр, не редактор
        const photos = doc.createElement('div');
        photos.className = 'noteCardPhotos';
        const thumb = doc.createElement('img');
        thumb.alt = 'Фото заметки';
        thumb.loading = 'lazy';
        photos.append(thumb);
        photos.onclick = e => {
          e.stopPropagation();
          const note = current();
          if (note?.images?.length) openImage(note.images[0], note.images);
        };
        box.append(text, photos, meta);
        const line = doc.createElement('div');
        line.className = 'noteLeader';
        const dot = doc.createElement('div');
        dot.className = 'noteDot';
        const current = () => notes.find(n => n.id === box.dataset.note);
        let press = null,
          suppress = false;
        box.onclick = () => {
          if (suppress) {
            suppress = false;
            return;
          }
          const note = current();
          if (note) openEditor(note, false);
        };
        box.oncontextmenu = e => {
          e.preventDefault();
          e.stopPropagation();
          const note = current();
          if (note) openMenu(note, e.clientX, e.clientY);
        };
        // iOS не шлёт contextmenu на удержание — открываем меню сами через 550 мс
        box.addEventListener('pointerdown', e => {
          if (e.pointerType !== 'touch') return;
          suppress = false;
          const x = e.clientX,
            y = e.clientY;
          press = win.setTimeout(() => {
            suppress = true;
            const note = current();
            if (note) openMenu(note, x, y);
          }, 550);
        });
        for (const type of ['pointerup', 'pointercancel', 'pointerleave'])
          box.addEventListener(type, () => win.clearTimeout(press));
        overlay.append(line, dot, box);
        item = { box, text, meta, photos, thumb, line, dot, occluded: false };
        views.set(note.id, item);
      }
      const photos = note.images?.length || 0;
      item.text.textContent = note.text || 'Фото';
      item.text.translate = !note.text; // текст заметки не переводим, заглушку «Фото» — да
      item.text.hidden = !note.text && photos > 0;
      item.meta.textContent = note.element || '';
      item.meta.hidden = !note.element;
      item.photos.hidden = !photos;
      item.photos.querySelector('.notePhotoMark')?.remove();
      if (photos) {
        const src = imageUrl(note.images[0]);
        if (item.thumb.getAttribute('src') !== src) item.thumb.src = src;
        item.photos.append(photoMark(photos));
        item.photos.title = 'Открыть фото (' + photos + ')';
      }
      item.box.title =
        note.text +
        (note.element ? '\n' + note.element : '') +
        '\nНажмите, чтобы изменить; правая кнопка — меню';
      return item;
    }
    function hide(item) {
      item.box.style.display = 'none';
      item.line.style.display = 'none';
      item.dot.style.display = 'none';
    }
    function render() {
      if (!installed) return;
      const ids = new Set(notes.map(n => n.id));
      for (const [id, item] of views)
        if (!ids.has(id)) {
          item.box.remove();
          item.line.remove();
          item.dot.remove();
          views.delete(id);
        }
      for (const note of notes) view(note);
      renderList();
      elapsed = 1;
      layout();
    }
    function layout() {
      if (!installed || disposed) return;
      const rect = canvas.getBoundingClientRect(),
        w = rect.width,
        h = rect.height,
        entries = [];
      for (const note of notes) {
        const item = views.get(note.id);
        if (!item) continue;
        hide(item);
        if (!enabled || note.hidden) continue;
        const anchor = anchorOf(note);
        if (anchor.object && !services.visible(anchor.object)) continue;
        if (!pointOk(anchor.point)) continue;
        const p = anchor.point.clone().project(camera);
        if (p.z < -1 || p.z > 1 || Math.abs(p.x) > 0.98 || Math.abs(p.y) > 0.98) continue;
        const x = ((p.x + 1) * w) / 2,
          y = ((1 - p.y) * h) / 2;
        for (const el of [item.box, item.line, item.dot]) el.classList.toggle('occluded', item.occluded);
        item.dot.style.display = 'block';
        item.dot.style.left = x + 'px';
        item.dot.style.top = y + 'px';
        entries.push({ key: 'note:' + note.id, x, y, box: item.box, line: item.line });
      }
      board.set('notes', entries);
      board.layout(w, h);
    }
    function checkOcclusion() {
      for (const note of notes) {
        const item = views.get(note.id);
        if (item) item.occluded = occluded(anchorOf(note).point);
      }
    }
    function frame(delta) {
      if (!installed || (!notes.length && !views.size)) return;
      elapsed += delta;
      if (elapsed >= 0.25) {
        elapsed = 0;
        if (enabled) checkOcclusion();
      }
      layout();
    }

    // ---- режим добавления и редактор ----
    function setStatus(text) {
      if (status) status.textContent = text;
    }
    function setAdding(value) {
      adding = !!value && !services.isMeasuring?.();
      canvas.style.cursor = adding ? 'crosshair' : '';
      addButton?.setAttribute('aria-pressed', String(adding));
      setStatus(adding ? 'Щёлкните по детали, куда поставить заметку. Esc — отмена.' : HINT);
    }
    function canvasClick(event) {
      if (!adding) return false;
      const hit = hitAt(event);
      if (!hit) {
        setStatus('Мимо детали: щёлкните по её поверхности. Esc — отмена.');
        return true;
      }
      setAdding(false);
      openEditor(fromHit(hit), true);
      return true;
    }
    function openEditor(note, isNew) {
      editing = { note, isNew };
      dialogTitle.textContent = isNew ? 'Новая заметка' : 'Заметка';
      dialogMeta.textContent = note.element || 'Точка без привязки к детали';
      dialogMeta.translate = !note.element;
      area.value = note.text || '';
      deleteButton.hidden = isNew;
      draftImages = [...(note.images || [])];
      photoHint.textContent = photoHint.dataset.text;
      renderDraft();
      if (dialog.open) dialog.close();
      dialog.showModal();
      area.focus();
    }
    function saveEditor() {
      if (!editing) return;
      const text = area.value.trim();
      if (!text && !draftImages.length) return;
      const { note, isNew } = editing;
      note.text = text;
      if (draftImages.length) note.images = [...draftImages];
      else delete note.images;
      note.updated = new Date().toISOString();
      if (isNew) notes.push(note);
      dialog.close();
      if (!enabled) setEnabled(true);
      render();
    }
    function remove(note) {
      notes = notes.filter(n => n !== note && n.id !== note.id);
      render();
    }
    function buildDialog() {
      dialog = $('noteEditor');
      dialogTitle = $('noteEditorTitle');
      dialogMeta = $('noteEditorMeta');
      area = $('noteEditorText');
      deleteButton = $('noteEditorDelete');
      saveButton = $('noteEditorSave');
      area.oninput = () => {
        saveButton.disabled = !area.value.trim() && !draftImages.length;
      };
      imagesBox = $('noteEditorImages');
      photoInput = $('noteEditorPhoto');
      photoHint = $('noteEditorPhotoHint');
      photoHint.dataset.text = photoHint.textContent;
      $('noteEditorAddPhoto').onclick = () => photoInput.click();
      photoInput.onchange = () => {
        const files = photoInput.files;
        addPhotos(files).finally(() => {
          photoInput.value = '';
        });
      };
      imageView = $('noteImageView');
      $('noteImageViewClose').onclick = () => imageView.close();
      $('noteImageViewImg').onclick = () => imageView.close();
      $('noteImageViewPrev').onclick = () => showImage(viewIndex - 1);
      $('noteImageViewNext').onclick = () => showImage(viewIndex + 1);
      imageView.addEventListener('keydown', e => {
        if (viewList.length < 2) return;
        if (e.key === 'ArrowLeft') showImage(viewIndex - 1);
        else if (e.key === 'ArrowRight') showImage(viewIndex + 1);
      });
      doc.body.append(imageView);
      area.onkeydown = e => {
        if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
          e.preventDefault();
          saveEditor();
        }
      };
      deleteButton.onclick = () => {
        if (editing && !editing.isNew) {
          const note = editing.note;
          dialog.close();
          remove(note);
        }
      };
      saveButton.onclick = saveEditor;
      $('noteEditorCancel').onclick = () => dialog.close();
      dialog.addEventListener('close', () => {
        editing = null;
      });
      doc.body.append(dialog);
    }

    // ---- панель «Заметки» ----
    function setHidden(note, value) {
      note.hidden = !!value;
      render();
    }
    function buildMenu() {
      noteMenu = $('noteMenu');
      const item = (id, run) => {
        $(id).onclick = () => {
          const note = menuNote;
          closeMenu();
          if (note) run(note);
        };
      };
      item('noteMenuHide', note => setHidden(note, true));
      item('noteMenuEdit', note => openEditor(note, false));
      item('noteMenuDelete', note => {
        if (!win.confirm || win.confirm('Удалить заметку?')) remove(note);
      });
      doc.body.append(noteMenu);
    }
    function openMenu(note, x, y) {
      if (!noteMenu) return;
      menuNote = note;
      noteMenu.hidden = false;
      const box = noteMenu.getBoundingClientRect();
      noteMenu.style.left = Math.max(6, Math.min(x, win.innerWidth - box.width - 6)) + 'px';
      noteMenu.style.top = Math.max(6, Math.min(y, win.innerHeight - box.height - 6)) + 'px';
      noteMenu.querySelector('button')?.focus?.();
    }
    function closeMenu() {
      if (noteMenu) noteMenu.hidden = true;
      menuNote = null;
    }
    const outsideMenu = e => {
      if (noteMenu && !noteMenu.hidden && !noteMenu.contains(e.target)) closeMenu();
    };
    function focusNote(note) {
      if (!enabled) setEnabled(true);
      if (note.hidden) setHidden(note, false);
      if (note.objectId != null) services.selectId?.(note.objectId);
      const item = views.get(note.id);
      if (!item) return;
      for (const other of views.values()) other.box.classList.remove('focus');
      item.box.classList.add('focus');
      clearTimeout(focusTimer);
      focusTimer = setTimeout(() => item.box.classList.remove('focus'), 1600);
    }
    function renderList() {
      if (!listBox) return;
      listSummary.textContent = 'Список (' + notes.length + ')';
      listBox.textContent = '';
      if (!notes.length) {
        const empty = doc.createElement('div');
        empty.className = 'noteEmpty';
        empty.textContent = 'Заметок пока нет';
        listBox.append(empty);
        return;
      }
      for (const note of notes) {
        const row = doc.createElement('div');
        row.className = 'noteItem' + (note.hidden ? ' noteOff' : '');
        const go = doc.createElement('button');
        go.type = 'button';
        go.className = 'noteGo';
        const full = note.text || 'Фото',
          label = doc.createElement('span');
        label.textContent = full.length > 70 ? full.slice(0, 70) + '…' : full;
        label.translate = !note.text;
        go.append(label);
        if (note.images?.length) go.prepend(photoMark(note.images.length), ' ');
        if (note.element) {
          const small = doc.createElement('small');
          small.textContent = note.element;
          small.translate = false;
          go.append(small);
        }
        go.onclick = () => {
          listMenu.open = false;
          focusNote(note);
        };
        const eye = doc.createElement('button');
        eye.type = 'button';
        eye.className = 'noteIcon noteEye';
        eye.innerHTML = note.hidden ? EYE_OFF : EYE;
        eye.title = note.hidden ? 'Показать заметку' : 'Скрыть заметку';
        eye.setAttribute('aria-label', eye.title);
        eye.setAttribute('aria-pressed', String(!!note.hidden));
        eye.onclick = () => setHidden(note, !note.hidden);
        const edit = doc.createElement('button');
        edit.type = 'button';
        edit.className = 'noteIcon';
        edit.textContent = '✎';
        edit.title = 'Изменить';
        edit.setAttribute('aria-label', 'Изменить заметку');
        edit.onclick = () => {
          listMenu.open = false;
          openEditor(note, false);
        };
        const del = doc.createElement('button');
        del.type = 'button';
        del.className = 'noteIcon';
        del.textContent = '×';
        del.title = 'Удалить';
        del.setAttribute('aria-label', 'Удалить заметку');
        del.onclick = () => {
          if (!win.confirm || win.confirm('Удалить заметку?')) remove(note);
        };
        row.append(go, eye, edit, del);
        listBox.append(row);
      }
    }
    function buildTools() {
      const made = services.createToolRow?.('notesOpen', 'Заметки', open => {
        if (!open) setAdding(false);
      });
      tools = made ? made.row : context.toolMount;
      toolItems = $('notesToolItems');
      showBox = $('notesShow');
      showBox.checked = enabled;
      showBox.onchange = () => setEnabled(showBox.checked);
      addButton = $('notesAdd');
      addButton.onclick = () => setAdding(!adding);
      listMenu = $('notesList');
      listSummary = $('notesListSummary');
      listBox = $('notesListBox');
      status = $('notesStatus');
      tools.append(toolItems);
      disposeMenu = services.portalToolMenu?.(listMenu) || null;
      setStatus(HINT);
    }
    function setEnabled(value) {
      enabled = !!value;
      if (showBox) showBox.checked = enabled;
      elapsed = 1;
      layout();
    }
    function keydown(event) {
      if (event.key !== 'Escape') return;
      closeMenu();
      if (adding) setAdding(false);
    }
    function ready() {
      const viewport = doc.getElementById('viewport');
      overlay = doc.createElement('div');
      overlay.className = 'noteCallouts';
      viewport.append(overlay);
      buildDialog();
      buildMenu();
      buildTools();
      installed = true;
      render();
    }
    hooks.ready.push(ready);
    hooks.frame.push(frame);
    hooks.canvasClick.push(canvasClick);
    doc.addEventListener('keydown', keydown);
    doc.addEventListener('pointerdown', outsideMenu, true);

    function serialize() {
      return { enabled, notes: notes.map(n => ({ ...n })) };
    }
    // Мягко: снимок мог быть сделан на прежней версии модели или прийти битым —
    // негодные записи пропускаем, остальное применяем.
    function restore(value) {
      if (!value || typeof value !== 'object') return;
      const list = Array.isArray(value) ? value : value.notes;
      notes = (Array.isArray(list) ? list : [])
        .filter(n => n && typeof n.text === 'string' && finite3(n.point))
        .map(n => ({
          images: Array.isArray(n.images) ? n.images.filter(name => imageName.test(name)) : [],
          n
        }))
        .filter(({ images, n }) => n.text.trim() || images.length)
        .map(({ images, n }) => ({
          id: String(n.id || newId()),
          text: n.text,
          point: n.point.map(Number),
          objectId: n.objectId ?? null,
          local: finite3(n.local) ? n.local.map(Number) : null,
          element: typeof n.element === 'string' ? n.element : '',
          updated: n.updated || null,
          hidden: n.hidden === true,
          ...(images.length ? { images } : {})
        }));
      if (typeof value.enabled === 'boolean') enabled = value.enabled;
      if (showBox) showBox.checked = enabled;
      render();
    }
    function dispose() {
      if (disposed) return;
      disposed = true;
      setAdding(false);
      for (const [list, fn] of [
        [hooks.ready, ready],
        [hooks.frame, frame],
        [hooks.canvasClick, canvasClick]
      ]) {
        const i = list.indexOf(fn);
        if (i >= 0) list.splice(i, 1);
      }
      doc.removeEventListener('keydown', keydown);
      doc.removeEventListener('pointerdown', outsideMenu, true);
      noteMenu?.remove();
      clearTimeout(focusTimer);
      disposeMenu?.();
      board.remove('notes');
      overlay?.remove();
      dialog?.remove();
      imageView?.remove();
      for (const { url } of pending.values()) win.URL.revokeObjectURL(url);
      doc.querySelector?.('style[data-feature="notes"]')?.remove();
      views.clear();
      if (tools && tools !== context.toolMount) {
        doc.getElementById('notesOpen')?.remove();
        tools.remove();
      } else toolItems?.remove();
    }
    // Файлы рядом со страницей для дискетки: в notes/ должны лежать ровно эти фото;
    // base64 — у ещё не отправленных. Лишние файлы из notes/ дискетка удаляет.
    function attachments() {
      const names = new Set();
      for (const note of notes) for (const name of note.images || []) names.add(name);
      return {
        dir: IMAGE_DIR,
        files: [...names].map(name => {
          const base64 = pending.get(name)?.base64;
          return base64 ? { name, base64 } : { name };
        })
      };
    }
    function attachmentsSaved(names) {
      for (const name of names || []) {
        const entry = pending.get(name);
        if (entry) entry.base64 = null; // картинку оставляем в памяти до перезагрузки
      }
    }
    return {
      name: 'notes',
      serialize,
      restore,
      attachments,
      attachmentsSaved,
      addPhotos,
      setEnabled,
      setAdding,
      openEditor,
      dispose,
      get enabled() {
        return enabled;
      },
      get adding() {
        return adding;
      },
      get notes() {
        return notes.map(n => ({ ...n }));
      },
      // открыть редактор самой заметки (openEditor с копией из .notes правил бы копию)
      edit(id) {
        const note = notes.find(n => n.id === id);
        if (note) openEditor(note, false);
      },
      setHidden(id, value) {
        const note = notes.find(n => n.id === id);
        if (note) setHidden(note, value);
      },
      add(note) {
        if (note && typeof note.text === 'string' && finite3(note.point)) {
          notes.push({ id: newId(), objectId: null, local: null, element: '', ...note });
          render();
        }
      },
      remove(id) {
        const note = notes.find(n => n.id === id);
        if (note) remove(note);
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'notes', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

styles:
.noteCallouts {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 4;
}
.noteCallout {
  position: absolute;
  display: none;
  box-sizing: border-box;
  padding: 5px 7px;
  background: #2b2616ee;
  border: 1px solid #9c8545;
  border-left: 4px solid #e2b93b;
  border-radius: 5px;
  color: #fbf5e3;
  font: 12px/16px system-ui;
  pointer-events: auto;
  cursor: pointer;
}
.noteCallout .noteText {
  display: block;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-height: 96px;
  overflow: hidden;
}
.noteCallout .noteText[hidden] {
  display: none;
}
.noteCallout small {
  display: block;
  margin-top: 2px;
  color: #d9c89a;
  overflow-wrap: anywhere;
}
.noteCallout:hover,
.noteCallout.focus {
  border-color: #ffd970;
  background: #3a3219f4;
}
.noteCallout.occluded {
  opacity: 0.62;
}
.noteLeader {
  position: absolute;
  display: none;
  height: 0;
  border-top: 1px solid #e2b93b;
  transform-origin: 0 0;
  pointer-events: none;
}
.noteLeader.occluded {
  border-top-style: dashed;
  opacity: 0.7;
}
.noteDot {
  position: absolute;
  display: none;
  width: 8px;
  height: 8px;
  margin: -4px 0 0 -4px;
  border-radius: 50%;
  background: #e2b93b;
  box-shadow: 0 0 0 2px #2b2616;
  pointer-events: none;
}
.noteDot.occluded {
  opacity: 0.5;
}
#viewport.measuring .noteCallout {
  pointer-events: none;
}
.noteStatus {
  font-size: 11px;
  color: var(--muted-soft);
  max-width: 340px;
}
.noteList {
  min-width: 250px;
  max-height: 58vh;
  overflow: auto;
}
.noteItem {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 2px;
  border-top: 1px solid var(--divider);
}
.noteItem:first-child {
  border-top: 0;
}
.noteItem .noteGo {
  flex: 1;
  min-width: 0;
  text-align: left;
  background: none;
  border: 0;
  color: inherit;
  padding: 2px;
  cursor: pointer;
  font-size: 12px;
  line-height: 1.3;
  overflow-wrap: anywhere;
}
.noteItem .noteGo small {
  display: block;
  color: var(--muted-soft);
}
.noteItem button.noteIcon {
  flex: none;
  width: 28px;
  height: 26px;
  padding: 0;
  display: inline-grid;
  place-items: center;
}
.noteItem button.noteIcon svg {
  width: 16px;
  height: 16px;
}
.noteItem.noteOff .noteGo {
  opacity: 0.5;
}
.noteMenu {
  position: fixed;
  z-index: 85;
  min-width: 190px;
  padding: 5px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
.noteMenu[hidden] {
  display: none;
}
.noteMenu button {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: inherit;
  padding: 6px 8px;
  border-radius: 5px;
  cursor: pointer;
}
.noteMenu button:hover,
.noteMenu button:focus-visible {
  background: var(--hover);
}
.noteEmpty {
  font-size: 12px;
  color: var(--muted-soft);
  padding: 4px;
}
.noteEditor {
  width: 440px;
  max-width: calc(100vw - 24px);
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--popup-border);
  border-radius: 10px;
  padding: 14px;
}
.noteEditor::backdrop {
  background: #0006;
}
.noteEditor small {
  display: block;
  color: var(--muted-soft);
  margin: 2px 0 8px;
  overflow-wrap: anywhere;
}
.noteEditor textarea {
  display: block;
  width: 100%;
  min-height: 110px;
  box-sizing: border-box;
  resize: vertical;
  background: #0f1a21;
  color: var(--text);
  border: 1px solid var(--control-border);
  border-radius: 6px;
  padding: 8px;
  font: 13px/1.4 system-ui;
}
.noteEditor .noteButtons {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  margin-top: 10px;
}
.noteEditor .noteButtons .noteDelete {
  margin-right: auto;
}

.notesToolItems {
  display: contents;
}

/* фото заметки: миниатюры в редакторе и просмотр в полный размер */
.noteImages {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}
.noteImages:empty {
  display: none;
}
.noteThumb {
  position: relative;
  width: 72px;
  height: 72px;
  border: 1px solid var(--control-border);
  border-radius: 6px;
  overflow: hidden;
  background: var(--divider);
}
.noteThumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  cursor: zoom-in;
  display: block;
}
.noteThumb button {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 22px;
  height: 22px;
  padding: 0;
  border-radius: 50%;
  line-height: 20px;
  background: #17232dd9;
}
.notePhotoRow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.notePhotoRow button {
  flex: none;
  white-space: nowrap;
}
.noteEditor .notePhotoRow small {
  margin: 0;
  font-size: 11px;
}
.noteImageView {
  max-width: calc(100vw - 24px);
  max-height: calc(100vh - 24px);
  padding: 0;
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  background: #0b1318;
}
.noteImageView::backdrop {
  background: #000b;
}
.noteImageView img {
  display: block;
  max-width: calc(100vw - 26px);
  max-height: calc(100vh - 26px);
  cursor: zoom-out;
}
.noteImageView button {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 30px;
  height: 30px;
  padding: 0;
  border-radius: 50%;
  background: #17232dd9;
}
.noteImageView .noteImageNav {
  top: 50%;
  width: 40px;
  height: 40px;
  margin-top: -20px;
  font-size: 26px;
  line-height: 36px;
}
#noteImageViewPrev {
  left: 6px;
  right: auto;
}
#noteImageViewNext {
  right: 6px;
}
.noteImageCount {
  position: absolute;
  left: 50%;
  bottom: 8px;
  transform: translateX(-50%);
  padding: 2px 8px;
  border-radius: 10px;
  background: #17232dd9;
  font-size: 12px;
}

/* пометка «📷 N» и превью первого фото на карточке у модели */
.notePhotoMark {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 0 5px;
  border-radius: 9px;
  background: #7ddcff26;
  color: #7ddcff;
  font-size: 11px;
  font-weight: 600;
  line-height: 16px;
  vertical-align: middle;
}
.notePhotoMark svg {
  width: 13px;
  height: 13px;
}
.noteCallout .noteCardPhotos {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  cursor: zoom-in;
}
.noteCallout .noteCardPhotos[hidden] {
  display: none;
}
.noteCallout .noteCardPhotos img {
  width: 56px;
  height: 42px;
  object-fit: cover;
  border-radius: 4px;
  border: 1px solid #9c8545;
  background: #1c1a12;
}

scripts:
(function (root) {
  'use strict';
  // «Однотонная фурнитура». По умолчанию выключена: фурнитура и импортированные тела
  // рисуются своими цветами и текстурами. Включённая — заливает их одним цветом.
  // Материалы у мешей ПОДМЕНЯЮТСЯ, а не перекрашиваются: материалы в шаблоне общие
  // (кэш по цвету и текстуре), перекраска задела бы профили того же цвета.
  // Отверстия (меши на скрытом слое и их InstancedMesh) не трогаются.
  function install(context, bundle) {
    const { THREE: T, hooks, services, document: doc } = context;
    if (bundle?.schema !== 1) throw new Error('Несовместимый модуль однотонной фурнитуры');
    const color = bundle.color || '#b7c4d2',
      originals = new Map(),
      monos = new Map();
    let on = false,
      box = null,
      label = null,
      disposed = false;
    const KINDS = ['hardware', 'import'];
    function meshes() {
      const out = [];
      for (const key of ['hardware', 'imports']) {
        const group = services.groups?.[key];
        if (group)
          group.traverse(o => {
            if (
              o.isMesh &&
              !o.isInstancedMesh &&
              KINDS.includes(o.userData?.kind) &&
              !Number.isInteger(o.userData?.holeIndex)
            )
              out.push(o);
          });
      }
      return out;
    }
    // Один однотонный материал на каждый исходный: прозрачность стекла сохраняется.
    function monoFor(material) {
      let mono = monos.get(material);
      if (!mono) {
        mono = new T.MeshStandardMaterial({
          color,
          roughness: 0.7,
          metalness: 0.05,
          side: T.DoubleSide,
          transparent: !!material.transparent,
          opacity: material.opacity ?? 1,
          depthWrite: material.depthWrite !== false
        });
        monos.set(material, mono);
      }
      return mono;
    }
    function apply() {
      for (const mesh of meshes()) {
        if (on) {
          if (!originals.has(mesh)) originals.set(mesh, mesh.material);
          mesh.material = monoFor(originals.get(mesh));
        } else if (originals.has(mesh)) {
          mesh.material = originals.get(mesh);
          originals.delete(mesh);
        }
      }
    }
    function setMono(value) {
      on = !!value;
      if (box) box.checked = on;
      if (!disposed) apply();
    }
    function ready() {
      // разметка — markup.html (сборщик кладёт её в #featureMarkup)
      label = doc.getElementById('hardwareMonoControl');
      box = doc.getElementById('hardwareMono');
      box.checked = on;
      box.onchange = () => setMono(box.checked);
      (context.layersMount || context.toolMount).append(label);
      apply();
    }
    hooks.ready.push(ready);
    function dispose() {
      if (disposed) return;
      on = false;
      apply();
      disposed = true;
      const i = hooks.ready.indexOf(ready);
      if (i >= 0) hooks.ready.splice(i, 1);
      for (const m of monos.values()) m.dispose();
      monos.clear();
      label?.remove();
    }
    return {
      name: 'hardware_mono',
      serialize: () => on,
      restore: v => setMono(v === true),
      setMono,
      dispose,
      get mono() {
        return on;
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'hardware_mono', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

(function (root) {
  'use strict';
  const CODES = new Set(['KeyW', 'KeyA', 'KeyS', 'KeyD', 'KeyQ', 'KeyE']);
  const editable = target =>
    target?.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target?.tagName || '');
  function install(context, options = {}) {
    const { THREE, camera, controls, canvas, hooks, document: doc, window: win, hintMount } = context;
    if (!THREE || !camera || !controls || !canvas || !hooks || !Array.isArray(hooks.frame) || !doc || !win)
      throw new Error('Просмотрщик не поддерживает навигационный модуль');
    const pressed = new Set(),
      speedFactor = Number(options.speed_factor) || 0.8;
    const forward = new THREE.Vector3(),
      right = new THREE.Vector3(),
      up = new THREE.Vector3(),
      movement = new THREE.Vector3();
    const down = event => {
      if (!CODES.has(event.code) || editable(event.target)) return;
      pressed.add(event.code);
      event.preventDefault();
    };
    const release = event => pressed.delete(event.code);
    const clear = () => pressed.clear();
    doc.addEventListener('keydown', down);
    doc.addEventListener('keyup', release);
    win.addEventListener('blur', clear);
    hooks.frame.push(delta => {
      if (!pressed.size) return;
      forward.subVectors(controls.target, camera.position).normalize();
      up.copy(camera.up).normalize();
      right.crossVectors(forward, up).normalize();
      movement.set(0, 0, 0);
      if (pressed.has('KeyW')) movement.add(forward);
      if (pressed.has('KeyS')) movement.sub(forward);
      if (pressed.has('KeyD')) movement.add(right);
      if (pressed.has('KeyA')) movement.sub(right);
      if (pressed.has('KeyE')) movement.add(up);
      if (pressed.has('KeyQ')) movement.sub(up);
      if (!movement.lengthSq()) return;
      movement.normalize().multiplyScalar(camera.position.distanceTo(controls.target) * speedFactor * delta);
      camera.position.add(movement);
      controls.target.add(movement);
    });
    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    if (hintMount) hintMount.append(doc.getElementById('navigationHint'));
    const label = canvas.getAttribute('aria-label') || 'Трёхмерная модель';
    canvas.setAttribute('aria-label', label + '; WASD — движение; Q и E — вниз и вверх');
    return {
      name: 'navigation',
      pressed,
      dispose() {
        doc.removeEventListener('keydown', down);
        doc.removeEventListener('keyup', release);
        win.removeEventListener('blur', clear);
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'navigation', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

(function (root) {
  'use strict';
  // Привязки замера к рёбрам — как в SketchUp / Inventor. Шаблон сам привязывается
  // только к вершинам; этот модуль через hooks.snapCandidates добавляет кандидатов
  // с ребра под курсором:
  //   конечная точка (rank 0)  — концы ребра;
  //   середина       (rank 1)  — голубой значок;
  //   перпендикуляр  (rank 1)  — основание перпендикуляра из первой точки замера,
  //                              пурпурный значок и пурпурная резиновая линия;
  //   на ребре       (rank 4)  — ближайшая к лучу точка ребра, красный значок.
  // Меньший rank важнее; при равном выигрывает ближний к курсору. Середина и
  // перпендикуляр намеренно равны: поперёк длинного ребра часто идёт короткое
  // ребро толщины панели, и его середина лежит в паре пикселей от основания
  // перпендикуляра — при строгом порядке она перебивала бы нужную точку.
  function install(context, data) {
    const { THREE: T, hooks, services, camera, controls, canvas } = context;
    if (data?.schema !== 1 || !Array.isArray(hooks?.snapCandidates))
      throw new Error('Несовместимый модуль привязок замера');
    const TOL = 12,
      HITS = 6,
      EXACT = 0.5;
    const ray = new T.Raycaster(),
      ndc = new T.Vector2();
    let objects = null,
      hash = null,
      disposed = false;

    // Рёбра строятся по «раздутой» геометрии (копланарные детали разведены на
    // 0.01–0.2 мм). Концы ребра притягиваем к точной вершине модели в пределах
    // 0.5 мм — тогда середина, перпендикуляр и сам замер считаются от точных
    // координат. Если точной вершины рядом нет (например, сборщик разнёс детали),
    // остаётся координата ребра.
    const cell = v => [Math.round(v.x), Math.round(v.y), Math.round(v.z)];
    function buildHash() {
      hash = new Map();
      for (const s of services.snaps || []) {
        const k = cell(s.v).join(',');
        let list = hash.get(k);
        if (!list) hash.set(k, (list = []));
        list.push(s.v);
      }
    }
    function exact(v) {
      if (!hash) buildHash();
      const [x, y, z] = cell(v);
      let best = null,
        bestD = EXACT * EXACT;
      for (let dx = -1; dx <= 1; dx++)
        for (let dy = -1; dy <= 1; dy++)
          for (let dz = -1; dz <= 1; dz++)
            for (const p of hash.get(x + dx + ',' + (y + dy) + ',' + (z + dz)) || []) {
              const d = p.distanceToSquared(v);
              if (d < bestD) {
                bestD = d;
                best = p;
              }
            }
      return best ? best.clone() : v;
    }
    function edgeObjects() {
      if (objects) return objects;
      objects = [...(services.edgeLineObjects || [])];
      services.groups?.lines?.traverse(o => {
        if (o.isLine) objects.push(o);
      });
      return objects;
    }
    function segment(hit) {
      const o = hit.object,
        pos = o.geometry.attributes.position,
        index = o.geometry.index,
        i = hit.index;
      if (!pos || i == null || i + 1 >= (index ? index.count : pos.count)) return null;
      const at = k =>
        new T.Vector3().fromBufferAttribute(pos, index ? index.getX(k) : k).applyMatrix4(o.matrixWorld);
      return [exact(at(i)), exact(at(i + 1))];
    }
    function candidates(query) {
      if (disposed || !services.isMeasuring?.()) return [];
      const rect = query.rect;
      if (!rect.width || !rect.height) return [];
      ndc.set((query.mx / rect.width) * 2 - 1, -(query.my / rect.height) * 2 + 1);
      ray.setFromCamera(ndc, camera);
      // Порог луча — в мировых единицах, с запасом; точный отбор по экранному
      // расстоянию делает шаблон.
      const depth = camera.position.distanceTo(controls?.target || new T.Vector3());
      ray.params.Line.threshold =
        ((depth * 2 * Math.tan((camera.fov * Math.PI) / 360)) / rect.height) * TOL * 2.5;
      const hits = ray
        .intersectObjects(edgeObjects(), false)
        .filter(h => services.visible?.(h.object) !== false);
      const out = [],
        seen = new Set(),
        first = query.firstPoint;
      for (const hit of hits) {
        if (out.length >= HITS * 4) break;
        const seg = segment(hit);
        if (!seg) continue;
        const [a, b] = seg,
          len = a.distanceTo(b);
        if (len < 0.05) continue;
        const key = [a, b]
          .map(v =>
            v
              .toArray()
              .map(n => n.toFixed(3))
              .join(',')
          )
          .sort()
          .join('|');
        if (seen.has(key)) continue;
        seen.add(key);
        const onEdge = new T.Vector3();
        ray.ray.distanceSqToSegment(a, b, null, onEdge);
        out.push({
          v: onEdge,
          object: hit.object,
          kind: 'edge',
          rank: 4,
          tol: TOL,
          hint: 'На ребре',
          color: 0xff6b6b
        });
        out.push({ v: a, object: hit.object, kind: 'endpoint', rank: 0, tol: 16, hint: 'Конечная точка' });
        out.push({ v: b, object: hit.object, kind: 'endpoint', rank: 0, tol: 16, hint: 'Конечная точка' });
        out.push({
          v: a.clone().add(b).multiplyScalar(0.5),
          object: hit.object,
          kind: 'midpoint',
          rank: 1,
          tol: 14,
          hint: 'Середина',
          color: 0x4fe3ff
        });
        if (first) {
          const dir = b.clone().sub(a),
            t = first.clone().sub(a).dot(dir) / dir.lengthSq();
          if (t > 1e-6 && t < 1 - 1e-6) {
            const foot = a.clone().addScaledVector(dir, t);
            if (foot.distanceTo(first) > 0.01)
              out.push({
                v: foot,
                object: hit.object,
                kind: 'perpendicular',
                rank: 1,
                tol: 14,
                hint: 'Перпендикуляр',
                color: 0xff5cf0
              });
          }
        }
      }
      return out;
    }
    hooks.snapCandidates.push(candidates);
    // Сборщик двигает детали — точные вершины и список рёбер пересчитываем.
    const reset = () => {
      hash = null;
      objects = null;
    };
    if (hooks.geometryChanged) hooks.geometryChanged.push(reset);
    return {
      name: 'measure_snaps',
      candidates,
      dispose() {
        disposed = true;
        for (const [list, fn] of [
          [hooks.snapCandidates, candidates],
          [hooks.geometryChanged, reset]
        ]) {
          const i = list ? list.indexOf(fn) : -1;
          if (i >= 0) list.splice(i, 1);
        }
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'measure_snaps', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

(function (root) {
  'use strict';
  function install(context, bundle) {
    const { THREE, data, hooks, services, canvas, document: doc, window: win } = context;
    const mount = context.selectionMount || context.toolMount; // блок «Выбор и видимость»
    if (
      !THREE ||
      !data ||
      !hooks ||
      !services ||
      !canvas ||
      !doc ||
      !win ||
      !mount ||
      !Array.isArray(bundle?.assembly_ids) ||
      bundle.assembly_ids.some(id => !Number.isInteger(id))
    )
      throw new Error('Просмотрщик не поддерживает модуль видимости');
    const assemblies = new Set(bundle.assembly_ids),
      hidden = new Set(),
      filters = new Map();
    const objectVisible = id => !hidden.has(id) && [...filters.values()].every(test => test(id));
    services.objectVisible = objectVisible;
    services.setVisibilityFilter = (name, test) => {
      if (test != null && typeof test !== 'function') throw new Error('Некорректный фильтр видимости');
      if (test) filters.set(name, test);
      else filters.delete(name);
      apply();
    };
    const treeCleanup = [];
    let treeSelecting = false;
    let objectMode = true,
      selected = null,
      lastRaw = null,
      touch = null,
      timer = null;
    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const $ = id => doc.getElementById(id);
    const tools = $('visibilityTools');
    const mode = $('visibilityMode');
    const restore = $('visibilityRestore');
    restore.disabled = true;
    mount.append(tools);
    const menu = $('visibilityMenu');
    const action = (id, run) => {
      const button = $(id);
      button.onclick = () => {
        close();
        run();
      };
      return button;
    };
    const hideButton = action('visibilityHideSelected', () => hideSelected());
    const hideSamePartsButton = action('visibilityHideSameParts', () => hideSameParts());
    const hideBlockButton = action('visibilityHideBlock', () => hideBlock());
    const hideSameBlocksButton = action('visibilityHideSameBlocks', () => hideSameBlocks());
    const hideUnitButton = action('visibilityHideUnit', () => hideUnit());
    const isolateButton = action('visibilityIsolate', () => isolateSelected());
    action('visibilityRestoreSelected', () => {
      for (const id of targetIds()) hidden.delete(id);
      apply();
    });
    doc.body.append(menu);

    function assemblyFor(object) {
      let rec = object?.userData?.record;
      while (rec) {
        if (assemblies.has(rec.id)) return { userData: { record: rec, kind: 'group' } };
        rec = services.sourceById?.get(rec.parent_id);
      }
      return object;
    }
    // Блок для «Скрыть блок»: от выбранного вверх до ближайшей сборочной единицы
    // (её саму не берём) — самый верхний блок (Type 1005) на этом пути. Выбрав
    // фасад, скрываем «Фасад ящика в сборе» целиком, соседние блоки сборки остаются.
    function blockFor(rec) {
      let top = null,
        seen = new Set();
      while (rec && !seen.has(rec.id) && !assemblies.has(rec.id)) {
        seen.add(rec.id);
        if (rec.type === 1005) top = rec;
        rec = services.sourceById?.get(rec.parent_id);
      }
      return top;
    }
    // «Аналогичные» — по названию (без артикула после \r): детали — того же типа,
    // что выбранная (панели, фурнитура…), блоки — все блоки с именем блока из
    // «Скрыть блок». Каждый скрывается со всем содержимым.
    const baseName = rec =>
      String(rec?.name || '')
        .split('\r')[0]
        .trim();
    function sameParts(rec) {
      if (!rec || rec.type === 1005 || assemblies.has(rec.id)) return [];
      const name = baseName(rec);
      if (!name) return [];
      return [...services.sourceById.values()].filter(r => r.type === rec.type && baseName(r) === name);
    }
    function sameBlocks(block) {
      if (!block) return [];
      const name = baseName(block);
      if (!name) return [];
      return [...services.sourceById.values()].filter(
        r => r.type === 1005 && !assemblies.has(r.id) && baseName(r) === name
      );
    }
    function hideAll(list) {
      if (!list.length) return;
      for (const r of list) for (const id of services.descendants(r.id)) hidden.add(id);
      apply();
      services.select(null);
    }
    function hideSameParts() {
      hideAll(selected ? sameParts(selected.userData.record) : []);
    }
    function hideSameBlocks() {
      hideAll(selected ? sameBlocks(blockFor(selected.userData.record)) : []);
    }
    // Ближайшая сборочная единица над выбранным (или оно само) — как в «Выбор: сборка».
    function unitFor(rec) {
      const seen = new Set();
      while (rec && !seen.has(rec.id)) {
        if (assemblies.has(rec.id)) return rec;
        seen.add(rec.id);
        rec = services.sourceById?.get(rec.parent_id);
      }
      return null;
    }
    function hideUnit() {
      const unit = selected && unitFor(selected.userData.record);
      if (unit) hideAll([unit]);
    }
    function hideBlock() {
      const block = selected && blockFor(selected.userData.record);
      if (!block) return;
      for (const id of services.descendants(block.id)) hidden.add(id);
      apply();
      services.select(null);
    }
    function updateMode() {
      mode.textContent = objectMode ? 'Выбор: объект' : 'Выбор: сборка';
      mode.setAttribute('aria-label', mode.textContent);
      mode.dataset.compactLabel = objectMode ? 'Объект' : 'Сборка';
      mode.setAttribute('aria-pressed', String(objectMode));
    }
    function targetIds() {
      return selected ? new Set(services.descendants(selected.userData.record.id)) : new Set();
    }
    function syncOptimizedHoles() {
      const holes = services.holeMeshes || [],
        group = services.groups?.holes;
      if (!holes.length || !group) return;
      const instanced = group.children.find(o => o.isInstancedMesh),
        rims = group.children.find(o => o.isLineSegments && o.userData.decorative);
      if (instanced) {
        const zero = new THREE.Matrix4().makeScale(0, 0, 0);
        for (let i = 0; i < holes.length; i++)
          instanced.setMatrixAt(
            i,
            !objectVisible(holes[i].userData.record.id) ? zero : services.holeMatrices[i]
          );
        instanced.instanceMatrix.needsUpdate = true;
      }
      if (rims) {
        const pos = rims.geometry.attributes.position,
          array = pos.array,
          original = services.holeRimPositions,
          chunk = original.length / holes.length;
        for (let i = 0; i < holes.length; i++) {
          const start = i * chunk,
            end = start + chunk;
          if (!objectVisible(holes[i].userData.record.id)) array.fill(0, start, end);
          else array.set(original.subarray(start, end), start);
        }
        pos.needsUpdate = true;
        rims.geometry.computeBoundingSphere();
      }
    }
    function apply() {
      for (const [id, objects] of services.renderedById)
        for (const object of objects) object.visible = objectVisible(id);
      for (const [id, entry] of services.treeEntries)
        entry.node.classList.toggle('visibilityHidden', !objectVisible(id));
      syncOptimizedHoles();
      restore.disabled = !hidden.size;
      services.updateHighlight();
    }
    function hideSelected() {
      if (!selected) return;
      for (const id of targetIds()) hidden.add(id);
      apply();
      services.select(null);
    }
    function isolateSelected() {
      if (!selected) return;
      const keep = targetIds();
      hidden.clear();
      for (const id of services.sourceById.keys()) if (!keep.has(id)) hidden.add(id);
      apply();
    }
    function restoreAll() {
      hidden.clear();
      apply();
    }
    function setObjectMode(on) {
      objectMode = !!on;
      updateMode();
      if (lastRaw) services.select(lastRaw);
    }
    function close() {
      menu.classList.add('hidden');
    }
    function open(x, y) {
      if (!selected) return;
      hideButton.disabled = [...targetIds()].every(id => hidden.has(id));
      const block = blockFor(selected.userData.record),
        blockName = String(block?.name || '')
          .split('\r')[0]
          .trim();
      hideBlockButton.disabled = !block || services.descendants(block.id).every(id => hidden.has(id));
      hideBlockButton.textContent = block
        ? 'Скрыть блок «' +
          (blockName.length > 40 ? blockName.slice(0, 39) + '…' : blockName || 'без имени') +
          '»'
        : 'Скрыть блок';
      const short = text => (text.length > 32 ? text.slice(0, 31) + '…' : text);
      const unit = unitFor(selected.userData.record);
      hideUnitButton.disabled = !unit || services.descendants(unit.id).every(id => hidden.has(id));
      hideUnitButton.textContent = unit
        ? 'Скрыть сборочную единицу «' + short(baseName(unit) || 'без имени') + '»'
        : 'Скрыть сборочную единицу';
      hideUnitButton.title = unit
        ? 'Скрыть сборочную единицу со всем содержимым'
        : 'Выбранное не входит в сборочную единицу';
      const parts = sameParts(selected.userData.record),
        blocks = sameBlocks(block);
      hideSamePartsButton.disabled = parts.length < 2;
      hideSameBlocksButton.disabled = blocks.length < 2;
      hideSamePartsButton.textContent = parts.length
        ? 'Скрыть все такие детали «' + short(baseName(parts[0])) + '» (' + parts.length + ')'
        : 'Скрыть все такие детали';
      hideSameBlocksButton.textContent = blocks.length
        ? 'Скрыть все такие блоки «' + short(baseName(block)) + '» (' + blocks.length + ')'
        : 'Скрыть все такие блоки';
      hideBlockButton.title = block
        ? 'Скрыть блок со всем содержимым; другие блоки сборочной единицы останутся'
        : 'Выбранное не входит в блок внутри сборочной единицы';
      isolateButton.disabled = false;
      menu.classList.remove('hidden');
      const box = menu.getBoundingClientRect();
      menu.style.left = Math.max(6, Math.min(x, win.innerWidth - box.width - 6)) + 'px';
      menu.style.top = Math.max(6, Math.min(y, win.innerHeight - box.height - 6)) + 'px';
      menu.querySelector('button:not(:disabled)')?.focus();
    }
    function selectAt(event) {
      const hit = services.pick?.(event);
      if (!hit) {
        close();
        return false;
      }
      services.select(hit);
      open(event.clientX, event.clientY);
      return true;
    }
    const onContext = event => {
      event.preventDefault();
      if (services.isMeasuring?.()) return;
      selectAt(event);
    };
    const cancelTouch = () => {
      if (timer) win.clearTimeout(timer);
      timer = null;
      touch = null;
    };
    const onDown = event => {
      if (event.pointerType !== 'touch' || services.isMeasuring?.()) return;
      touch = { id: event.pointerId, x: event.clientX, y: event.clientY };
      timer = win.setTimeout(() => {
        const point = touch;
        if (point) selectAt({ clientX: point.x, clientY: point.y });
        cancelTouch();
      }, 550);
    };
    const onMove = event => {
      if (touch?.id === event.pointerId && Math.hypot(event.clientX - touch.x, event.clientY - touch.y) > 10)
        cancelTouch();
    };
    canvas.addEventListener('contextmenu', onContext);
    canvas.addEventListener('pointerdown', onDown);
    canvas.addEventListener('pointermove', onMove);
    canvas.addEventListener('pointerup', cancelTouch);
    canvas.addEventListener('pointercancel', cancelTouch);
    const onDocumentDown = event => {
      if (!menu.contains(event.target)) close();
    };
    const onKey = event => {
      if (event.key === 'Escape') close();
    };
    doc.addEventListener('pointerdown', onDocumentDown);
    doc.addEventListener('keydown', onKey);
    mode.onclick = () => setObjectMode(!objectMode);
    restore.onclick = restoreAll;
    updateMode();
    hooks.selectionTarget.push(object => {
      lastRaw = object;
      return objectMode || treeSelecting ? object : assemblyFor(object);
    });
    hooks.selectionChanged.push(object => {
      selected = object;
    });
    hooks.selectionFields.push(rec => (assemblies.has(rec.id) ? [['Статус', 'Сборочная единица']] : []));
    hooks.ready.push(() => {
      services.holeMatrices = [];
      const instanced = services.groups.holes.children.find(o => o.isInstancedMesh),
        matrix = new THREE.Matrix4();
      if (instanced)
        for (let i = 0; i < services.holeMeshes.length; i++) {
          instanced.getMatrixAt(i, matrix);
          services.holeMatrices.push(matrix.clone());
        }
      const rims = services.groups.holes.children.find(o => o.isLineSegments && o.userData.decorative);
      services.holeRimPositions = rims
        ? new Float32Array(rims.geometry.attributes.position.array)
        : new Float32Array();
      for (const [id, entry] of services.treeEntries) {
        const el = entry.control;
        let press = null,
          start = null,
          suppress = false;
        const show = e => {
          treeSelecting = true;
          try {
            services.selectId(id);
          } finally {
            treeSelecting = false;
          }
          open(e.clientX, e.clientY);
        };
        const context = e => {
          e.preventDefault();
          e.stopPropagation();
          show(e);
        };
        const cancel = () => {
          if (press) win.clearTimeout(press);
          press = null;
          start = null;
        };
        const down = e => {
          if (e.pointerType !== 'touch') return;
          suppress = false;
          start = { x: e.clientX, y: e.clientY };
          press = win.setTimeout(() => {
            suppress = true;
            show({ clientX: start.x, clientY: start.y });
            cancel();
          }, 550);
        };
        const move = e => {
          if (start && Math.hypot(e.clientX - start.x, e.clientY - start.y) > 10) cancel();
        };
        const click = e => {
          if (suppress) {
            e.preventDefault();
            e.stopImmediatePropagation();
            suppress = false;
          }
        };
        for (const [event, fn] of [
          ['contextmenu', context],
          ['pointerdown', down],
          ['pointermove', move],
          ['pointerup', cancel],
          ['pointercancel', cancel],
          ['click', click]
        ]) {
          el.addEventListener(event, fn, true);
          treeCleanup.push(() => el.removeEventListener(event, fn, true));
        }
        treeCleanup.push(cancel);
      }
      for (const id of assemblies) {
        const entry = services.treeEntries.get(id);
        if (!entry) continue;
        const badge = doc.createElement('span');
        badge.className = 'assemblyBadge';
        badge.textContent = 'Сборочная единица';
        entry.control.append(badge);
      }
    });
    function dispose() {
      for (const clean of treeCleanup) clean();
      cancelTouch();
      canvas.removeEventListener('contextmenu', onContext);
      canvas.removeEventListener('pointerdown', onDown);
      canvas.removeEventListener('pointermove', onMove);
      canvas.removeEventListener('pointerup', cancelTouch);
      canvas.removeEventListener('pointercancel', cancelTouch);
      doc.removeEventListener('pointerdown', onDocumentDown);
      doc.removeEventListener('keydown', onKey);
      tools.remove();
      menu.remove();
      doc.querySelector?.('style[data-feature="visibility"]')?.remove();
    }
    return {
      name: 'visibility',
      serialize: () => ({ hidden: [...hidden], objectMode }),
      restore: s => {
        hidden.clear();
        for (const id of s.hidden || []) if (services.sourceById.has(id)) hidden.add(id);
        setObjectMode(s.objectMode);
        apply();
      },
      hidden,
      setObjectMode,
      hideSelected,
      hideBlock,
      hideSameParts,
      hideSameBlocks,
      hideUnit,
      unitFor: id => unitFor(services.sourceById.get(id))?.id ?? null,
      sameParts: id => sameParts(services.sourceById.get(id)).map(r => r.id),
      sameBlocks: id => sameBlocks(blockFor(services.sourceById.get(id))).map(r => r.id),
      blockFor: id => blockFor(services.sourceById.get(id))?.id ?? null,
      isolateSelected,
      restoreAll,
      dispose,
      get objectMode() {
        return objectMode;
      },
      get selectedId() {
        return selected?.userData?.record?.id ?? null;
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'visibility', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

styles:
.visibilityTools {
  display: flex;
  gap: 5px;
}
.visibilityTools button[aria-pressed='true'] {
  background: #35615e;
  border-color: #70c7b9;
}
.visibilityMenu {
  position: fixed;
  z-index: 80;
  min-width: 220px;
  padding: 5px;
  background: var(--panel);
  border: 1px solid var(--popup-border);
  border-radius: 8px;
  box-shadow: 0 12px 35px #0008;
}
.visibilityMenu button {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
}
.visibilityMenu button:hover,
.visibilityMenu button:focus-visible {
  background: var(--hover);
}
.visibilityHidden {
  opacity: 0.46;
}
.assemblyBadge {
  margin-left: 6px;
  padding: 1px 4px;
  border: 1px solid var(--popup-border);
  border-radius: 4px;
  color: var(--accent);
  font-size: 9px;
  white-space: nowrap;
}

scripts:
(function (root) {
  'use strict';
  function install(context, bundle) {
    const { THREE, data, hooks, services, document: doc } = context;
    const mount = context.selectionMount || context.toolMount; // блок «Выбор и видимость»
    if (
      !THREE ||
      !data ||
      !hooks ||
      !services ||
      !doc ||
      !mount ||
      bundle?.schema !== 2 ||
      !Array.isArray(bundle.panels)
    )
      throw new Error('Просмотрщик не поддерживает связи панели и крепежа');
    if (!Array.isArray(data.hardware)) throw new Error('В сцене нет данных фурнитуры');
    const relations = new Map(),
      meshedHardware = new Set(data.hardware.filter(record => record.mesh).map(record => record.id));
    for (const relation of bundle.panels) {
      if (
        !Number.isInteger(relation.panel_id) ||
        !Array.isArray(relation.hardware) ||
        relations.has(relation.panel_id)
      )
        throw new Error('Некорректные связи панели и крепежа');
      if (
        relation.hardware.some(
          item =>
            !Number.isInteger(item.id) ||
            !Array.isArray(item.holes) ||
            !Array.isArray(item.intersecting_holes) ||
            item.holes.some(index => !Number.isInteger(index) || index < 0) ||
            item.intersecting_holes.some(index => !item.holes.includes(index))
        )
      )
        throw new Error('Некорректные отверстия связанного крепежа');
      relations.set(relation.panel_id, relation.hardware);
    }
    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const button = doc.getElementById('panelHardwareToggle');
    mount.append(button);
    const hardwareOverlay = new THREE.Group(),
      holeOverlay = new THREE.Group();
    hardwareOverlay.name = 'Связанный крепёж';
    holeOverlay.name = 'Связанные отверстия';
    const hardwareMaterial = new THREE.MeshBasicMaterial({
      color: 0x26e5df,
      transparent: true,
      opacity: 0.82,
      depthTest: false,
      depthWrite: false
    });
    const holeMaterial = new THREE.MeshBasicMaterial({
      color: 0xffa34a,
      transparent: true,
      opacity: 0.92,
      depthTest: false,
      depthWrite: false
    });
    let active = false,
      selectedPanelId = null,
      ready = false;

    function clear(group) {
      while (group.children.length) {
        const child = group.children[0];
        group.remove(child);
      }
    }
    function cloneMesh(source, material, group) {
      source.updateWorldMatrix(true, false);
      const copy = new THREE.Mesh(source.geometry, material);
      copy.matrix.copy(source.matrixWorld);
      copy.matrixAutoUpdate = false;
      copy.renderOrder = 18;
      group.add(copy);
    }
    function redraw() {
      clear(hardwareOverlay);
      clear(holeOverlay);
      const linked = selectedPanelId == null ? null : relations.get(selectedPanelId);
      button.textContent = active && linked ? `Крепёж панели · ${linked.length}` : 'Крепёж панели';
      if (!ready || !active || !linked) return;
      const hardwareById = new Map(linked.map(item => [item.id, new Set(item.holes)]));
      for (const item of linked) {
        if (!meshedHardware.has(item.id)) continue;
        for (const object of services.renderedById.get(item.id) || [])
          object.traverse(child => {
            if (child.isMesh) cloneMesh(child, hardwareMaterial, hardwareOverlay);
          });
      }
      for (const mesh of services.holeMeshes || []) {
        const holes = hardwareById.get(mesh.userData.record.id);
        if (holes?.has(mesh.userData.holeIndex)) cloneMesh(mesh, holeMaterial, holeOverlay);
      }
    }
    function setActive(on) {
      active = !!on;
      button.setAttribute('aria-pressed', String(active));
      redraw();
    }
    function noun(count, one, few, many) {
      // по правилам языка интерфейса, если модуль перевода есть
      if (root.BazisI18n) return root.BazisI18n.plural(count, one, few, many);
      const tens = count % 100,
        units = count % 10;
      return units === 1 && tens !== 11
        ? one
        : units >= 2 && units <= 4 && (tens < 12 || tens > 14)
          ? few
          : many;
    }
    button.onclick = () => setActive(!active);
    hooks.selectionChanged.push(object => {
      selectedPanelId = object?.userData?.kind === 'panel' ? object.userData.record.id : null;
      redraw();
    });
    hooks.selectionFields.push((record, kind) => {
      if (kind !== 'panel') return [];
      const linked = relations.get(record.id) || [];
      const holes = linked.reduce((sum, item) => sum + item.holes.length, 0),
        intersections = linked.reduce((sum, item) => sum + item.intersecting_holes.length, 0);
      return [
        [
          'Связанный крепёж',
          `${linked.length} ${noun(linked.length, 'объект', 'объекта', 'объектов')} · ${holes} ${noun(holes, 'отверстие', 'отверстия', 'отверстий')}`
        ],
        ['Входят в панель', `${intersections} ${noun(intersections, 'отверстие', 'отверстия', 'отверстий')}`]
      ];
    });
    hooks.ready.push(() => {
      services.groups.hardware.add(hardwareOverlay);
      services.groups.holes.add(holeOverlay);
      ready = true;
      redraw();
    });
    if (hooks.geometryChanged) hooks.geometryChanged.push(redraw);
    function dispose() {
      const i = hooks.geometryChanged?.indexOf(redraw);
      if (i >= 0) hooks.geometryChanged.splice(i, 1);
      clear(hardwareOverlay);
      clear(holeOverlay);
      hardwareOverlay.removeFromParent();
      holeOverlay.removeFromParent();
      hardwareMaterial.dispose();
      holeMaterial.dispose();
      button.remove();
    }
    return {
      name: 'panel_hardware',
      serialize: () => ({ active, selectedPanelId }),
      restore: s => {
        if (s.selectedPanelId != null) services.selectId(s.selectedPanelId);
        setActive(s.active);
      },
      setActive,
      redraw,
      dispose,
      get active() {
        return active;
      },
      get selectedPanelId() {
        return selectedPanelId;
      },
      get relatedHardwareIds() {
        return (relations.get(selectedPanelId) || []).map(item => item.id);
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else
    (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'panel_hardware', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

/* Adapter for precomputed milling meshes. No boolean engine in the browser. */
(function (root) {
  'use strict';
  function indexForScene(bundle, sourceHash) {
    if (bundle.schema !== 'bazis-milling-v1' || bundle.sha256 !== sourceHash)
      throw new Error('Фрезеровки относятся к другой версии модели');
    const map = new Map();
    for (const panel of bundle.panels) {
      if (map.has(panel.id)) throw new Error('Повтор ID панели');
      map.set(panel.id, panel);
    }
    return map;
  }
  function geometry(THREE, record) {
    const p = record?.positions,
      i = record?.indices;
    if (
      !Array.isArray(p) ||
      p.length < 9 ||
      p.length % 3 ||
      !p.every(Number.isFinite) ||
      !Array.isArray(i) ||
      !i.length ||
      i.length % 3 ||
      !i.every(n => Number.isInteger(n) && n >= 0 && n < p.length / 3)
    )
      throw new Error('Некорректная сетка фрезеровки');
    const indexed = new THREE.BufferGeometry();
    indexed.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
    indexed.setIndex(i);
    // Preserve hard stock edges. Same XY texture convention as the panel renderer.
    const uv = [];
