    linkGroup.name = 'Связи взрыв-схемы';
    const partDimensionGroup = new T.Group();
    partDimensionGroup.name = 'Габариты выбранной детали';
    const partDimensions = [];
    function init() {
      // окно — в общем слое под всей строкой (как «⋯» у сечения)
      disposeSettings = services.portalToolMenu?.(settings, { anchor: popup });
      ready = true;
      area.append(labelLayer, unitBar);
      scene.add(linkGroup, partDimensionGroup);
      scene.updateMatrixWorld(true);
      for (const [id, objects] of services.renderedById) {
        const roots = objects.filter(o =>
          ['panel', 'profile', 'hardware', 'import'].includes(o.userData.kind)
        );
        if (!roots.length) continue;
        const box = new T.Box3();
        for (const o of roots) box.expandByObject(o);
        if (box.isEmpty()) continue;
        items.set(id, {
          id,
          kind: roots[0].userData.kind,
          rec: roots[0].userData.record,
          roots: roots.map(object => ({ object, position: object.position.clone() })),
          center: box.getCenter(new T.Vector3()),
          offset: new T.Vector3(),
          unit: unitOf(id)
        });
      }
      const instanced = services.groups.holes.children.find(o => o.isInstancedMesh),
        rims = services.groups.holes.children.find(o => o.isLineSegments && o.userData.decorative);
      if (!services.holeMatrices) {
        services.holeMatrices = [];
        if (instanced)
          for (let i = 0; i < services.holeMeshes.length; i++) {
            const m = new T.Matrix4();
            instanced.getMatrixAt(i, m);
            services.holeMatrices.push(m);
          }
      }
      if (!services.holeRimPositions)
        services.holeRimPositions = new Float32Array(rims?.geometry.attributes.position.array || []);
      holeBases = services.holeMatrices.map(m => m.clone());
      rimBase = new Float32Array(services.holeRimPositions);
      for (const snap of services.snaps || [])
        snapBases.push({ snap, base: snap.v.clone(), id: snap.object.userData.record?.id });
      refresh();
    }
    function syncHoles() {
      const holes = services.holeMeshes || [],
        group = services.groups.holes,
        instanced = group.children.find(o => o.isInstancedMesh),
        rims = group.children.find(o => o.isLineSegments && o.userData.decorative),
        collapsed = new T.Matrix4().makeScale(0, 0, 0);
      for (let i = 0; i < holes.length; i++) {
        const offset = items.get(holes[i].userData.record.id)?.offset || zero,
          visible = holes[i].visible && holes[i].parent.visible,
          base = holeBases[i];
        if (base && instanced) {
          const m = base.clone();
          m.elements[12] += offset.x;
          m.elements[13] += offset.y;
          m.elements[14] += offset.z;
          services.holeMatrices[i].copy(m);
          instanced.setMatrixAt(i, visible ? m : collapsed);
        }
        if (rims && rimBase) {
          const chunk = rimBase.length / holes.length,
            start = i * chunk,
            end = start + chunk,
            array = rims.geometry.attributes.position.array;
          for (let n = start; n < end; n += 3) {
            services.holeRimPositions[n] = rimBase[n] + offset.x;
            services.holeRimPositions[n + 1] = rimBase[n + 1] + offset.y;
            services.holeRimPositions[n + 2] = rimBase[n + 2] + offset.z;
          }
          if (visible) array.set(services.holeRimPositions.subarray(start, end), start);
          else array.fill(0, start, end);
        }
      }
      if (instanced) instanced.instanceMatrix.needsUpdate = true;
      if (rims) {
        rims.geometry.attributes.position.needsUpdate = true;
        rims.geometry.computeBoundingSphere();
      }
    }
    function updateLinks() {
      while (linkGroup.children.length) {
        const o = linkGroup.children[0];
        linkGroup.remove(o);
        o.geometry.dispose();
        o.material.dispose();
      }
      if (!active || !exploded) return;
      const positions = [];
      for (const [id, ids] of byHardware) {
        const hardware = items.get(id);
        if (!hardware || !hardware.roots.some(o => services.visible(o.object))) continue;
        for (const pid of ids) {
          const panel = items.get(pid);
          if (!panel || !shown(panel)) continue;
          const link = relations.find(r => r.panel_id === pid)?.hardware.find(h => h.id === id),
            owner = data.hardware.find(h => h.id === id),
            hole = owner?.holes[link?.intersecting_holes[0]];
          const target = hole
            ? new T.Vector3(...hole.p)
                .applyQuaternion(new T.Quaternion(...owner.q))
                .add(new T.Vector3(...owner.p))
            : panel.center.clone();
          positions.push(
            ...hardware.center.clone().add(hardware.offset).toArray(),
            ...target.add(panel.offset).toArray()
          );
        }
      }
      if (positions.length) {
        const geometry = new T.BufferGeometry();
        geometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
        linkGroup.add(
          new T.LineSegments(
            geometry,
            new T.LineBasicMaterial({ color: 0xe5ac5f, transparent: true, opacity: 0.65 })
          )
        );
      }
    }
    function clearPartDimensions() {
      while (partDimensions.length) {
        const rec = partDimensions.pop(),
          index = services.dimensionVisuals.indexOf(rec);
        if (index >= 0) services.dimensionVisuals.splice(index, 1);
        rec.group.removeFromParent();
        rec.group.traverse(o => {
          o.geometry?.dispose();
          o.material?.dispose();
        });
        rec.label.remove();
      }
    }
    function refreshPartDimensions() {
      clearPartDimensions();
      partDimensionsButton.setAttribute('aria-pressed', String(partDimensionsEnabled));
      partDimensionGroup.visible = active && partDimensionsEnabled;
      const panel = panels.get(selectedId),
        item = items.get(selectedId);
      if (!partDimensionGroup.visible || !panel || !item) return;
      const points = (panel.loops || []).flat();
      if (!points.length) return;
      const xs = points.map(p => p[0]),
        ys = points.map(p => p[1]),
        minX = Math.min(...xs),
        maxX = Math.max(...xs),
        minY = Math.min(...ys),
        maxY = Math.max(...ys),
        dx = maxX - minX,
        dy = maxY - minY;
      if (!(dx > 0 && dy > 0)) return;
      const margin = Math.max(20, Math.min(dx, dy) * 0.06),
        z = Math.max(0, Number(panel.thickness) || 0),
        q = new T.Quaternion(...panel.q),
        p = new T.Vector3(...panel.p);
      const worldPoint = v => new T.Vector3(...v).applyQuaternion(q).add(p).add(item.offset);
      for (const [a, b] of [
        [
          [minX, minY - margin, z],
          [maxX, minY - margin, z]
        ],
        [
          [minX - margin, minY, z],
          [minX - margin, maxY, z]
        ]
      ]) {
        const rec = services.createDimensionVisual(worldPoint(a), worldPoint(b));
        rec.assemblerPartSize = true;
        rec.label.dataset.assemblerPartSize = 'true';
        partDimensionGroup.add(rec.group);
        partDimensions.push(rec);
      }
    }
    function refresh() {
      if (!active) settings.open = false;
      tools.setOpen(active);
      unitBar.hidden = !active;
      explodeInput.setAttribute('aria-pressed', String(exploded));
      partDimensionsButton.setAttribute('aria-pressed', String(partDimensionsEnabled));
      slider.value = String(separation);
      amount.textContent = separation + ' мм';
      for (const [id, b] of unitButtons) b.setAttribute('aria-pressed', String(id === unitId));
      preview.disabled = !panels.has(selectedId);
      labelLayer.style.display = active ? 'block' : 'none';
      partDimensionGroup.visible = active && partDimensionsEnabled;
      if (!ready) return;
      if (services.setVisibilityFilter) {
        let keep = null;
        if (active && unitId != null) {
          keep = new Set([...records.keys()].filter(id => belongs(id, unitId)));
          for (const [id, panels] of byHardware)
            if (panels.some(pid => keep.has(pid)))
              for (const child of services.descendants(id)) keep.add(child);
        }
        services.setVisibilityFilter('assembler', keep ? id => keep.has(id) : null);
        if (selectedId != null && !services.objectVisible(selectedId)) services.select(null);
      }
      const boxes = new Map();
      for (const i of items.values())
        if (i.kind !== 'hardware' && belongs(i.id, unitId)) {
          const key = unitId ?? i.unit;
          if (!boxes.has(key)) boxes.set(key, new T.Box3());
          boxes.get(key).expandByPoint(i.center);
        }
      for (const i of items.values()) {
        i.offset.set(0, 0, 0);
        if (active && exploded && i.kind !== 'hardware' && belongs(i.id, unitId)) {
          const pivot = boxes.get(unitId ?? i.unit)?.getCenter(new T.Vector3()) || i.center;
          i.offset.copy(i.center).sub(pivot);
          if (i.offset.lengthSq() < 1) i.offset.set(0, 1, 0);
          i.offset.normalize().multiplyScalar(separation);
        }
      }
      if (active && exploded)
        for (const i of items.values())
          if (i.kind === 'hardware') {
            const targets = (byHardware.get(i.id) || [])
              .map(id => items.get(id))
              .filter(p => p && belongs(p.id, unitId));
            if (targets.length) {
              for (const p of targets) i.offset.add(p.offset);
              i.offset.multiplyScalar(1 / targets.length);
              const d = i.center.clone().sub(targets[0].center);
              if (d.lengthSq() < 1) d.set(0, 0, 1);
              i.offset.addScaledVector(d.normalize(), separation * 0.35);
            }
          }
      if (active && exploded)
        for (const u of childUnits()) {
          const parts = [...items.values()].filter(i => belongs(i.id, u.id)),
            box = new T.Box3();
          for (const i of parts) box.expandByPoint(i.center);
          if (box.isEmpty()) continue;
          const pivot = boxes.get(unitId)?.getCenter(new T.Vector3()) || zero,
            offset = box.getCenter(new T.Vector3()).sub(pivot);
          if (offset.lengthSq() < 1) offset.set(0, 1, 0);
          offset.normalize().multiplyScalar(separation);
          for (const i of parts) i.offset.copy(offset);
        }
      for (const i of items.values())
        for (const r of i.roots) {
          const localOffset = i.offset.clone();
          if (r.object.parent) {
            const inverse = r.object.parent.matrixWorld.clone().invert();
            localOffset.applyMatrix4(inverse).sub(zero.clone().applyMatrix4(inverse));
          }
          r.object.position.copy(r.position).add(localOffset);
        }
      for (const { snap, base, id } of snapBases) snap.v.copy(base).add(items.get(id)?.offset || zero);
      scene.updateMatrixWorld(true);
      syncHoles();
      updateLinks();
      refreshPartDimensions();
      services.updateHighlight();
      for (const fn of hooks.geometryChanged || []) fn();
      for (const fn of hooks.assemblerChanged) fn({ active, exploded, separation, unitId });
      lastVisibility = '';
      labelElapsed = 1;
    }
    function frame(delta = 0.016) {
      if (!ready || !active) return;
      const signature = [...items.values()]
        .map(i => i.roots.map(o => (services.visible(o.object) ? '1' : '0')).join(''))
        .join('');
      if (signature !== lastVisibility) {
        syncHoles();
        updateLinks();
        lastVisibility = signature;
        labelElapsed = 1;
      }
      labelElapsed += delta;
      if (labelElapsed >= 0.15) {
        labelElapsed = 0;
        updateLabels();
      }
    }
    function setActive(value) {
      active = !!value;
      refresh();
    }
    function open() {
      setActive(true);
    }
    function setExploded(value) {
      exploded = !!value;
      if (exploded) {
        active = true;
        if (unitId == null && units.length)
          unitId =
            unitOf(selectedId) ??
            units
              .slice()
              .sort(
                (a, b) =>
                  data.panels.filter(p => belongs(p.id, b.id)).length -
                  data.panels.filter(p => belongs(p.id, a.id)).length
              )[0].id;
      }
      refresh();
    }
    function setSeparation(value) {
      if (!Number.isFinite(value)) throw new Error('Некорректный разнос');
      separation = Math.max(0, Math.min(1000, value));
      refresh();
    }
    function setPartDimensions(value) {
      partDimensionsEnabled = !!value;
      refreshPartDimensions();
    }
    function select(id) {
      if (id == null) services.select(null);
      else services.selectId(id);
    }
    // Меняет только переданные поля. name: true/false — выбор пользователя,
    // null — вернуть умолчание устройства.
    function setLabelOptions(options) {
      if ('position' in options) labelPosition = options.position !== false;
      if ('name' in options) labelNameOverride = typeof options.name === 'boolean' ? options.name : null;
      labelName = labelNameOverride ?? defaultLabelName();
      if (Number.isFinite(options.fontSize))
        labelFontSize = Math.max(10, Math.min(28, Math.round(options.fontSize)));
      positionInput.checked = labelPosition;
      nameInput.checked = labelName;
      fontInput.value = String(labelFontSize);
      fontValue.textContent = labelFontSize + ' px';
      labelElapsed = 1;
      if (ready && active) updateLabels();
    }
    function calloutText(rec, selected = false) {
      const parts = [];
      if (labelPosition)
        parts.push(
          String(
            rec.artpos ||
              (rec.assembly_unit
                ? String(rec.name || '')
                    .trim()
                    .split(/\s+/)[0]
                : '') ||
              t('Без позиции')
          )
        );
      if (labelName || selected) parts.push(rec.name || t('Без названия'));
      return parts.join(' · ');
    }
    function selectionChanged(object) {
      selectedId = object?.userData.record.id ?? null;
      preview.disabled = !panels.has(selectedId);
      refreshPartDimensions();
      labelElapsed = 1;
      if (ready && active) updateLabels();
    }
    function openDrawing(id = selectedId) {
      const panel = panels.get(id);
      return panel ? root.BazisAssemblerDrawing.open(context, panel) : null;
    }
    function anchor(i) {
      const center = i.center.clone().add(i.offset),
        ray = new T.Raycaster(camera.position, center.clone().sub(camera.position).normalize());
      const hit = ray
        .intersectObjects(
          i.roots.map(r => r.object),
          true
        )
        .find(h => h.object.isMesh && services.pointVisible(h.point));
      return hit?.point || center;
    }
    function updateLabels() {
      for (const l of labels.values()) l.style.display = 'none';
      const wanted = [];
      // Выноски на каждую деталь — и во взрыв-схеме, и когда просто выбрана сборочная
      // единица при включённом режиме сборщика (не только при разносе).
      if (exploded || (active && unitId != null)) {
        const children = childUnits();
        for (const i of items.values())
          if (shown(i) && listable(i) && (i.id === selectedId || !children.some(u => belongs(i.id, u.id))))
            wanted.push([i.id, anchor(i), calloutText(i.rec, i.id === selectedId)]);
        for (const u of children) {
          const parts = [...items.values()].filter(i => shown(i) && listable(i) && belongs(i.id, u.id));
          if (parts.length) {
            const box = new T.Box3();
            for (const i of parts) box.expandByPoint(i.center.clone().add(i.offset));
            const center = box.getCenter(new T.Vector3());
            parts.sort(
              (a, b) =>
                a.center.clone().add(a.offset).distanceToSquared(center) -
                b.center.clone().add(b.offset).distanceToSquared(center)
            );
            wanted.push(['unit' + u.id, anchor(parts[0]), calloutText(u, u.id === selectedId)]);
          }
        }
      } else if (selectedId != null) {
        const i = items.get(selectedId);
        if (i && i.roots.some(r => services.visible(r.object)) && ['panel', 'profile'].includes(i.kind))
          wanted.push([i.id, anchor(i), calloutText(i.rec, true)]);
      } else {
        for (const u of units) {
          if (unitId != null && u.id !== unitId) continue;
          if (unitId == null && units.some(parent => parent.id !== u.id && belongs(u.id, parent.id)))
            continue;
          const box = new T.Box3();
          for (const i of items.values())
            if (shown(i) && ['panel', 'profile'].includes(i.kind) && belongs(i.id, u.id))
              box.expandByPoint(i.center);
          if (!box.isEmpty())
            wanted.push(['unit' + u.id, box.getCenter(new T.Vector3()), calloutText(u, u.id === selectedId)]);
        }
      }
      const width = area.clientWidth,
        height = area.clientHeight,
        labelWidth = Math.min(190, width * 0.27);
      leaderLayer.replaceChildren();
      // общий помощник: создать/переиспользовать подпись, выноску деталь→точку и маркер
      const anchorMarker = (id, ax, ay) => {
        const m = doc.createElementNS('http://www.w3.org/2000/svg', 'circle');
        for (const [k, v] of Object.entries({
          cx: ax,
          cy: ay,
          r: 5,
          fill: '#ffcc70',
          stroke: '#17232d',
          'stroke-width': 2
        }))
          m.setAttribute(k, v);
        m.setAttribute('data-anchor', String(id));
        leaderLayer.append(m);
      };
      const leader = (x1, y1, x2, y2) => {
        const l = doc.createElementNS('http://www.w3.org/2000/svg', 'line');
        for (const [k, v] of Object.entries({
          x1,
          y1,
          x2,
          y2,
          stroke: '#9db9c5',
          'stroke-width': 1,
          'stroke-opacity': 0.7
        }))
          l.setAttribute(k, v);
        leaderLayer.append(l);
      };
      const boxFor = id => {
        let l = labels.get(id);
        if (!l) {
          l = doc.createElement('div');
          l.className = 'assemblerCallout';
          l.translate = false; // позиция и название — данные (заглушки — через t)
          l.dataset.part = String(id);
          l.setAttribute('role', 'button');
          l.tabIndex = 0;
          l.onkeydown = e => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              l.click();
            }
          };
          l.onclick = (rid => () => {
            if (typeof rid === 'number') select(rid);
            else if (String(rid).startsWith('unit')) {
              unitId = Number(String(rid).slice(4));
              refresh();
            }
          })(id);
          labelLayer.append(l);
          labels.set(id, l);
        }
        return l;
      };
      const points = [];
      for (const [id, point, text] of wanted) {
        if (!text) continue;
        const p = point.project(camera);
        if (p.z < -1 || p.z > 1 || Math.abs(p.x) > 1 || Math.abs(p.y) > 1) continue;
        const selected = id === selectedId || id === 'unit' + selectedId,
          l = boxFor(id);
        l.textContent = text;
        // шрифт из настроек — для сносок с наименованием; одна позиция остаётся мелкой
        l.style.fontSize = (labelName || selected ? labelFontSize : 11) + 'px';
        l.style.lineHeight = '1.3';
        l.setAttribute('aria-pressed', String(selected));
        l.style.display = 'block';
        l.style.width = 'max-content';
        l.style.maxWidth = (selected ? Math.min(240, width * 0.65) : labelWidth) + 'px';
        l.style.maxHeight = 'none';
        const w = Math.ceil(l.getBoundingClientRect().width),
          h = Math.ceil(l.getBoundingClientRect().height);
        l.style.display = 'none';
        points.push({ id, text, selected, w, h, x: ((p.x + 1) * width) / 2, y: ((1 - p.y) * height) / 2 });
      }

      const obstacles = [];
      for (const i of items.values()) {
        if (i.kind === 'hardware' || !i.roots.some(r => services.visible(r.object))) continue;
        const box = new T.Box3();
        for (const r of i.roots) if (services.visible(r.object)) box.expandByObject(r.object);
        if (box.isEmpty()) continue;
        const ps = [];
        for (const x of [box.min.x, box.max.x])
          for (const y of [box.min.y, box.max.y])
            for (const z of [box.min.z, box.max.z]) {
              const p = new T.Vector3(x, y, z).project(camera);
              if (p.z >= -1 && p.z <= 1) ps.push({ x: ((p.x + 1) * width) / 2, y: ((1 - p.y) * height) / 2 });
            }
        if (ps.length) {
          const x = Math.min(...ps.map(p => p.x)),
            y = Math.min(...ps.map(p => p.y));
          obstacles.push({
            x,
            y,
            w: Math.max(...ps.map(p => p.x)) - x,
            h: Math.max(...ps.map(p => p.y)) - y
          });
        }
      }
      obstacles.push({ x: width - 112, y: 0, w: 112, h: 110, ui: true });
      if (!unitBar.hidden) {
        const r = unitBar.getBoundingClientRect(),
          a = area.getBoundingClientRect();
        obstacles.push({ x: r.left - a.left, y: r.top - a.top, w: r.width, h: r.height, ui: true });
      }
      for (const el of doc.querySelectorAll('#hardwareCatalog,#hardwareCatalogToggle,.footer')) {
        if (el.hidden) continue;
        const r = el.getBoundingClientRect(),
          a = area.getBoundingClientRect();
        if (r.width && r.height)
          obstacles.push({ x: r.left - a.left, y: r.top - a.top, w: r.width, h: r.height, ui: true });
      }
      for (const r of root.BazisAssemblerLabels.layout(points, obstacles, width, height, labelWidth, 36)) {
        const l = boxFor(r.point.id);
        l.textContent = r.point.text;
        l.title = r.point.text;
        l.style.display = 'block';
        l.style.width = r.w + 'px';
        l.style.maxHeight = r.h + 'px';
        l.style.left = r.x + 'px';
        l.style.top = r.y + 'px';
        leader(r.point.x, r.point.y, r.target.x, r.target.y);
        anchorMarker(r.point.id, r.point.x, r.point.y);
      }
    }

    hooks.ready.push(init);
    hooks.frame.push(frame);
    hooks.selectionChanged.push(selectionChanged);
    refresh();
    return {
      name: 'assembler',
      open,
      setActive,
      select,
      setExploded,
      setSeparation,
      setPartDimensions,
      setLabelOptions,
      openDrawing,
      get state() {
        return {
          active,
          exploded,
          separation,
          unitId,
          selectedId,
          partDimensionsEnabled,
          labelPosition,
          labelName,
          labelFontSize,
          partDimensions: partDimensions.length,
          parts: items.size,
          links: linkGroup.children[0]?.geometry.attributes.position.count / 2 || 0
        };
      },
      serialize: () => ({
        active,
        exploded,
        separation,
        unitId,
        partDimensionsEnabled,
        labelPosition,
        labelName: labelNameOverride,
        labelFontSize
      }),
      restore: s => {
        setLabelOptions({
          position: s.labelPosition !== false,
          name: typeof s.labelName === 'boolean' ? s.labelName : null,
          fontSize: Number(s.labelFontSize)
        });
        active = !!s.active;
        exploded = !!s.exploded;
        partDimensionsEnabled = !!s.partDimensionsEnabled;
        separation = Math.max(0, Math.min(1000, Number(s.separation) || 0));
        unitId = units.some(u => u.id === s.unitId) ? s.unitId : null;
        refresh();
      },
      dispose() {
        if (disposed) return;
        active = false;
        refresh();
        clearPartDimensions();
        disposed = true;
        for (const [list, fn] of [
