  pointer-events: none;
  overflow: hidden;
}
#assemblerLeaders {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

scripts:
(function (root) {
  'use strict';
  function install(context, bundle) {
    const { THREE: T, data, hooks, services, document: doc, canvas } = context;
    if (bundle?.schema !== 1 || !Array.isArray(bundle.cards))
      throw new Error('Несовместимый каталог фурнитуры');
    hooks.assemblerChanged = hooks.assemblerChanged || [];
    const records = new Map(data.objects.map(r => [r.id, r])),
      cards = bundle.cards,
      area = canvas.parentElement || doc.getElementById('viewport'),
      byHardware = new Map();
    for (const panel of data.features?.panel_hardware?.panels || [])
      for (const hardware of panel.hardware || []) {
        if (!byHardware.has(hardware.id)) byHardware.set(hardware.id, []);
        byHardware.get(hardware.id).push(panel.panel_id);
      }
    const belongs = (id, parent) => {
      if (parent == null) return true;
      let r = records.get(id),
        seen = new Set();
      while (r && !seen.has(r.id)) {
        if (r.id === parent) return true;
        seen.add(r.id);
        r = records.get(r.parent_id);
      }
      return false;
    };
    const descendants = ids => new Set(ids.flatMap(id => services.descendants(id)));
    const includedRoot = id =>
      unitId == null ||
      belongs(id, unitId) ||
      services
        .descendants(id)
        .some(child => (byHardware.get(child) || []).some(panel => belongs(panel, unitId)));
    const overlay = new T.Group();
    overlay.name = 'Подсветка артикула';
    const meshMaterial = new T.MeshBasicMaterial({
      color: 0x27e6df,
      transparent: true,
      opacity: 0.88,
      depthTest: false,
      depthWrite: false
    });
    const holeMaterial = new T.MeshBasicMaterial({
      color: 0xffb454,
      transparent: true,
      opacity: 0.94,
      depthTest: false,
      depthWrite: false
    });
    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const panel = doc.getElementById('hardwareCatalog');
    const rail = doc.getElementById('hardwareCatalogRail');
    const title = doc.getElementById('hardwareCatalogTitle'),
      hint = doc.getElementById('hardwareCatalogHint');
    const toggle = doc.getElementById('hardwareCatalogToggle');
    toggle.onclick = () => setExpanded(!expanded);
    area.append(panel, toggle);
    sceneAdd();
    const buttons = new Map();
    let active = true,
      expanded = false,
      unitId = null,
      selected = null,
      ready = false;
    function sceneAdd() {
      context.scene.add(overlay);
    }
    function clear() {
      while (overlay.children.length) overlay.remove(overlay.children[0]);
    }
    function clone(source, material) {
      source.updateWorldMatrix(true, false);
      const copy = new T.Mesh(source.geometry, material);
      copy.matrix.copy(source.matrixWorld);
      copy.matrixAutoUpdate = false;
      copy.renderOrder = 19;
      overlay.add(copy);
    }
    function idsFor(card) {
      return descendants(card.object_ids.filter(includedRoot));
    }
    function redraw() {
      clear();
      if (!selected) return;
      const card = cards.find(c => c.id === selected);
      if (!card) return;
      const ids = idsFor(card),
        meshed = new Set();
      for (const id of ids)
        for (const object of services.renderedById.get(id) || [])
          object.traverse(child => {
            if (child.isMesh) {
              clone(child, meshMaterial);
              meshed.add(id);
            }
          });
      for (const hole of services.holeMeshes || [])
        if (ids.has(hole.userData.record.id) && !meshed.has(hole.userData.record.id))
          clone(hole, holeMaterial);
    }
    function setSelected(id) {
      selected = selected === id ? null : id;
      for (const [key, button] of buttons) button.setAttribute('aria-pressed', String(key === selected));
      redraw();
    }
    function setExpanded(value) {
      expanded = !!value;
      if (!expanded) setSelected(null);
      render();
    }
    function render() {
      rail.replaceChildren();
      buttons.clear();
      let count = 0;
      for (const card of cards) {
        const quantity = card.object_ids.filter(includedRoot).length;
        if (!quantity) continue;
        count++;
        const button = doc.createElement('button');
        button.type = 'button';
        button.className = 'hardwareCard';
        button.setAttribute('aria-pressed', String(card.id === selected));
        button.title = card.name;
        button.setAttribute('data-i18n-skip', '');
        button.onclick = () => setSelected(card.id);
        const name = doc.createElement('span');
        name.className = 'hardwareCardName';
        name.translate = false;
        name.textContent = card.name;
        let image;
        if (card.image) {
          image = doc.createElement('img');
          image.className = 'hardwareCardImage';
          image.src = card.image;
          image.alt = '';
          image.loading = 'lazy';
        } else {
          image = doc.createElement('span');
          image.className = 'hardwareCardImage hardwareCardPlaceholder';
          image.textContent = '◇';
        }
        const meta = doc.createElement('span');
        meta.className = 'hardwareCardMeta';
        const display = card.manufacturer_article || card.article || 'без артикула';
        meta.textContent =
          'арт. ' + display + (card.article && display !== card.article ? ' · код ' + card.article : '');
        const qty = doc.createElement('strong');
        qty.textContent = 'Количество: ' + quantity;
        meta.append(qty);
        button.append(name, image, meta);
        rail.append(button);
        buttons.set(card.id, button);
      }
      title.textContent = 'Фурнитура · ' + count;
      hint.hidden = count === 0;
      toggle.hidden = !active || count === 0;
      toggle.setAttribute('aria-expanded', String(expanded));
      toggle.textContent = `Фурнитура · ${count} ${expanded ? '▼' : '▲'}`;
      panel.hidden = !active || !expanded || count === 0;
      if (selected && !buttons.has(selected)) selected = null;
      redraw();
      publishBar();
    }
    // Каталог доступен и вне сборщика: там unitId пуст и includedRoot пропускает
    // всю фурнитуру модели. Сборщик лишь сужает список до выбранной сборки.
    // Публикуем занятую снизу высоту как --hardwareBarH на #viewport: над ней
    // material_labels ставит свой столбик выносок, чтобы ничего не перекрывалось.
    function publishBar() {
      try {
        const host = doc.getElementById('viewport');
        if (!host) return;
        let h = 8;
        if (!toggle.hidden) {
          const t = toggle.getBoundingClientRect(),
            v = host.getBoundingClientRect();
          if (t.height) h = Math.round(v.bottom - t.top) + 6;
        }
        host.style.setProperty('--hardwareBarH', h + 'px');
        doc.documentElement.style.setProperty('--hardwareBarH', h + 'px');
      } catch (e) {}
    }
    const resize = () => publishBar();
    (context.window || root).addEventListener('resize', resize);
    function stateChanged(state) {
      unitId = state.active ? (state.unitId ?? null) : null;
      render();
    }
    hooks.assemblerChanged.push(stateChanged);
    if (hooks.geometryChanged) hooks.geometryChanged.push(redraw);
    hooks.ready.push(() => {
      ready = true;
      render();
    });
    function dispose() {
      (context.window || root).removeEventListener('resize', resize);
      doc.documentElement.style.removeProperty('--hardwareBarH');
      area.style.removeProperty('--hardwareBarH');
      clear();
      overlay.removeFromParent();
      meshMaterial.dispose();
      holeMaterial.dispose();
      panel.remove();
      toggle.remove();
      doc.querySelector?.('style[data-feature="hardware_catalog"]')?.remove();
      for (const [list, fn] of [
        [hooks.assemblerChanged, stateChanged],
        [hooks.geometryChanged, redraw]
      ]) {
        const i = list?.indexOf(fn);
        if (i >= 0) list.splice(i, 1);
      }
    }
    return {
      name: 'hardware_catalog',
      setSelected,
      setExpanded,
      redraw,
      serialize: () => ({ expanded }),
      restore: state => setExpanded(!!state?.expanded),
      dispose,
      get state() {
        return { active, expanded, unitId, selected, visibleCards: buttons.size, ready };
      }
    };
  }
  const api = { install };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else
    (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'hardware_catalog', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

