  object-fit: contain;
  background: #edf0f1;
  border-radius: 4px;
}
.hardwareCardPlaceholder {
  display: grid;
  place-items: center;
  color: #617985;
  background: var(--divider);
  font-size: 24px;
}
.hardwareCardMeta {
  font-size: 10px;
  line-height: 13px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.hardwareCardMeta strong {
  display: block;
  font-size: 11px;
  color: var(--text);
}
@media (max-width: 760px) {
  .hardwareCatalog {
    height: 153px;
    padding: 5px;
  }
  .hardwareCatalogToggle[aria-expanded='true'] {
    bottom: 176px;
  }
  .hardwareCatalogHead {
    height: 20px;
  }
  .hardwareCard {
    width: 112px;
    height: 114px;
    flex-basis: 112px;
    grid-template-rows: 26px 58px 23px;
    padding: 3px;
  }
  .hardwareCardImage {
    height: 58px;
  }
  .hardwareCardName {
    font-size: 10px;
    line-height: 12px;
  }
  .hardwareCardMeta {
    font-size: 9px;
    line-height: 11px;
  }
  .hardwareCardMeta strong {
    font-size: 10px;
  }
}
.footer {
  bottom: var(--hardwareBarH, 10px);
}

scripts:
/**
 * БАЗИС 3D — проверка регрессии сгенерированного документа.
 *
 * Модуль по общему контракту: adapter.js создаёт свою разметку в extrasMount,
 * вешает обработчик и выставляет basisCheck() наружу. В шаблоне остаётся только
 * точка монтирования.
 *
 *   basisCheck()                              // отчёт в консоль
 *   basisCheck({ maxDepthRatio: 5000 })       // свои пороги
 *   basisCheck({ verbose: false })            // только сводка
 *   __bvcLast                                 // сырые находки после прогона
 *
 * Возвращает { pass, warn, fail, verdict }. Пороги приходят из integration.py,
 * аргумент вызова их перекрывает.
 *
 * Сцену берём из window.__viewer: install() отрабатывает ДО того, как сцена
 * собрана, поэтому renderer и scene ищем в момент запуска, а не установки.
 * Запасной путь — перехват Object3D.prototype.onBeforeRender — оставлен для
 * вставки в консоль чужой сборки, где __viewer нет. Он хрупкий: во вкладке не
 * на переднем плане requestAnimationFrame придушен, перерисовки нет.
 *
 * CFG.structuralTypes — коды record.type «несущих» деталей (панели и профили).
 * По ним отделяются реальные проблемы модели от фурнитуры и импорта, где
 * произвольные углы и внутренние копланары — норма.
 */
(function (root) {
  'use strict';

  let defaults = {};

  async function basisCheck(userCfg) {
    'use strict';

    const CFG = Object.assign(
      {
        maxDepthRatio: 10000, // потолок far/near
        depthSafety: 10, // во сколько раз Δz должна быть меньше тончайшей несущей детали
        maxInflate: 0.25, // мм, потолок раздутия геометрии
        maxInflateSteps: 12, // ступеней в лестнице inflate
        alignEps: 0.01, // ° — меньше считаем строго по осям
        alignSuspectMax: 5, // ° — больше считаем намеренным наклоном
        alignClusterMin: 2, // объектов в кластере углов, чтобы поднять флаг
        perfFrames: 30,
        thinMm: 6, // «тонкая» деталь — кандидат в копланары
        triBudget: 3e6,
        structuralTypes: [4002, 2001, 2002, 2004], // 2002 — тоже профиль, встречается в моделях
        skipPerf: false, // замер кадра врёт под софтверным GL и виртуальным временем
        verbose: true
      },
      defaults,
      userCfg || {}
    );

    const T = window.THREE;
    if (!T) throw new Error('THREE не найден в window');

    // ── перехват сцены ────────────────────────────────────────────────────────
    const V = window.__viewer;
    if (V && V.renderer && V.scene && V.camera) {
      window.__bvcCtx = { r: V.renderer, s: V.scene, c: V.camera };
    } else {
      const O = T.Object3D.prototype;
      if (!O.__bvc) {
        const orig = O.onBeforeRender;
        O.onBeforeRender = function (r, s, c) {
          if (s && s.isScene) window.__bvcCtx = { r, s, c };
          return orig.apply(this, arguments);
        };
        O.__bvc = 1;
      }
      window.dispatchEvent(new Event('resize'));
      for (let i = 0; i < 30 && !window.__bvcCtx; i++) await new Promise(r => setTimeout(r, 100));
      if (!window.__bvcCtx)
        throw new Error('Рендер не перехвачен за 3 с. Крутни модель мышью и запусти ещё раз.');
    }
    const { r: R, s: S, c: C } = window.__bvcCtx;

    const F = [];
    const add = (lvl, id, msg, data) => F.push({ lvl, id, msg, data });

    const meshes = [],
      lines = [];
    S.traverse(o => {
      if (o.isMesh) meshes.push(o);
      else if (o.isLine || o.isLineSegments) lines.push(o);
    });
    const rec = m => (m.userData && m.userData.record) || null;
    // Меш без record — служебный (общий InstancedMesh отверстий, хелперы). Считать
    // его несущим нельзя: его габарит попадал в «тончайшую деталь» и молча портил
    // порог depth.resolution.
    const isStruct = m => {
      const r = rec(m);
      return r ? CFG.structuralTypes.indexOf(r.type) >= 0 : false;
    };
    const structural = meshes.filter(isStruct);
    const localMin = m => {
      m.geometry.computeBoundingBox();
      const s = m.geometry.boundingBox.getSize(new T.Vector3());
      return Math.min(s.x, s.y, s.z);
    };

    const sceneBox = new T.Box3();
    S.children.forEach(c => {
      if (c.type === 'Group') sceneBox.expandByObject(c);
    });
    const sz = sceneBox.getSize(new T.Vector3());
    const span = Math.max(sz.x, sz.y, sz.z);

    const gl = R.getContext();
    const bits = gl.getParameter(gl.DEPTH_BITS) || 24;
    const N = Math.pow(2, bits) - 1;
    const logDepth = !!R.capabilities.logarithmicDepthBuffer;
    // разрешение буфера глубины на дистанции w (мм)
    const dz = w =>
      logDepth
        ? ((1 + w) * Math.LN2 * Math.log2(C.far + 1)) / N
        : (w * w * (C.far - C.near)) / (C.near * C.far * N);

    // ── 1. Камера и буфер глубины ─────────────────────────────────────────────
    const sThin = structural
      .map(localMin)
      .filter(v => v > 1e-3)
      .sort((a, b) => a - b);
    const allThin = meshes
      .map(localMin)
      .filter(v => v > 1e-3)
      .sort((a, b) => a - b);
    const thinnest = sThin[0] || 0;
    const dFar = span * 1.6;
    const ratio = C.far / C.near;

    add(
      ratio <= CFG.maxDepthRatio ? 'PASS' : 'FAIL',
      'depth.ratio',
      'far/near = ' +
        ratio.toFixed(0) +
        ' (порог ' +
        CFG.maxDepthRatio +
        '); near ' +
        C.near.toFixed(3) +
        ', far ' +
        C.far.toFixed(0)
    );

    add(
      logDepth ? 'PASS' : 'INFO',
      'depth.log',
      'logarithmicDepthBuffer: ' + logDepth + ', depth bits: ' + bits
    );

    const resFar = dz(dFar),
      need = thinnest / CFG.depthSafety;
    add(
      resFar <= need ? 'PASS' : 'FAIL',
      'depth.resolution',
      'Δz на дистанции обзора (' +
        dFar.toFixed(0) +
        ' мм) = ' +
        resFar.toFixed(4) +
        ' мм; тончайшая несущая деталь ' +
        thinnest.toFixed(2) +
        ' мм → нужно ≤ ' +
        need.toFixed(4) +
        ' мм',
      {
        dzБлизко: +dz(span * 0.6).toFixed(5),
        dzДалеко: +resFar.toFixed(5),
        тончайшаяНесущая: +thinnest.toFixed(3),
        тончайшаяВообще: +(allThin[0] || 0).toFixed(3)
      }
    );

    add(
      C.far <= span * 20 ? 'PASS' : 'WARN',
      'depth.farVsScene',
      'far = ' +
        C.far.toFixed(0) +
        ' при габарите сцены ' +
        span.toFixed(0) +
        ' (' +
        (C.far / span).toFixed(1) +
        '×)'
    );

    add(
      C.near <= Math.max(thinnest * 20, 50) ? 'PASS' : 'WARN',
      'depth.nearVsPart',
      'near = ' + C.near.toFixed(2) + ' мм — ближе этого к детали не подъехать'
    );

    // ── 2. Материалы ──────────────────────────────────────────────────────────
    const mats = new Map();
    meshes.forEach(m => [m.material].flat().forEach(x => mats.set(x.uuid, x)));

    const po = [...mats.values()].filter(x => x.polygonOffset);
    const poSlope = po.filter(x => x.polygonOffsetFactor !== 0);
    add(
      poSlope.length === 0 ? 'PASS' : 'WARN',
      'mat.polygonOffset',
      po.length === 0
        ? 'polygonOffset не используется'
        : 'polygonOffset на ' +
            po.length +
            ' материалах, из них factor≠0: ' +
            poSlope.length +
            ' — смещение зависит от угла грани к камере, поэтому мерцает при вращении'
    );

    const badT = [...mats.values()].filter(x => x.transparent && x.depthWrite);
    const lineMats = [...new Set(lines.map(o => o.material))];
    const badTL = lineMats.filter(x => x.transparent && x.depthWrite);
    add(
      badT.length + badTL.length === 0 ? 'PASS' : 'WARN',
      'mat.transparentDepthWrite',
      'transparent + depthWrite одновременно: ' +
        badT.length +
        ' мат. мешей, ' +
        badTL.length +
        ' мат. линий (из ' +
        lineMats.length +
        ') — порядок отрисовки зависит от ракурса'
    );

    add(
      mats.size <= Math.max(64, meshes.length / 20) ? 'PASS' : 'WARN',
      'mat.sharing',
      mats.size + ' уникальных инстансов материала на ' + meshes.length + ' мешей'
    );

    // ── 3. Целостность геометрии ──────────────────────────────────────────────
    let tris = 0,
      zeroArea = 0,
      nanPos = 0,
      noNormal = 0,
      badNormal = 0,
      budget = CFG.triBudget;
    const vA = new T.Vector3(),
      vB = new T.Vector3(),
      vC = new T.Vector3();
    const e1 = new T.Vector3(),
      e2 = new T.Vector3(),
      crs = new T.Vector3();
    for (const m of meshes) {
      const g = m.geometry,
        p = g.attributes.position,
        ix = g.index;
      if (!p) continue;
      // Нормали нужны только освещаемым материалам. Неосвещаемые (MeshBasicMaterial:
      // грани кромок режима «Кромки», подсветки, накладки) их не читают — без
      // нормалей они рисуются верно, и считать их ошибкой нельзя.
      const lit = [].concat(m.material || []).some(mat => mat && !mat.isMeshBasicMaterial);
      if (!g.attributes.normal) {
        if (lit) noNormal++;
      } else {
        const a = g.attributes.normal.array;
        for (let i = 0; i < a.length; i += 3) {
          const L = Math.hypot(a[i], a[i + 1], a[i + 2]);
          if (!isFinite(L) || L < 1e-6) {
            badNormal++;
            break;
          }
        }
      }
      const n = ix ? ix.count : p.count;
      if (budget <= 0) continue;
      budget -= n / 3;
      for (let i = 0; i + 2 < n; i += 3) {
        const a = ix ? ix.getX(i) : i,
          b = ix ? ix.getX(i + 1) : i + 1,
          c = ix ? ix.getX(i + 2) : i + 2;
        vA.fromBufferAttribute(p, a);
        vB.fromBufferAttribute(p, b);
        vC.fromBufferAttribute(p, c);
        e1.subVectors(vB, vA);
        e2.subVectors(vC, vA);
        const area = crs.crossVectors(e1, e2).length() * 0.5;
        tris++;
        if (!isFinite(area)) nanPos++;
        else if (area < 1e-6) zeroArea++;
      }
    }
    add(
      zeroArea === 0 && nanPos === 0 ? 'PASS' : 'FAIL',
      'geo.degenerate',
      'треугольников нулевой площади: ' + zeroArea + ', NaN/Inf: ' + nanPos + ' (проверено ' + tris + ')'
    );
    add(
      noNormal === 0 && badNormal === 0 ? 'PASS' : 'FAIL',
      'geo.normals',
      'мешей без нормалей: ' + noNormal + ', с нулевыми/NaN нормалями: ' + badNormal
    );
    add(
      'INFO',
      'geo.flat',
      'мешей нулевой толщины: ' +
        meshes.filter(m => localMin(m) === 0).length +
        ' (плоский лист — валидная геометрия, но кандидат в копланары)'
    );

    // ── 4. Inflate: лестница смещений должна быть регулярной и ограниченной ────
    const withRec = meshes.filter(m => {
      const r = rec(m);
      return r && r.thickness != null;
    });
    if (withRec.length) {
      const devs = withRec.map(m => {
        const t = rec(m).thickness;
        m.geometry.computeBoundingBox();
        const s = m.geometry.boundingBox.getSize(new T.Vector3());
        return [s.x, s.y, s.z].map(v => v - t).reduce((a, b) => (Math.abs(a) < Math.abs(b) ? a : b));
      });
      const pos = devs.filter(d => d > 1e-6).sort((a, b) => a - b);
      const step = pos[0] || 0;
      const maxDev = pos[pos.length - 1] || 0;
      const steps = step > 0 ? Math.round(maxDev / step) : 0;
      const offGrid = step > 0 ? pos.filter(d => Math.abs(d / step - Math.round(d / step)) > 0.02).length : 0;
      const neg = devs.filter(d => d < -1e-6).length;
      add(
        maxDev <= CFG.maxInflate && steps <= CFG.maxInflateSteps && !offGrid && !neg ? 'PASS' : 'WARN',
        'geo.inflate',
        'шаг ' +
          step.toFixed(4) +
          ' мм, максимум ' +
          maxDev.toFixed(4) +
          ' мм (' +
          steps +
          ' ступеней); ' +
          'вне сетки ' +
          offGrid +
          ', отрицательных ' +
          neg,
        {
          нетронуто: devs.length - pos.length - neg,
          проверено: devs.length,
          порогМакс: CFG.maxInflate,
          порогСтупеней: CFG.maxInflateSteps
        }
      );
    } else {
      add('INFO', 'geo.inflate', 'userData.record.thickness отсутствует — проверка пропущена');
    }

    // ── 5. Копланарные грани среди непрозрачных, пишущих глубину ──────────────
    const occl = meshes
      .filter(m => {
        const x = [m.material].flat()[0];
        return x && x.depthWrite !== false && !x.transparent;
      })
      .map(m => {
        const b = new T.Box3().setFromObject(m);
        const s = b.getSize(new T.Vector3());
        return { m, b, s, min: Math.min(s.x, s.y, s.z), struct: isStruct(m) };
      });
    const tol = Math.max(dz(dFar) * 2, 0.01);
    const AX = ['x', 'y', 'z'];
    const planes = new Map();
    for (const x of occl) {
      if (x.min > CFG.thinMm) continue;
      const ai = x.s.x === x.min ? 0 : x.s.y === x.min ? 1 : 2,
        a = AX[ai];
      // min и max могут схлопнуться в один ключ у плоского листа — дедупим
      const keys = new Set([
        ai + ':' + Math.round(x.b.min[a] / tol),
        ai + ':' + Math.round(x.b.max[a] / tol)
      ]);
      for (const k of keys) {
        if (!planes.has(k)) planes.set(k, []);
        planes.get(k).push({ x, ai });
      }
    }
    let cop = 0,
      copStruct = 0;
    const seen = new Set(),
      worst = [];
    for (const arr of planes.values()) {
      if (arr.length < 2 || arr.length > 40) continue;
      for (let i = 0; i < arr.length; i++)
        for (let j = i + 1; j < arr.length; j++) {
          if (arr[i].x.m === arr[j].x.m) continue;
          const pk = [arr[i].x.m.id, arr[j].x.m.id].sort().join('-');
          if (seen.has(pk)) continue;
          const A = arr[i].x.b,
            B = arr[j].x.b,
            ai = arr[i].ai;
          const o1 = AX[(ai + 1) % 3],
            o2 = AX[(ai + 2) % 3];
          const ov = Math.min(A.max[o1], B.max[o1]) - Math.max(A.min[o1], B.min[o1]);
          const ow = Math.min(A.max[o2], B.max[o2]) - Math.max(A.min[o2], B.min[o2]);
          if (ov > 1 && ow > 1) {
            seen.add(pk);
            cop++;
            const both = arr[i].x.struct && arr[j].x.struct;
            if (both) copStruct++;
            if (both && worst.length < 12) {
              const ra = rec(arr[i].x.m),
                rb = rec(arr[j].x.m);
              worst.push(
                (ra ? ra.name + '#' + ra.id : '?') +
                  ' ↔ ' +
                  (rb ? rb.name + '#' + rb.id : '?') +
                  ' по ' +
                  AX[ai] +
                  ', ' +
                  Math.round(ov * ow) +
                  ' мм²'
              );
            }
          }
        }
    }
    add(
      copStruct === 0 ? (cop === 0 ? 'PASS' : 'INFO') : 'WARN',
      'geo.coplanar',
      'копланарных пар в пределах Δz=' +
        tol.toFixed(4) +
        ' мм: ' +
        cop +
        ', из них между несущими деталями: ' +
        copStruct +
        (cop > copStruct ? ' (остальное — внутри импорта и фурнитуры, косметика)' : ''),
      worst
    );

    // ── 6. Ориентации несущих деталей ────────────────────────────────────────
    const q = new T.Quaternion(),
      eu = new T.Euler();
    let aligned = 0,
      intentional = 0;
    const suspect = [];
    for (const m of structural) {
      eu.setFromQuaternion(m.getWorldQuaternion(q));
      const dev = Math.max(
        ...[eu.x, eu.y, eu.z].map(a => {
          const d = a * 57.29577951,
            r = ((d % 90) + 90) % 90;
          return Math.min(r, 90 - r);
        })
      );
      if (dev < CFG.alignEps) aligned++;
      else if (dev > CFG.alignSuspectMax) intentional++;
      else {
        const r = rec(m);
        suspect.push({ id: r && r.id, parent: r && r.parent_id, name: (r && r.name) || m.name, dev });
      }
    }
    // склеиваем близкие углы: одинаковое отклонение у пачки деталей = один сдвинутый узел,
    // разрозненные единичные углы = обычный шум трансформаций
    suspect.sort((a, b) => a.dev - b.dev);
    const clusters = [];
    for (const s of suspect) {
      const last = clusters[clusters.length - 1];
      if (last && s.dev - last.max <= Math.max(0.02, last.max * 0.05)) {
        last.items.push(s);
        last.max = s.dev;
      } else clusters.push({ min: s.dev, max: s.dev, items: [s] });
    }
    const big = clusters.filter(c => c.items.length >= CFG.alignClusterMin);
    add(
      big.length === 0 ? 'PASS' : 'WARN',
      'geo.alignment',
      'несущих по осям: ' +
        aligned +
        ', намеренно наклонённых (>' +
        CFG.alignSuspectMax +
        '°): ' +
        intentional +
        ', вне сетки (' +
        CFG.alignEps +
        '..' +
        CFG.alignSuspectMax +
        '°): ' +
        suspect.length +
        (big.length ? ' → кластеров: ' + big.length : ''),
      big.map(c => ({
        угол: c.min === c.max ? c.min.toFixed(3) + '°' : c.min.toFixed(3) + '..' + c.max.toFixed(3) + '°',
        объектов: c.items.length,
        родители: [...new Set(c.items.map(s => s.parent))],
        детали: c.items.map(s => s.name + '#' + s.id).slice(0, 30)
      }))
    );

    // ── 7. Ресурсы и производительность ──────────────────────────────────────
    const renderFrame = V?.render ? () => V.render() : () => R.render(S, C);
    renderFrame();
    if (CFG.skipPerf) {
      add(
        'INFO',
        'perf.frame',
        'замер кадра пропущен; ' +
          R.info.render.calls +
          ' draw calls, ' +
          R.info.render.triangles +
          ' треугольников'
      );
    } else {
      const t0 = performance.now();
      for (let i = 0; i < CFG.perfFrames; i++) renderFrame();
      gl.finish();
      const ms = (performance.now() - t0) / CFG.perfFrames;
      add(
        ms < 16.7 ? 'PASS' : ms < 33 ? 'WARN' : 'FAIL',
        'perf.frame',
        ms.toFixed(2) +
          ' мс/кадр, ' +
          R.info.render.calls +
          ' draw calls, ' +
          R.info.render.triangles +
          ' треугольников'
      );
    }
    add(
      R.info.memory.geometries <= meshes.length * 1.2 ? 'PASS' : 'WARN',
      'perf.geometries',
      R.info.memory.geometries + ' геометрий в памяти на ' + meshes.length + ' мешей'
    );

    // ── отчёт ────────────────────────────────────────────────────────────────
    const ord = { FAIL: 0, WARN: 1, INFO: 2, PASS: 3 };
    F.sort((a, b) => ord[a.lvl] - ord[b.lvl]);
    if (CFG.verbose) {
      const ic = { PASS: '✅', WARN: '⚠️', FAIL: '❌', INFO: 'ℹ️' };
      console.group('%cБАЗИС 3D — регрессионный чек', 'font-weight:bold;font-size:13px');
      for (const f of F) {
        const line = ic[f.lvl] + ' [' + f.id + '] ' + f.msg;
        const has = f.data && (Array.isArray(f.data) ? f.data.length : Object.keys(f.data).length);
        if (has) {
          console.groupCollapsed(line);
          console.log(f.data);
          console.groupEnd();
        } else console.log(line);
      }
      console.groupEnd();
    }
    const sum = {
      fail: F.filter(f => f.lvl === 'FAIL').length,
      warn: F.filter(f => f.lvl === 'WARN').length,
      pass: F.filter(f => f.lvl === 'PASS').length
    };
    sum.verdict = sum.fail ? 'FAIL' : sum.warn ? 'WARN' : 'PASS';
    if (CFG.verbose) {
      console.log(
        '%c' + sum.verdict + ' — ' + sum.pass + ' pass / ' + sum.warn + ' warn / ' + sum.fail + ' fail',
        'font-weight:bold;color:' + (sum.fail ? '#e5484d' : sum.warn ? '#f5a524' : '#30a46c')
      );
    }
    window.__bvcLast = F;
    return sum;
  }

  // Ключи из Python приходят в snake_case; наружу отдаём привычные имена.
  const MAP = {
    max_depth_ratio: 'maxDepthRatio',
    depth_safety: 'depthSafety',
    max_inflate: 'maxInflate',
    max_inflate_steps: 'maxInflateSteps',
    thin_mm: 'thinMm',
    structural_types: 'structuralTypes',
    skip_perf: 'skipPerf'
  };

  function install(context, options) {
    const doc = context.document;
    defaults = {};
    for (const [from, to] of Object.entries(MAP))
      if (options && options[from] != null) defaults[to] = options[from];
    root.basisCheck = basisCheck;

    const mount = context.extrasMount;
    if (!mount) return { name: 'regression', basisCheck };

    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const divider = doc.getElementById('regressionDivider'),
      button = doc.getElementById('regressionRun'),
      out = doc.getElementById('regressionStatus');
    button.onclick = async () => {
      button.disabled = true;
      out.textContent = 'Считаю…';
      try {
        const s = await basisCheck();
        out.textContent =
          s.verdict +
          ' — ' +
          s.pass +
          ' пройдено, ' +
          s.warn +
          ' предупреждений, ' +
          s.fail +
          ' провалов. Разбор в консоли.';
      } catch (error) {
        out.textContent = 'Не удалось: ' + error.message;
        console.error(error);
      }
      button.disabled = false;
    };
    mount.append(divider, button, out);
    return {
      name: 'regression',
      basisCheck,
      dispose() {
        divider.remove();
        button.remove();
        out.remove();
        doc.querySelector?.('style[data-feature="regression"]')?.remove();
        delete root.basisCheck;
      }
    };
  }

  const api = { install, basisCheck };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'regression', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);

