scripts:
(function (root) {
  'use strict';
  // Обновление просмотрщика прямо из опубликованной страницы. Новый код берётся из
  // viewer/kit.json того же сайта (его выкладывает команда выпуска, publish_viewer.py),
  // данные модели переносятся из этой страницы как есть, запись — через github_save
  // тем же токеном. Страница собирается ровно так, как её собрал бы сборщик
  // (viewer_kit.assemble): совпадение байт в байт проверяет test_viewer_kit.py.

  const KIT_SCHEMA = 1;
  // Порядок меток — как в viewer_kit.assemble. Замена всех вхождений, по очереди.
  // Имена без обрамления «__»: этот код сам вставляется в страницу по метке, и
  // метки, записанные в нём целиком, следующие шаги заменили бы прямо в нём.
  const MARKERS = [
    'THREE_JS',
    'ORBIT_JS',
    'FEATURE_JS',
    'FEATURE_CSS',
    'FEATURE_HTML',
    'MODEL_JSON',
    'DATA_MIME',
    'ASSET_MIME',
    'BOOTSTRAP',
    'STARTUP_JS',
    'TITLE',
    'THREE_LICENSE',
    'VIEWER_VERSION'
  ];

  function assemble(template, parts) {
    for (const name of MARKERS) template = template.split('__' + name + '__').join(parts[name]);
    return template;
  }

  // Как html.escape в Python: & < > " '
  const escapeHtml = text =>
    text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;');

  // Path(name).stem: без последнего расширения; имя из одной точки-префикса не режем
  const stem = name => {
    const base = String(name || '').replace(/^.*[\\/]/, '');
    const dot = base.lastIndexOf('.');
    return dot > 0 ? base.slice(0, dot) : base;
  };

  const applies = (when, scene) => !when.length || when.some(key => nonEmpty(scene[key]));
  const nonEmpty = value =>
    Array.isArray(value)
      ? value.length > 0
      : value && typeof value === 'object'
        ? Object.keys(value).length > 0
        : !!value;

  // Текст тегов собирается из частей: исходник этого модуля лежит в той же странице,
  // и буквальный «<script id=…» в нём нашёлся бы поиском вместо настоящего тега.
  const tag = id => '<' + 'script id="' + id + '"';
  const CLOSE = '</' + 'script>';

  function readPage(text) {
    const data = new RegExp(tag('modelData') + ' type="([^"]+)">([\\s\\S]*?)' + CLOSE).exec(text);
    if (!data) throw new Error('В странице нет данных модели.');
    const three = new RegExp(tag('threeSrc') + ' type="([^"]+)">').exec(text);
    if (data[1] !== 'text/plain' || !three || three[1] !== 'text/javascript')
      throw new Error('Страница собрана в другом режиме сжатия — обновите её локально (upgrade_html.py).');
    const safe = /defaultSafe\s*=\s*(?:\/\*DEFAULT_SAFE_GRAPHICS\*\/\s*)?(true|false)/.exec(text);
    // правки вида html_save кладёт в <head> — только там их и ищем
    const head = text.slice(0, text.indexOf('</head>'));
    const saved = new RegExp(tag('viewerSavedState') + '[^>]*>[\\s\\S]*?' + CLOSE).exec(head);
    return {
      payload: data[2],
      safeGraphics: !!safe && safe[1] === 'true',
      savedState: saved ? saved[0] : null
    };
  }

  // Разделы новых модулей вклеиваются в исходный текст данных: остальное остаётся
  // байт в байт (JSON.stringify всей сцены переписал бы числа: -0 → 0, 1.0 → 1).
  // Верхний "features" у сборщика — последний ключ сцены, после геометрии; если
  // первое вхождение оказалось не им, разбор это покажет, и страница не запишется.
  function withSections(raw, added, sections) {
    const key = '"features":{',
      at = raw.indexOf(key);
    if (at < 0) throw new Error('В данных модели нет разделов модулей — обновите страницу локально.');
    const open = at + key.length,
      before = Object.keys(JSON.parse(raw).features).length;
    const text =
      raw.slice(0, open) +
      added.map(name => JSON.stringify(name) + ':' + JSON.stringify(sections[name])).join(',') +
      (raw[open] === '}' ? '' : ',') +
      raw.slice(open);
    const check = JSON.parse(text).features;
    if (Object.keys(check).length !== before + added.length || !added.every(name => name in check))
      throw new Error('Не удалось добавить разделы модулей в данные — обновите страницу локально.');
    return text;
  }

  // Новая страница из текста текущей и набора кода. codec — {gunzip(base64) → текст,
  // gzip(текст) → base64}: в браузере потоки сжатия, в проверке — zlib.
  async function rebuild(pageText, kit, version, codec) {
    if (!kit || kit.kit_schema !== KIT_SCHEMA)
      throw new Error('Набор кода другого формата — обновите страницу локально (upgrade_html.py).');
    const page = readPage(pageText);
    const raw = await codec.gunzip(page.payload),
      scene = JSON.parse(raw);
    if ((scene.scene_schema || 1) > kit.scene_schema)
      throw new Error('Данные модели новее набора кода — выпустите новую версию просмотрщика.');
    const sections = scene.features || (scene.features = {});
    // Модули, которым данные модели не нужны, страница добавляет себе сама; прочие
    // новые модули требуют выгрузки из БАЗИСа (их разделы считает Python).
    const added = kit.features
      .filter(f => f.static && !(f.name in sections) && applies(f.static.when, scene))
      .map(f => f.name);
    for (const f of kit.features) if (added.includes(f.name)) sections[f.name] = f.static.data;
    const payload = added.length ? await codec.gzip(withSections(raw, added, sections)) : page.payload;
    const active = kit.features.filter(f => f.name in sections);
    const scripts = [],
      seen = new Set();
    for (const f of active) {
      for (const name of f.shared)
        if (!seen.has(name)) {
          seen.add(name);
          scripts.push(kit.shared[name]);
        }
      scripts.push(...f.scripts);
    }
    // как browser_styles / browser_markup в feature_registry.py
    const tagged = (field, element, attribute) => f =>
      f[field].map(t => '<' + element + ' ' + attribute + '="' + f.name + '">\n' + t + '</' + element + '>');
    let text = assemble(kit.template, {
      THREE_JS: kit.three,
      ORBIT_JS: kit.orbit,
      FEATURE_JS: scripts.join('\n'),
      FEATURE_CSS: active.flatMap(tagged('styles', 'style', 'data-feature')).join('\n'),
      FEATURE_HTML: active.flatMap(tagged('markup', 'div', 'data-feature-markup')).join('\n'),
      MODEL_JSON: payload,
      DATA_MIME: kit.data_mime,
      ASSET_MIME: kit.asset_mime,
      BOOTSTRAP: kit.bootstrap,
      STARTUP_JS: page.safeGraphics
        ? kit.startup.replace(/(\/\*DEFAULT_SAFE_GRAPHICS\*\/\s*)false/g, '$1true')
        : kit.startup,
      TITLE: escapeHtml(stem(scene.source)),
      THREE_LICENSE: kit.license,
      VIEWER_VERSION: version
    });
    // правки вида («Сохранить HTML») — последним элементом <head>, как их кладёт html_save
    if (page.savedState) text = text.replace('</head>', () => page.savedState + '</head>');
    return { text, added };
  }

  function install(context, data) {
    const { document: doc, window: win } = context;
    if (data?.schema !== 1) throw new Error('Несовместимый модуль обновления просмотрщика');
    const target = context.data.republish;
    let disposed = false;

    // Разметка — markup.html (сборщик кладёт её в #featureMarkup)
    const wrap = doc.getElementById('viewerUpdateTools'),
      button = doc.getElementById('viewerUpdate'),
      status = doc.getElementById('viewerUpdateStatus');
    (context.extrasMount || context.toolMount).append(wrap);

    const own = doc.querySelector?.('meta[name="bazis-viewer"]')?.getAttribute('content') || '';
    // Сайт публикации: страница лежит в <сайт>/models/<слаг>/index.html, набор — в <сайт>/viewer/
    const depth = String(target.path).split('/').length - 1;
    const kitUrl = name => new win.URL('../'.repeat(depth) + 'viewer/' + name, win.location.href).href;
    const online = /^https?:$/.test(win.location?.protocol || '');

    async function fetchJson(url) {
      const response = await win.fetch(url + '?t=' + Date.now(), { cache: 'no-store' });
      if (!response.ok) throw new Error('Не удалось получить ' + url + ' (' + response.status + ')');
      return response.json();
    }

    async function check() {
      if (!online) {
        status.textContent =
          'Версия просмотрщика ' + (own || 'неизвестна') + '. Обновление — на опубликованной странице.';
        return null;
      }
      try {
        const manifest = await fetchJson(kitUrl('manifest.json'));
        const fresh = manifest.version !== own;
        button.hidden = !fresh;
        status.textContent = fresh
          ? 'Есть новая версия просмотрщика: ' +
            manifest.version +
            ' (у страницы — ' +
            (own || 'старая') +
            ').'
          : 'Просмотрщик актуален (' + own + ').';
        return manifest;
      } catch (error) {
        status.textContent = 'Не удалось проверить версию просмотрщика: ' + error.message;
        return null;
      }
    }

    const codec = {
      async gunzip(encoded) {
        return (await root.BazisStartup.gunzip(encoded)).text();
      },
      async gzip(text) {
        const stream = new win.Blob([new win.TextEncoder().encode(text)])
          .stream()
          .pipeThrough(new win.CompressionStream('gzip'));
        const bytes = new Uint8Array(await new win.Response(stream).arrayBuffer());
        let binary = '';
        for (let i = 0; i < bytes.length; i += 0x8000)
          binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
        return win.btoa(binary);
      }
    };

    async function update() {
      const saver = ((win.__viewer && win.__viewer.features) || []).find(f => f.name === 'github_save');
      if (!saver || !saver.commitFile) {
        status.textContent = 'Нет модуля записи на GitHub — обновите страницу локально.';
        return null;
      }
      button.disabled = true;
      try {
        status.textContent = 'Скачиваю новую версию просмотрщика…';
        const manifest = await fetchJson(kitUrl('manifest.json'));
        const kit = await fetchJson(kitUrl('kit.json'));
        const response = await win.fetch(win.location.href.replace(/[?#].*$/, ''), { cache: 'no-store' });
        if (!response.ok) throw new Error('Не удалось прочитать эту страницу (' + response.status + ')');
        status.textContent = 'Собираю страницу…';
        const result = await rebuild(await response.text(), kit, manifest.version, codec);
        status.textContent = 'Записываю на GitHub…';
        const sha = await saver.commitFile(
          target.path,
          result.text,
          'Обнови просмотрщик ' + target.path + ' до ' + manifest.version
        );
        if (!sha) {
          status.textContent = 'Отменено.';
          return null;
        }
        status.textContent =
          'Просмотрщик обновлён (коммит ' +
          sha.slice(0, 7) +
          (result.added.length ? '; добавлено: ' + result.added.join(', ') : '') +
          '). GitHub Pages выложит страницу примерно через минуту — затем перезагрузите её.';
        return result;
      } catch (error) {
        status.textContent = error.message;
        return null;
      } finally {
        if (!disposed) button.disabled = false;
      }
    }

    button.onclick = update;
    button.hidden = true;
    check();
    return {
      name: 'viewer_update',
      version: own,
      check,
      update,
      dispose() {
        disposed = true;
        wrap.remove();
        doc.querySelector?.('style[data-feature="viewer_update"]')?.remove();
      }
    };
  }

  const api = { install, rebuild, assemble, readPage };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else (root.BazisViewerFeatures || (root.BazisViewerFeatures = [])).push({ name: 'viewer_update', install });
})(typeof globalThis !== 'undefined' ? globalThis : this);
